/* ⚠️ Нюансы по карточкам. window.NOTES (id → текст). */
window.NOTES = {
 "qk2-buildtime-di": "«Build-time» не значит «нельзя конфигурировать в рантайме». Значения @ConfigProperty читаются при запуске; build-time фиксируется только СТРУКТУРА графа бинов.",
 "qk2-cdi-scopes": "Нельзя инжектить @RequestScoped в @Singleton напрямую без прокси — получите устаревший/неправильный экземпляр. @ApplicationScoped (с прокси) такой проблемы лишён, поэтому в Quarkus он скоуп по умолчанию для CDI-бинов.",
 "qk2-client-proxy": "Прокси требует non-final класс с доступным no-arg конструктором. Финальный класс или только параметризованный конструктор → ошибка сборки ARC. Финальные методы прокси не перехватываются.",
 "qk2-inject-vs-autowired": "В Quarkus можно использовать и Spring-аннотации (@Autowired, @Component) через extension quarkus-spring-di, но под капотом всё равно работает ARC в build-time — это слой совместимости, не настоящий Spring.",
 "qk2-extension": "Deployment-модуль НЕ попадает в рантайм-classpath приложения — это частая путаница. Туда едет только runtime-артефакт.",
 "qk2-reflection-enemy": "В native при NoSuchMethodException/ClassNotFoundException на ровном месте первый подозреваемый — незарегистрированный для рефлексии класс. Лечится @RegisterForReflection или соответствующим extension.",
 "qk2-jvm-vs-native": "Native-сборка идёт долго (минуты) и жрёт много RAM на машине сборки — это бьёт по времени CI, а не по рантайму.",
 "qk2-closed-world": "В Quarkus большинство таких случаев уже закрыты экстеншенами на этапе build-time — твой собственный код с рефлексией закрывать надо вручную.",
 "qk2-register-for-reflection": "Аннотация регистрирует только сам класс. Если на полях вложенные типы, которые тоже идут через рефлексию, их регистрируют отдельно — иначе словишь падение на вложенном объекте.",
 "qk2-when-not-native": "Ловушка собеса: «native всегда быстрее» — неверно. Native быстрее ТОЛЬКО на старте; по установившемуся throughput разогретая JVM обычно впереди.",
 "qk2-aot-vs-jit": "GraalVM умеет и PGO (profile-guided optimization) для native: собрать профиль на инструментированном прогоне и пересобрать образ — это сужает разрыв с JIT, но фича из Oracle GraalVM, не из бесплатной community-сборки.",
 "qk2-uni-vs-multi": "Uni не равно «быстро/синхронно». Uni всё так же асинхронный — просто результат один. Путают именно семантику количества элементов, а не блокирующесть.",
 "qk2-imperative-vs-reactive": "Реактивный != автоматически быстрее. Если внутри Uni ты вызовешь блокирующий JDBC — ты заблокируешь event-loop и обрушишь throughput всего инстанса, а не одного запроса.",
 "qk2-blocking-annotation": "Самый частый прод-баг: вернуть Uni и забыть @Blocking при вызове блокирующей зависимости. Под нагрузкой инстанс деградирует не точечно, а целиком — все event-loop потоки заняты.",
 "qk2-reactive-messaging-kafka": "По умолчанию ack стратегия может коммитить оффсет до завершения обработки. Если нужна гарантия «обработал → закоммитил», управляй ack вручную через Message или настраивай commit/failure-strategy, иначе при падении потеряешь сообщение.",
 "qk2-virtual-threads": "Pinning: если внутри виртуального потока попасть в synchronized-блок или нативный код во время блокировки, поток «пришпиливается» к carrier и теряет преимущество. Используй ReentrantLock вместо synchronized на горячих путях.",
 "qk2-backpressure-multi": "Безграничный буфер по умолчанию — путь к OutOfMemoryError под нагрузкой. На горячих источниках всегда явно задавай onOverflow с лимитом, а не надейся, что «само сдержит».",
 "qk2-panache-ar-vs-repo": "Active record статические методы (Order.findById) сложно мокать в юнит-тестах — приходится тащить тяжёлый интеграционный тест с реальной БД.",
 "qk2-hibernate-reactive-vs-blocking": "Смешивать нельзя бездумно: блокирующий JDBC-вызов внутри реактивного event-loop треда подвесит весь event loop. Quarkus даже кидает BlockingOperationNotAllowedException.",
 "qk2-transactional-narayana": "Самоинвокация: если @Transactional-метод вызвать из другого метода ТОГО ЖЕ бина напрямую (this.save()), перехватчик не сработает и транзакции не будет — классический грабли на проде.",
 "qk2-dev-services": "Нужен запущенный Docker/Podman. На CI-агентах без Docker-in-Docker Dev Services упадут — там обычно задают реальные URL переменными окружения.",
 "qk2-flyway-liquibase": "В кластере из N инстансов все стартуют одновременно и пытаются мигрировать — и Flyway, и Liquibase берут lock на служебной таблице, чтобы миграцию выполнил ровно один под. Но долгая миграция всё равно задержит старт всех.",
 "qk2-mpconfig-sources": "Если свойство обязательно (нет defaultValue и тип не Optional) и его нигде нет — приложение упадёт при старте с DeploymentException, а не вернёт null.",
 "qk2-profiles": "%test читается только из application.properties в тестовом classpath; на проде файл с %test-ключами безвреден — они просто не активируются.",
 "qk2-buildtime-runtime": "Частая ловушка: в Docker подменяют `quarkus.datasource.db-kind` через env и удивляются, что не работает — это build-time свойство, оно зашито при `mvn package`.",
 "qk2-devmode-livereload": "Если правка ломает компиляцию, ошибка прилетит прямо в браузер как красивый exception page при следующем запросе — это нормально для dev mode.",
 "qk2-continuous-testing": "Continuous testing использует тестовый профиль (%test) и Dev Services — поведение может отличаться от прода, если конфиг сильно завязан на профиль.",
 "qk2-packaging": "Свойство переименовано: актуально `quarkus.package.jar.type`, старое `quarkus.package.type` помечено deprecated в Quarkus 3.x — на собесе легко спалиться устаревшим ключом.",
 "qk2-fault-tolerance": "@Retry на неидемпотентном вызове (например, POST «создать заявку») может задвоить операцию. Ретраить безопасно только идемпотентные вызовы или защищать ключом идемпотентности.",
 "qk2-health-probes": "Классическая ошибка — пихать проверку внешней БД в @Liveness. Тогда при недоступной БД Kubernetes будет бесконечно перезапускать здоровый под. Внешние зависимости — только в @Readiness.",
 "qk2-micrometer-otel": "Полный сэмплинг трейсов на проде дорог: 100% трейсинг под нагрузкой бьёт по латентности и стоимости хранения. На проде включают сэмплинг (например, 5–10% запросов).",
 "qk2-openapi-swagger": "По умолчанию Swagger UI доступен только в dev-режиме. Чтобы открыть его на проде, нужно явно `quarkus.swagger-ui.always-include=true` — и подумать, не светишь ли ты внутренний API наружу.",
 "qk2-vs-springboot": "Главный аргумент Quarkus — быстрый холодный старт — почти не значим для долгоживущего сервиса, который рестартует раз в неделю. Он критичен в serverless/частом скейле, а не везде подряд.",
 "qk2-oidc-keycloak": "В bearer-режиме сервис доверяет подписи, а не вызывает Keycloak на каждый запрос — это плюс к скорости, но просроченный/отозванный токен валиден до истечения exp. Для мгновенного отзыва нужен короткий TTL токенов или introspection.",
 "ap-ambassador": "⚠️ Лишний сетевой хоп и второй процесс на каждый инстанс — это +latency и +эксплуатация. Для пары вызовов проще обычная библиотека (Resilience4j) прямо в коде. Ambassador окупается на polyglot-зоопарке и когда сетевую политику хотят менять без передеплоя сервиса.",
 "ap-claim-check": "⚠️ Главные грабли — жизненный цикл объекта. Удалишь тело раньше, чем консьюмер (или ретрай DLQ) его прочитал — получишь битую ссылку. И наоборот: забыл TTL — стор пухнет от старых payload. Также появляется eventual-consistency окно: ссылка в топике уже есть, а объект в стор ещё не долетел (пиши в стор ДО отправки сообщения).",
 "ap-scatter-gather": "⚠️ Без таймаута и лимита параллелизма scatter-gather превращается в усилитель отказов: один залипший провайдер держит все запросы, пул потоков/соединений выгорает, latency взлетает по worst-case. Обязательны per-call timeout, общий дедлайн и стратегия частичного ответа. И помни: ждать «всех» = твоя задержка равна задержке самого медленного.",
 "ap-competing-consumers": "⚠️ Частая ошибка — масштабировать консьюмеров там, где бизнес требует строгого порядка (например, события по одному счёту: «открыт → пополнен → закрыт»). Параллельные воркеры переставят их и сломают инвариант. Лечится партиционированием по ключу сущности (все события счёта X → одна партиция → один консьюмер), но тогда параллелизм упирается в число партиций.",
 "ap-event-carried-state": "⚠️ Дублированные данные = риск рассинхрона: пропущенное/переупорядоченное событие оставит у потребителя устаревшую копию. Нужны идемпотентность, версии/timestamp для отбрасывания старых апдейтов и механизм re-sync (снапшот/реплей). И не пихай в событие весь агрегат «на всякий» — раздутая схема становится хрупким публичным контрактом, который больно менять.",
 "ap-p2p-vs-pubsub": "⚠️ Грабли — перепутать модель под задачу. Шлёшь команду «спиши деньги» в pub/sub-топик с несколькими подписчиками — спишут несколько раз. И наоборот: льёшь доменное событие в p2p-очередь — его съест один консьюмер, остальные заинтересованные ничего не узнают. Правило: команда (сделай) → точка-в-точку одному владельцу; событие (случилось) → pub/sub всем, кому интересно.",
 "ap-bulkhead": "⚠️ Слишком много мелких пулов = фрагментация: суммарно потоков выделено много, но каждый пул мал и упирается в лимит при всплеске, хотя соседние простаивают. И семафорный bulkhead НЕ спасает от зависших блокирующих вызовов — он ограничивает число входящих, но сам зависший поток никуда не девается; нужен thread-pool вариант + таймаут.",
 "ap-resilience-stack": "⚠️ Главная ловушка — Retry + Circuit Breaker без согласования. Если retry агрессивный, а CB настроен на процент ошибок, ретраи могут «накрутить» успехи и не дать цепи открыться, продолжая бить по падающему downstream. И никогда не ретрайте, когда CB уже открыт — это бессмысленная нагрузка; ставьте retry над CB, чтобы он сразу видел open и не повторял.",
 "ap-failfast-vs-degrade": "⚠️ Опасность «тихой деградации»: отдаёте устаревший/неполный ответ, но клиент об этом не знает и принимает решение по неверным данным (старая цена, неактуальный баланс). Деградация обязана быть наблюдаемой — метрика/флаг в ответе/лог, иначе вы маскируете инцидент и узнаёте о нём от пользователей.",
 "ap-load-shedding": "⚠️ Load shedding бесполезен, если сброшенные клиенты тут же ретраят без backoff — вы отказали, но нагрузка не упала. Поэтому он работает ТОЛЬКО в паре с дисциплиной на клиенте (jitter backoff, retry budget) и сбросом ДО захвата дорогих ресурсов. Сброс после похода в БД уже бессмыслен — ресурс потрачен.",
 "ap-retry-budget": "⚠️ Per-request retry count (3 попытки) кажется безопасным, но это и есть главный механизм retry-storm и cascading failure: при сбое 1000 запросов мгновенно становятся 3000. Реальная защита — именно бюджет на агрегат + jitter. И ретраить можно только идемпотентные операции, иначе повтор задвоит платёж/заказ.",
 "ap-sidecar-ambassador-adapter": "⚠️ Лишний контейнер на каждый под — это удвоение числа процессов, рост latency на хоп и боль отладки («где сломалось — в app или в sidecar?»). Не лепи sidecar ради одной фичи, которую проще встроить библиотекой. Sidecar оправдан, когда забота общая для МНОГИХ сервисов на разных языках — тогда выгоднее один контейнер, чем N библиотек.",
 "ap-service-discovery": "⚠️ Главная боль обоих — устаревший реестр: инстанс умер, но ещё числится живым, и трафик летит в труп. Спасают health-чеки и TTL/heartbeat, но между падением и его обнаружением есть окно ошибок — клиент обязан иметь retry на другой инстанс. Client-side к тому же привязывает тебя к стеку (Eureka-клиент есть не везде), поэтому в k8s по умолчанию берут server-side.",
 "ap-saga-orchestration-vs-choreography": "⚠️ Главный капкан saga — отсутствие изоляции: между шагами промежуточное состояние ВИДНО другим (деньги уже списаны, товар ещё не зарезервирован) — это аномалии вроде грязного чтения, их гасят семантическими блокировками и флагами «в процессе». И компенсации обязаны быть идемпотентны и почти всегда успешны: если refund сам упал, у тебя нет «компенсации компенсации» — нужен ручной разбор и алерт.",
 "jc-eqhash": "Симметричный подвох: если переопределить hashCode так, что у равных объектов он совпадает, но забыть equals — объект найдётся в нужном бакете, но Map всё равно сочтёт его другим (по дефолтному ==). Правило: equals и hashCode переопределяют ВСЕГДА вместе. И не клади в HashMap/HashSet мутабельный ключ: изменил поле после put — hashCode поменялся, объект «потерялся» в старом бакете.",
 "jc-erasure": "Стирание ломает перегрузку: два метода foo(List<String>) и foo(List<Integer>) не скомпилируются — после erasure это один и тот же foo(List). И «непроверяемое» приведение (List)obj к List<String> проходит без ошибки — ClassCastException вылетит позже, в точке реального чтения элемента.",
 "jc-strpool": "Конкатенация констант («a»+«b») сворачивается компилятором в литерал и попадает в пул, а склейка с переменной (s+«b») создаёт новый объект в куче — поэтому ==  с таким результатом неожиданно даёт false. Сравнивай строки только через equals.",
 "jc-intcache": "Грабли не только в ==: Integer в коллекции unboxing-ом может кинуть NPE, если значение null (Map.get вернул null, а его присваивают в int). Нижнюю границу кэша (-128..127) менять нельзя, верхнюю можно поднять через -Djava.lang.Integer.IntegerCache.high — но полагаться на это в коде нельзя.",
 "jc-twr": "Подвох порядка: ресурсы в try-with-resources закрываются в ОБРАТНОМ порядке объявления, и если close() кинет исключение, оно подавляется (suppressed) — основное исключение из тела не теряется, но его легко не заметить в логах. Достать подавленные можно через Throwable.getSuppressed().",
 "jc-hashmap-resize": "initialCapacity задаётся как «сколько бакетов», а не «сколько элементов»: чтобы вместить N без resize, бери capacity = N/0.75 + 1. И HashMap не потокобезопасен — параллельный put при resize в старых JDK (до 8) мог зациклить список в бакете и повесить CPU на 100%.",
 "jc-failfast": "Fail-fast не гарантирован: modCount проверяется на best-effort, в многопоточном доступе CME может и не выстрелить, а данные молча повредятся. Удалять во время обхода безопасно только через iterator.remove() или removeIf().",
 "jc-map-impls": "TreeMap сравнивает ключи через compareTo/Comparator, а НЕ через equals — если compareTo несогласован с equals, два «равных» по equals ключа окажутся разными в TreeMap (и наоборот). LinkedHashMap для LRU включается конструктором accessOrder=true плюс переопределением removeEldestEntry.",
 "jc-stream-lazy": "Из-за лени побочные эффекты в map/peek могут вообще не выполниться, если терминалка коротко замыкается (findFirst, limit, anyMatch). Никогда не клади бизнес-логику в peek — она задумана только для отладки и может быть пропущена оптимизатором.",
 "jc-parallel-stream": "Размер commonPool по умолчанию = числу ядер минус 1, и он общий на всю JVM — один тяжёлый parallelStream блокирует параллельные стримы в других частях приложения. Чтобы изолировать, запускай parallel-стрим внутри собственного ForkJoinPool через submit().",
 "jc-stream-collectors": "Collectors.toMap кидает IllegalStateException при дубликатах ключей — нужен третий аргумент mergeFunction. А groupingBy по умолчанию даёт HashMap с непредсказуемым порядком; для значения-null в toMap будет NPE (HashMap.merge не любит null-значения).",
 "jc-funciface": "Интерфейс с одним абстрактным методом остаётся функциональным, даже если переопределяет public-метод Object (equals/toString/hashCode) — они не считаются абстрактными для SAM. Поэтому Comparator с его equals() — валидный функциональный интерфейс.",
 "jc-lambda-anon": "Захват this лямбдой держит ссылку на внешний объект — лямбда, сохранённая в долгоживущем поле/листенере, не даст внешнему объекту собраться GC (утечка). Анонимный класс с захватом — та же проблема плюс собственный hidden-ref на enclosing instance.",
 "jc-default-methods": "Правило разрешения конфликтов: класс бьёт интерфейс, более конкретный интерфейс бьёт более общий, иначе — ошибка компиляции и ручной выбор Iface.super.method(). Default-метод нельзя сделать из метода Object (equals/hashCode/toString) — компилятор запрещает.",
 "jc-static": "Статик-инициализация ленивая и потокобезопасная (JVM гарантирует один раз под блокировкой) — на этом построен идиом «holder» для ленивого синглтона. Но циклическая зависимость между static-блоками двух классов даёт частично инициализированный класс с тихими null/0, а не ошибку.",
 "jc-reflection": "С Java 9+ (модули) и строгой инкапсуляцией setAccessible(true) на чужой пакет кидает InaccessibleObjectException без явного opens/--add-opens — частая причина падений Hibernate/Jackson при переезде на новый JDK.",
 "jc-error-exc": "Не лови Throwable/Error «на всякий случай»: поймав OutOfMemoryError или StackOverflowError, ты продолжишь работу в неконсистентном состоянии. Отдельный коварный случай — перехват Exception проглатывает InterruptedException, ломая корректное прерывание потоков (нужно восстановить флаг: Thread.currentThread().interrupt()).",
 "jc-catch-order": "Multi-catch (A | B) не допускает родственные типы в одном блоке — только несвязанные иерархией, иначе ошибка компиляции про избыточность. А ловить голый Exception ради «надёжности» опасно: он проглотит и RuntimeException-баги, которые должны были упасть.",
 "jc-immutable-howto": "Без defensive copy immutable «протекает»: если в конструктор передали List и сохранили ссылку напрямую, вызывающий код продолжит менять внутренности через свою ссылку. Также final-поле гарантирует видимость без synchronized только при правильной публикации — частично сконструированный объект (this уходит из конструктора) видимость ломает.",
 "x-java-comparable-comparator": "Главный незаметный баг — нарушение контракта compareTo (не транзитивен / не антисимметричен): Collections.sort кинет «Comparison method violates its general contract!» только на определённых данных, в проде и не на всех. NaN и -0.0 ломают наивное сравнение double — используй Double.compare.",
 "x-java-string-immutable-builder": "StringBuilder не потокобезопасен (в отличие от StringBuffer), но Buffer в проде почти не нужен — общий билдер между потоками это всё равно ошибка дизайна. И substring с Java 7u6 копирует символы (раньше делил массив с оригиналом и держал большую строку в памяти — классическая старая утечка).",
 "x-java-stream-collectors-vs-reduce": "Даже groupingBy на параллельном стриме безопасен только с конкуррентным коллектором (groupingByConcurrent) и неупорядоченным стримом; обычный groupingBy в parallel работает, но сливает мапы через merge — дороже. Мутабельный аккумулятор в reduce — гонка и потеря данных.",
 "jc-transient": "transient вместе с дефолтной сериализацией требует ручного восстановления поля в readObject (или оно навсегда останется null/0). Частая ловушка: помечают transient поле, а потом удивляются NPE после десериализации, потому что не дописали readResolve/readObject.",
 "jc-var": "var выводит наиболее КОНКРЕТНЫЙ тип, а не тот, что ожидаешь: var x = new ArrayList<>() даёт ArrayList<Object>, а var s = condition ? «a» : 1 — общий супертип. С var нельзя var x = null и нельзя var в полях/параметрах/возврате метода.",
 "jc-switch-expr": "switch-выражение должно быть исчерпывающим (для enum/sealed компилятор требует покрыть все ветки или default) — это его плюс. Но если используешь старый синтаксис с двоеточием внутри switch-выражения, проваливание (fall-through) сохраняется; со стрелкой -> его нет.",
 "jc-sealed": "Все permits-наследники должны быть в том же модуле (или пакете для unnamed module) и каждый обязан быть sealed, non-sealed или final — иначе ошибка компиляции. Именно закрытость иерархии даёт компилятору исчерпывающую проверку switch без default.",
 "jc-pattern-match": "Связанная instanceof-переменная видна только там, где проверка гарантированно true (flow scoping): в if(!(o instanceof String s)) return; переменная s доступна ПОСЛЕ if — это часто удивляет. В switch с pattern null надо обрабатывать явной веткой case null, иначе NPE.",
 "jc-nested-classes": "Нестатический inner class держит скрытую ссылку на внешний объект — это частая причина утечек памяти (например, non-static листенер не даёт собрать Activity/сервис) и проблем при сериализации. Правило: если внутреннему классу не нужен внешний объект — делай его static.",
 "jc-enum-adv": "enum гарантированно синглтон даже при сериализации и рефлексии — поэтому это лучший способ реализовать синглтон (Effective Java). values() возвращает новый массив-копию на каждый вызов (дорого в цикле), а ordinal() нельзя сохранять в БД — перестановка/вставка констант сдвинет все номера.",
 "jc-method-ref": "Тонкость: Class::instanceMethod (неконнектед) первым аргументом подставляет сам объект-приёмник — String::length это s -> s.length(). Method reference на метод объекта (obj::m) захватывает obj в момент создания ссылки, а не при вызове — если obj потом переназначат, ссылка всё равно зовёт старый.",
 "jc-assert": "Никогда не пиши в assert выражение с побочным эффектом (assert list.remove(x)) — при выключенных ассершенах (а в проде они выключены по умолчанию) код просто не выполнится, и поведение разойдётся между dev и prod.",
 "jc-modules": "Сильная инкапсуляция модулей ломает рефлексию: чтобы Jackson/Hibernate/Spring добрались до private через setAccessible, пакет надо открыть через opens (в module-info) или флаг --add-opens при запуске — иначе InaccessibleObjectException. Это главная боль миграции на JPMS.",
 "jc-datetime": "LocalDateTime НЕ хранит таймзону — арифметика по нему игнорирует переход на летнее время; для «настенного времени с зоной» нужен ZonedDateTime. Instant же — точка на оси UTC. Период Period.between считает в календарных единицах (месяц ≠ 30 дней), Duration — в фиксированных секундах.",
 "g-java-finalize-clone": "Object.clone() в обход конструктора не инициализирует final-поля штатно и игнорирует инварианты — поэтому почти всегда предпочитают копирующий конструктор/фабрику. При наследовании clone() легко отдаёт объект подкласса с типом суперкласса либо ломается, если потомок не реализует Cloneable.",
 "g-java-comparator-nulls": "thenComparing(A::field) с примитивным геттером требует перегрузки thenComparingInt/Long/Double — иначе лишний боксинг или неоднозначность вывода типов. Сам компаратор с null-ключами без nullsFirst/nullsLast кинет NPE прямо в момент сортировки, а не при создании.",
 "g-java-varargs-trap": "method(null) при varargs передаёт null как весь МАССИВ (часто NPE внутри), а не как один элемент — чтобы передать «один null-элемент», нужен явный каст: method((T) null). Generic varargs провоцируют heap pollution; @SafeVarargs ставят только когда реально не пишут в массив.",
 "g-java-enummap-weakhashmap": "WeakHashMap чистит запись, когда GC собрал КЛЮЧ, но если значение держит сильную ссылку на ключ — запись не освободится никогда (классическая утечка). И WeakHashMap не потокобезопасен; для кэшей по weak-ссылкам в проде чаще берут Caffeine/Guava Cache.",
 "g-java-final-vars": "final у переменной-ссылки не делает объект неизменяемым — final List всё ещё можно .add(). Effectively final: переменную нельзя менять после инициализации, иначе лямбда/анонимный класс её не захватит — типичная ошибка «менять счётчик в лямбде внутри цикла» не компилируется.",
 "g-java-object-methods": "Использование getClass() в equals ломает симметрию с подклассами, а instanceof — нарушает её для прокси/Hibernate-сущностей (ленивый прокси не равен реальному). Нестабильный hashCode (зависит от мутабельного поля) приводит к тому, что объект «пропадает» из HashSet после изменения.",
 "g-java-checked-streams": "Обёртка checked в RuntimeException внутри лямбды теряет тип в сигнатуре — вызывающий не обязан его ловить, и исключение всплывёт в неожиданном месте. Альтернатива «sneaky throws» (через дженерик-трюк или Lombok @SneakyThrows) компилируется, но прячет checked от компилятора — спорная практика.",
 "g-java-compact-intern": "intern() кладёт строки в пул на Java-куче (с Java 7 — не в нативной памяти/PermGen, интернированные строки подлежат GC). На больших объёмах уникальных строк это раздувает heap и даёт contention на StringTable. Для дедупликации одинаковых строк в куче правильнее включить -XX:+UseStringDeduplication у G1, а не звать intern() руками.",
 "ds-acks": "acks=all сам по себе НЕ гарантирует надёжность: при дефолтном min.insync.replicas=1 «все ISR» может означать одну живую реплику (лидер), и падение её теряет данные. Реальная гарантия — только связка acks=all + min.insync.replicas=2 при RF=3.",
 "ds-idempotent": "Идемпотентность по бизнес-ключу заказа недостаточна, если в обработке есть несколько разных побочных эффектов (запись в БД + отправка письма + вызов внешнего API): часть из них при повторе выполнится снова. Идемпотентным должен быть каждый side-effect, а не только финальная запись.",
 "ds-outbox": "Outbox даёт at-least-once, а не exactly-once: relay может отправить сообщение и упасть до отметки 'sent'. Без идемпотентного консьюмера на принимающей стороне outbox неполноценен. Плюс публикация из outbox может переупорядочить события относительно их записи, если не сохранять порядок по ключу.",
 "ds-rebalance": "Частая неочевидная причина бесконечных ребалансов — не падение инстансов, а превышение max.poll.interval.ms из-за долгой обработки батча: консьюмер 'живой' по heartbeat, но брокер считает его зависшим и выкидывает, его коммит падает, батч переобрабатывается. Лечится уменьшением max.poll.records или static membership.",
 "ds-partkey": "Порядок сохраняется только пока число партиций неизменно: при увеличении партиций распределение ключей по hash меняется, и сообщения одного ключа могут уйти в другую партицию — гарантия порядка для старых ключей ломается. Менять partition count в проде у топика с порядком нельзя безболезненно.",
 "ds-cap": "На практике выбор не бинарный 'CP или AP', а PACELC: даже без сетевого разрыва есть компромисс латентность-vs-консистентность (Else: Latency or Consistency). Большинство 'CP'-систем на самом деле отдают согласованность только при кворуме и деградируют в недоступность, а не магически остаются и C, и A.",
 "p-saga-three-axes": "Choreographed-саги на eventual consistency коварны отсутствием явного оркестратора: при росте числа шагов логика 'кто кого триггерит' размазывается по сервисам, и отследить/отладить полную цепочку и точку отказа становится почти невозможно — отсюда тяга вернуться к orchestrated при >3-4 шагах.",
 "p-outbox-polling-vs-cdc": "CDC через Debezium снимает polling, но добавляет свои грабли: при failover/перезапуске коннектора возможна повторная публикация уже отправленных изменений (at-least-once на уровне CDC), плюс snapshot большой таблицы при первом старте может надолго залочить или нагрузить БД. Идемпотентность потребителя всё равно обязательна.",
 "p-kafka-inflight-order": "Частая ошибка — ради сохранения порядка ставить max.in.flight=1, теряя throughput. С enable.idempotence=true порядок гарантируется и при max.in.flight=5, потому что брокер восстанавливает его по sequence number. Снижать in-flight до 1 не нужно.",
 "p-kafka-schema-compat": "BACKWARD-совместимость по умолчанию проверяет только последнюю схему, а не всю историю — чтобы консьюмер мог читать данные любых старых версий, нужен BACKWARD_TRANSITIVE. Обычный BACKWARD пропустит ломающую цепочку из нескольких последовательных эволюций.",
 "p-idempotent-sametx": "INSERT message_id в processed_messages работает, только если он в ТОЙ ЖЕ транзакции, что и бизнес-запись, и в той же БД. Если бизнес-эффект — внешний HTTP-вызов или другая БД, транзакционной атомарности нет, и дедуп-таблица не спасёт от частичного повтора.",
 "p-cb-timeout": "Дополнительный подвох: @Timeout в MicroProfile исполняет вызов в отдельном потоке и прерывает его через interrupt — если код не реагирует на InterruptedException (например, висит в нативном сокете без socket timeout), поток не освободится. Нужен ещё и реальный таймаут на уровне HTTP-клиента/драйвера.",
 "p-cqrs-staleness": "Костыль 'после записи читать с write-стороны для read-your-writes' ломает саму идею CQRS и не масштабируется. Правильные приёмы: версионный токен/таймстемп в ответе команды, по которому read-сторона ждёт догона проекции, либо оптимистичное обновление UI из ответа команды, а не из read-модели.",
 "p-kafka-poison-hol": "Retry-топик с задержкой ломает гарантию порядка для ключа отравленного сообщения: пока оно крутится в retry, последующие сообщения того же ключа из основной партиции уже обработаны — получается out-of-order по сущности. Для строгого порядка по ключу DLQ-подход с пропуском применять нельзя.",
 "g-ds-idempotent-producer": "Идемпотентность продьюсера гарантирует exactly-once только в пределах одной сессии: PID выдаётся заново при перезапуске приложения, поэтому сообщения, отправленные до падения и повторённые после рестарта, дедупом не покрываются. Защита от дублей при рестарте — только транзакции (transactional.id) или идемпотентный консьюмер.",
 "g-ds-maxpoll": "Ключевая ловушка: session.timeout.ms и max.poll.interval.ms — два независимых таймаута. Увеличение session.timeout не спасёт от вылета по долгой обработке; тюнить надо именно max.poll.interval.ms (или уменьшать max.poll.records). Их часто путают.",
 "g-ds-cooperative": "Переход eager→cooperative-sticky нельзя делать одномоментным рестартом: смешанная группа с разными протоколами назначения несовместима. Нужен rolling через промежуточную конфигурацию (оба протокола в partition.assignment.strategy), иначе группа не соберётся.",
 "g-ds-static": "Static membership имеет обратную сторону: если под реально умер (не рестарт), его партиции простаивают до истечения session.timeout.ms — а его обычно повышают для static membership. Слишком большой session.timeout = долгий простой партиций при настоящем падении инстанса.",
 "g-ds-quorum": "R+W>N гарантирует пересечение наборов, но НЕ линеаризуемость без дополнительных мер: при сбойных записях (записалось на часть реплик и оборвалось) чтение может вернуть значение, которого 'официально' не было, плюс конкурентные записи требуют разрешения конфликтов (last-write-wins теряет данные, vector clocks/CRDT — нет).",
 "g-ds-2pc": "Главный практический изъян 2PC даже сверх блокировки — окно неопределённости участника: если координатор упал ПОСЛЕ его 'готов', но до решения, участник не имеет права ни закоммитить, ни откатить и держит локи до восстановления координатора. Именно это (а не сама двухфазность) делает 2PC опасным для доступности.",
 "p-stream-event-vs-proc-time": "Даже event-time из payload требует механизма watermark/allowed lateness для оконных агрегаций: опоздавшие события могут прийти после закрытия окна и быть молча потеряны. А DEFAULT now() на стороне БД спасает от рассинхрона часов, но не от ситуации, когда нужен именно момент бизнес-события, а не момент записи.",
 "p-trace-propagation-islands": "Частая причина 'островов' даже при наличии библиотеки трейсинга — асинхронные границы: при уходе работы в тред-пул, @Async, reactive-цепочку или Kafka-консьюмер контекст трейса не переносится автоматически вместе с задачей и теряется на смене потока. Нужна явная пропагация контекста через executor/messaging-инструментацию.",
 "te-mock-stub": "Грань размыта: в Mockito один объект и стабит (when), и верифицируется (verify). Грабли — over-verification: когда verify проверяет каждый внутренний вызов, тест ломается при любом рефакторинге, хотя поведение наружу не изменилось. Verify только для side-effect'ов без видимого результата.",
 "te-testcontainers": "Не поднимай новый контейнер на каждый тест-класс — старты Docker съедят минуты в CI. Используй reuse (testcontainers.reuse.enable) или singleton-паттерн со static-контейнером и ручным стартом, и чисти данные между тестами через truncate/rollback, а не пересоздание контейнера.",
 "te-flaky": "Частый источник на проде/CI — зависимость от системного времени и таймзоны (тест зелёный днём, красный после полуночи UTC), порядок Map/Set без сортировки, и общая БД при параллельном прогоне. Лечится фиксированным Clock, явной сортировкой и изоляцией данных, а не @Retry — ретрай прячет реальный баг.",
 "te-captor": "ArgumentCaptor захватывает ссылку, а не снимок: если код мутирует тот же объект после вызова мока, captor увидит ФИНАЛЬНОЕ состояние, а не то, что было в момент вызова. Для мутабельных аргументов это даёт ложно-зелёный/ложно-красный тест.",
 "x-te-spring-slices": "@WebMvctest и @DataJpaTest поднимают только свой слой — бины из других слоёв (сервисы в контроллере) надо мокать через @MockBean, иначе контекст не стартует. И @DataJpaTest по умолчанию откатывает транзакцию и подменяет datasource на embedded — чтобы он шёл против Testcontainers, нужен @AutoConfigureTestDatabase(replace=NONE).",
 "x-te-test-fixtures": "@BeforeAll/@AfterAll по умолчанию требуют static-метода, потому что по умолчанию JUnit5 создаёт новый экземпляр теста на каждый метод (PER_METHOD). С @TestInstance(PER_CLASS) можно сделать их нестатическими, но тогда поля инстанса шарятся между тестами — риск test pollution.",
 "g-te-spy-vs-mock": "Классическая ловушка spy: when(spy.foo()).thenReturn(x) РЕАЛЬНО вызовет foo() при стабинге (может кинуть исключение или сходить в БД). Для spy надо doReturn(x).when(spy).foo(). Плюс spy не перехватывает вызовы метода ИЗ другого метода того же объекта (this.foo() мимо прокси).",
 "g-te-mutation": "Мутационное тестирование медленное (прогоняет сьют на каждый мутант), поэтому на больших модулях гоняй инкрементально (PIT с историей/только по диффу), иначе CI встанет. И не гонись за 100% mutation score — эквивалентные мутанты (семантически идентичный код) убить нельзя в принципе.",
 "g-te-awaitility": "Awaitility ловит только ПЕРЕХОД в нужное состояние, но не отлавливает, что условие на миг стало истинным и сразу сломалось обратно. Для таких случаев нужен await().during(...).atMost(...) либо проверка стабильности. И не забывай pollInterval — слишком частый опрос грузит CPU/БД.",
 "g-te-test-isolation": "@DirtiesContext чинит загрязнение контекста, но пересоздаёт весь Spring-контекст — это убивает скорость сьюта, поэтому это крайняя мера. Предпочтительнее @Transactional-откат или ручной reset мока (Mockito.reset/@MockBean переинициализируется автоматически). А static-поля откат транзакции не чистит вообще.",
 "g-te-strict-stubs": "UnnecessaryStubbingException срабатывает и при опечатке в аргументе матчера: when(mock.find(eq(1L))) не сматчился, потому что код зовёт find(2L) — Mockito жалуется на лишний стаб, хотя реальная причина в несовпадении аргумента. Читай: стаб не сработал, а не просто удали его.",
 "p-hex-inject-clock": "Инжектишь именно java.time.Clock, а не LocalDate — тогда в тесте Clock.fixed(instant, zone) воспроизводит и конец месяца, и переход через полночь. Частая ошибка — прокинуть Supplier<LocalDate>, но забыть про таймзону: now(clock) и now() по-разному считают дату на границе суток в разных зонах.",
 "inf-cacheaside": "Классическая гонка: поток A читает старое значение из БД и собирается положить в кэш, а параллельно поток B обновляет БД и инвалидирует кэш — A затирает кэш протухшими данными. Безопаснее инвалидировать ключ (delete), а не писать в него на апдейте, и удалять кэш ПОСЛЕ коммита транзакции, а не до.",
 "inf-stampede": "TTL без джиттера сам провоцирует stampede: ключи, созданные одной пачкой, протухают одновременно. Лечат рандомизацией TTL + единственным пересчётом под distributed lock (или early recompute до истечения), остальные отдают чуть устаревшее значение.",
 "inf-rabbit-kafka": "Порядок в Kafka гарантирован только в пределах одной партиции, а не топика: если ключ партиционирования не задан (или разный), сообщения одной сущности расползаются по партициям и читаются вне порядка. В RabbitMQ порядок ломает любой prefetch>1 с несколькими консьюмерами на очереди.",
 "inf-k8s-probes": "Liveness, бьющая по тяжёлой ручке или внешней зависимости (БД), под нагрузкой начинает таймаутиться и K8s рестартит здоровые поды — каскад перезапусков под пиком. Liveness должна проверять только сам процесс; зависимости — дело readiness. Плюс не забывают про startupProbe для долго стартующих JVM, иначе liveness убьёт под на разогреве.",
 "x-inf-kafka-consumer-group": "При входе/выходе консьюмера происходит rebalance: партиции переназначаются и на это время потребление встаёт (stop-the-world у старого протокола). Долгая обработка одного сообщения дольше max.poll.interval.ms трактуется как смерть консьюмера → его выкидывают и запускают ребаланс-петлю.",
 "x-inf-redis-persistence": "AOF с fsync everysec теряет до 1 сек данных, а не «ничего»; appendfsync always убивает throughput. Фоновый RDB/AOF rewrite форкает процесс и из-за copy-on-write может удвоить потребление RAM на пике записи — частая причина OOM Redis.",
 "g-inf-es-refresh-near-realtime": "force refresh на каждую запись (refresh=true или refresh_interval малый) под нагрузкой плодит мелкие сегменты и убивает производительность из-за постоянных merge. Для bulk-загрузки наоборот ставят refresh_interval=-1 и рефрешат один раз в конце.",
 "g-inf-es-shards-replicas": "Слишком много мелких primary shards (oversharding) — частая ошибка: каждый shard это люсеновский индекс со своими накладными расходами на heap и кластерный стейт, и тысячи shard'ов кладут мастер-ноду. Реплику нельзя поднять выше числа доступных нод — лишние реплики висят unassigned, а индекс становится yellow.",
 "g-inf-docker-layer-cache-order": "Тонкость с go-offline: транзитивные и плагинные зависимости он подтягивает не все, поэтому первая реальная сборка иногда всё равно лезет в сеть. Ещё кэш слоя инвалидирует ЛЮБОЕ изменение pom.xml (даже версии приложения), а COPY с меняющимися timestamp/правами файлов ломает кэш незаметно.",
 "g-inf-k8s-configmap-no-reload": "subPath-монтирование ConfigMap НЕ обновляется автоматически (в отличие от обычного volume) — файл застывает на момент старта. И даже у обычного volume обновление прилетает в ФС, но приложение должно само следить за файлом; типичный паттерн — checksum-аннотация на pod template, чтобы изменение ConfigMap триггерило rollout.",
 "g-inf-k8s-hpa-needs-requests": "Для JVM есть отдельная ловушка: HPA считает % от requests.cpu, и если приложение упирается в память, а не в CPU, по CPU оно не масштабируется вовсе. А limits.cpu ниже реальной потребности вызывает CFS-throttling — под тормозит, но CPU-utilization для HPA выглядит низким.",
 "g-inf-nginx-upstream-lb": "ip_hash ломается за корпоративным NAT/прокси (много юзеров с одного IP липнут на один бэкенд → перекос нагрузки) и пере-распределяет всех при добавлении/удалении ноды. Дефолтный upstream к тому же не делает health-check (он только в nginx plus / через max_fails), поэтому может слать трафик на уже мёртвый бэкенд.",
 "jvm-stw": "System.gc() можно отключить флагом -XX:+DisableExplicitGC (часто стоит в проде), тогда вызов молча игнорируется. Но осторожно: некоторые библиотеки (например, off-heap DirectByteBuffer/Netty) полагаются на System.gc() для своевременного освобождения native-памяти — при отключённом GC можно словить 'Direct buffer memory' OOM.",
 "jvm-metaspace": "По умолчанию metaspace не ограничен и растёт до тех пор, пока есть native-память — забывают поставить -XX:MaxMetaspaceSize. Классическая утечка: hot-redeploy в app-сервере или динамическая генерация прокси/классов (CGLIB, лямбды через reflection), когда старые ClassLoader'ы не собираются из-за висящих ссылок.",
 "x-jvm-references": "SoftReference НЕ панацея от утечек кэша: GC чистит их только под давлением памяти и часто слишком поздно — перед OOM начинаются длинные Full GC. finalize() устарел и ненадёжен (нет гарантий вызова/времени) — для очистки ресурсов использовать PhantomReference + Cleaner или try-with-resources.",
 "x-jvm-tlab-escape": "Escape analysis и scalar replacement работают только в C2 после прогрева и ломаются от мелочей: объект 'убежит', если его передать в неинлайненный метод, положить в поле/массив или synchronized по нему. Нельзя рассчитывать, что 'JIT всё уберёт' — в бенчмарках это маскирует реальные аллокации (нужен JMH с Blackhole).",
 "x-jvm-oom-types": "OutOfMemoryError — это Error, а не Exception, ловить его catch(Exception) бесполезно; после него JVM часто в неконсистентном состоянии. 'GC overhead limit exceeded' обманчив: heap формально не полон, но приложение по сути мёртвое. Для post-mortem ставьте -XX:+HeapDumpOnOutOfMemoryError.",
 "g-jvm-jit-tiers": "Из-за прогрева первые тысячи запросов после старта медленные — критично для коротких джоб, serverless/FaaS и нагрузочного теста без warmup (получите заниженные цифры). Решения: -XX:+TieredCompilation (по умолчанию), AppCDS, либо AOT/JIT-кэш (Project Leyden / GraalVM native-image) чтобы убрать прогрев.",
 "g-jvm-deopt": "Частая грабля производительности — мегаморфные call-site: если в одну точку вызова приходит 3+ разных типа, JIT не может девиртуализировать/инлайнить и оставляет дорогой виртуальный вызов. Постоянные deopt видны в -XX:+PrintCompilation как 'made not entrant'.",
 "g-jvm-classloader-delegation": "Parent-delegation ломается там, где приложение должно видеть свою версию класса: web-контейнеры (Tomcat) и OSGi намеренно инвертируют делегирование (child-first). Отсюда классический ClassCastException 'Foo cannot be cast to Foo' — один и тот же класс, загруженный двумя разными загрузчиками, считается разными типами.",
 "g-jvm-happens-before": "Частая ошибка — double-checked locking без volatile: без него другой поток может увидеть ссылку на не до конца сконструированный объект. И наоборот: volatile у ССЫЛКИ на коллекцию не делает потокобезопасной саму коллекцию — happens-before покрывает только запись/чтение самого volatile-поля.",
 "g-jvm-string-intern-dedup": "intern() на массовых динамических строках — антипаттерн: до Java 7 это текло в PermGen, сейчас пул в heap, но строки практически не собираются и таблица пула фиксированного размера — частые intern() деградируют по производительности. String dedup (-XX:+UseStringDeduplication) для большинства приложений выгоднее и бесплатен.",
 "g-jvm-heap-flags-ergonomics": "-Xmx == -Xms сам по себе не коммитит память физически — страницы выделяются лениво при первом обращении; чтобы реально зафиксировать и убрать page-fault'ы, нужен -XX:+AlwaysPreTouch (ценой более долгого старта). Отдельная грабля в контейнерах: на старых JVM -Xmx не учитывал cgroup-лимит — задавайте -XX:MaxRAMPercentage.",
 "g-jvm-safepoint": "JIT не вставляет safepoint-проверку в 'counted loop' с int-счётчиком — поэтому долгий цикл по int может надолго заблокировать достижение safepoint и заморозить все потоки ('time to safepoint'). Замена счётчика на long или включение -XX:+UseCountedLoopSafepoints чинит. Диагностика: -XX:+PrintSafepointStatistics / safepoint-логи.",
 "git-rebase": "Золотое правило: не делай rebase запушенных/общих веток — переписанные хеши заставят остальных делать force-pull и плодить дубли. После rebase своей ветки push идёт только через --force-with-lease (не голый --force, иначе затрёшь чужой коммит, прилетевший после твоего fetch).",
 "git-reset-revert": "revert merge-коммита требует -m <номер родителя>, а сам факт revert'а «помечает» ветку как уже влитую — повторный merge той же ветки потом не подтянет изменения, пока не сделаешь revert revert'а. reset --soft сохраняет изменения в индексе, --mixed — в рабочем дереве, --hard стирает их безвозвратно (спасает только reflog).",
 "git-stash": "git stash по умолчанию НЕ прячет новые (untracked) и проигнорированные файлы — нужен -u / -a, иначе при переключении ветки они «протекут» и помешают. stash pop при конфликте оставляет запись в стэше (в отличие от успешного pop, который её удаляет) — легко потерять, думая что уже применил.",
 "x-git-reflog": "reflog локальный и недолговечный: записи живут ~90 дней (gc.reflogExpire), а недостижимые коммиты вычищает git gc — спасать «потеряшку» надо сразу. На свежесклонированном репозитории reflog пуст, так что чужие потерянные коммиты через него не вернуть.",
 "x-git-merge-conflict": "Отсутствие маркеров <<<<<<< не значит «конфликта нет»: семантический конфликт (обе стороны меняли разные строки, но логику ломают совместно) git не видит — компилируется, но падает в рантайме. Git rerere умеет запоминать разрешения повторяющихся конфликтов при долгих rebase.",
 "x-git-fetch-pull": "Голый git pull при разошедшихся ветках делает merge и плодит «merge branch main into main»-коммиты в истории — поэтому многие ставят pull.rebase=true. fetch обновляет origin/main, но НЕ двигает твою локальную main: после fetch её надо отдельно merge/rebase.",
 "g-git-submodule": "Обычный git clone не тянет содержимое сабмодулей — нужен --recurse-submodules или потом submodule update --init; забыл — собрал старую версию. git pull в родителе обновляет указатель сабмодуля на новый SHA, но не сами файлы сабмодуля, и эти «прыжки gitlink» — частый невидимый источник багов на CI.",
 "g-git-detached-head": "Классическая ловушка с сабмодулями и CI: после checkout по SHA любой коммит висит в detached HEAD и теряется при следующем переключении, если не создать ветку. git checkout - не вернёт detached-коммиты — только их хеш из reflog.",
 "g-git-revert-merge": "revert merge-коммита через -m 1 отменяет влитый код, но НЕ откатывает саму историю — git считает ветку по-прежнему влитой. Чтобы доработать и влить её снова, придётся реверсировать сам revert (revert revert'а), иначе повторный merge не подтянет изменения.",
 "g-git-hooks": "Хуки лежат в .git/hooks и не версионируются — у нового разработчика их просто нет, пока он не настроит core.hooksPath или Husky/pre-commit. Любой хук обходится флагом --no-verify, поэтому проверки качества должны дублироваться в серверном CI, а не только в pre-commit.",
 "g-git-gitignore-tracked": "После git rm --cached файл остаётся на диске, но удаляется из индекса — у других при pull он тоже удалится из рабочей копии (часто неожиданно стирают чужие локальные конфиги). И добавление каталога в .gitignore не игнорирует уже отслеживаемые файлы внутри него.",
 "g-git-cherry-pick-conflict": "cherry-pick создаёт коммит с НОВЫМ SHA, поэтому при последующем merge той же ветки git видит «дубль» изменений и может выдать конфликт или удвоить правки. git cherry помогает найти уже перенесённые коммиты; -x в сообщение добавит ссылку на оригинал.",
 "db-leftmost": "Postgres всё же может использовать такой индекс через Index Skip Scan / отдельный scan только если client_id низкокардинален, но это медленно и ненадёжно — не закладывайся. И наоборот: индекс (client_id, date) отлично закроет WHERE client_id=? AND date=? и WHERE client_id=? ORDER BY date — это и есть смысл leftmost-префикса.",
 "db-covering": "В Postgres index-only scan реально срабатывает только если visibility map говорит, что страница 'all-visible' — иначе движок всё равно идёт в heap проверять видимость версии строки. После массовых обновлений без VACUUM covering-индекс молча перестаёт быть index-only. INCLUDE-колонки добавляют данные в индекс, но не участвуют в сортировке/поиске.",
 "db-notused": "Частая реальная причина 'индекс не используется' — не объём выборки, а несовпадение типов (колонка bigint, параметр передан как text/numeric) или функция над колонкой (lower(col), col::date), из-за чего planner не видит совпадения. Ещё — устаревшая статистика после массовой заливки: помогает ANALYZE.",
 "db-keyset": "Keyset ломается на неуникальном ключе сортировки: при ORDER BY created_at будут дубли времени и строки на стыке страниц потеряются/задвоятся — нужен составной курсор (created_at, id) и WHERE (created_at, id) > (?, ?). Плюс keyset не умеет прыгнуть на 'страницу 50' — только вперёд/назад.",
 "db-isolation": "Имена уровней обманчивы: в Postgres REPEATABLE READ — это snapshot isolation и НЕ ловит write skew, а в Oracle 'SERIALIZABLE' на деле тоже snapshot. Дефолт в Postgres/Oracle — READ COMMITTED, в MySQL InnoDB — REPEATABLE READ. Один и тот же код ведёт себя по-разному на разных СУБД.",
 "db-lostupdate": "Оптимистичная блокировка ловит lost update, только если ВСЕ писатели идут через тот же version-механизм; голый UPDATE в обход (миграция, ручной SQL, другой сервис) её обходит молча. И в JPA @Version проверка происходит на flush/commit — между чтением и commit'ом окно гонки остаётся, нужен retry на OptimisticLockException.",
 "db-writeskew": "В Postgres SERIALIZABLE (SSI) не блокирует, а откатывает проигравшую транзакцию ошибкой 40001 (serialization failure) — без обёртки с retry операции молча теряются под нагрузкой. Дешёвая альтернатива от write skew без полного SERIALIZABLE — материализовать конфликт через SELECT ... FOR UPDATE на общей строке-инварианте.",
 "db-optpess": "Пессимистичная блокировка не масштабируется и легко даёт deadlock, если транзакции берут строки в разном порядке — фиксируй порядок (например по возрастанию id). А оптимистичная под высоким контеншеном вырождается в шторм откатов и повторов, съедая больше, чем сэкономила — тогда лучше пессимистичная или очередь.",
 "db-mvcc": "Цена MVCC — bloat: SELECT не блокирует UPDATE, но длинная открытая транзакция (или забытый replication slot) держит старый снапшот и не даёт VACUUM почистить мёртвые версии во ВСЕЙ базе — таблицы и индексы пухнут на ровном месте. Следи за pg_stat_activity по долгоживущим транзакциям.",
 "db-vacuum": "Обычный VACUUM возвращает место для переиспользования внутри таблицы, но НЕ отдаёт его ОС — файл не сжимается. Чтобы реально вернуть место, нужен VACUUM FULL (берёт ACCESS EXCLUSIVE lock, переписывает таблицу — на проде стоп-мир) или pg_repack без блокировки. Главный риск — wraparound: при отставании autovacuum база может уйти в read-only.",
 "db-numeric": "NUMERIC точен, но медленный (программная арифметика) и без указания масштаба NUMERIC хранит как ввели — округление на твоей совести. Частая прод-ошибка — float проникает не в БД, а в Java: double в коде или JSON; для денег нужен BigDecimal по всей цепочке, иначе точность теряется ещё до записи в NUMERIC.",
 "db-idxbloat": "REINDEX без CONCURRENTLY блокирует запись (а до PG12 — и чтение); на проде нужен REINDEX INDEX CONCURRENTLY или pg_repack. Корень bloat часто — длинные транзакции, мешающие vacuum; просто пересоздать индекс не лечит, если причина не устранена.",
 "db-selectstar": "Конкретная боль SELECT *: при JOIN двух таблиц с одноимёнными колонками (id, created_at) маппер молча берёт не ту, плюс отдача bytea/JSONB/TEXT-полей, которые приложению не нужны, раздувает трафик и память. В коде это ещё и ломается тихо при добавлении колонки, без ошибки компиляции.",
 "db-polymorphic": "Полиморфная FK незаметно убивает планировщик: индекс по (parent_type, parent_id) полупустой и неэффективный, а ORM-eager-загрузка таких связей обычно выливается в N+1. Если очень нужно — лучше отдельные nullable FK-колонки с CHECK, что заполнена ровно одна.",
 "db-read-phenom": "Стандарт SQL определяет уровни через эти три аномалии, но реальные СУБД защищают иначе и от большего: snapshot isolation (Postgres RR) убирает все три, но добавляет write skew, которого в стандарте нет вообще. Поэтому 'мой уровень закрывает фантомы' — проверяй по конкретной СУБД, а не по стандарту.",
 "db-jdbc": "ResultSet по умолчанию тянет ВСЕ строки в память (особенно драйвер MySQL) — на большой выборке OOM; для стриминга нужен forward-only ResultSet + setFetchSize и в Postgres обязательно autoCommit=false, иначе fetchSize игнорируется. И Connection/Statement/ResultSet надо закрывать (try-with-resources), иначе утечка соединений из пула.",
 "db-hikari": "Главная прод-ловушка пула — connection leak: соединение взято и не возвращено (забыли close, исключение мимо finally), пул исчерпывается и приложение висит на getConnection. Лечат leakDetectionThreshold. И больше — не лучше: пул крупнее, чем БД тянет по ядрам/коннектам, снижает throughput и упирается в max_connections.",
 "x-db-deadlock": "Deadlock возникает не только из явных блокировок: его дают порядок строк в одном UPDATE по диапазону, FK-проверки (lock на родителя), gap-локи в MySQL и даже два INSERT с одинаковым уникальным ключом. Postgres жертву убивает сам, но приложение ОБЯЗАНО ловить ошибку и делать retry — иначе пользователь видит 500.",
 "x-db-n-plus-one": "JPA/Hibernate ловушка: lazy-связи дают N+1 незаметно при доступе к коллекции уже вне транзакции (LazyInitializationException) либо тихо в цикле. JOIN FETCH лечит, но с несколькими коллекциями даёт декартово произведение — нужен @BatchSize или раздельные запросы. Включи hibernate show_sql/p6spy, чтобы увидеть реальное число запросов.",
 "x-db-for-update": "FOR UPDATE не блокирует строки, которые ещё не вставлены — от фантомов (двойная вставка по бизнес-ключу) спасает уникальный constraint, а не FOR UPDATE. Варианты NOWAIT/SKIP LOCKED меняют поведение: без них воркеры выстраиваются в пробку за одной строкой. И блокировка живёт до конца транзакции, а не до конца SELECT.",
 "x-db-sql-injection": "PreparedStatement параметризует только значения, но НЕ имена таблиц/колонок, ORDER BY и LIMIT-направление — если их подставляешь динамически из ввода, инъекция остаётся; такие куски валидируй белым списком. Конкатенация 'для одного безобидного фильтра' — типичный источник дыры.",
 "p-tx-ssi-retry-40001": "Retry нужен на ВСЮ транзакцию с самого начала (новый снапшот), а не на повтор одного UPDATE — иначе повторишь поверх того же конфликтного снапшота. И ошибка может прилететь даже на COMMIT, а не на конкретном запросе, поэтому retry-обёртка должна охватывать commit.",
 "p-db-composite-order": "Правило 'равенство first, диапазон last' распространяется и на ORDER BY: индекс (status, created_at) ещё и отдаёт строки уже отсортированными по created_at внутри status — убирает отдельный Sort-шаг. А вот два диапазона по разным колонкам один B-tree эффективно не закроет в любом порядке.",
 "p-db-unindexed-fk": "Это самый частый 'невидимый' прод-затык: индекс на FK не создаётся автоматически ни в Postgres, ни в Oracle (в MySQL InnoDB — создаётся). Помимо медленного DELETE родителя, отсутствие индекса на дочерней FK провоцирует эскалацию блокировок и взаимоблокировки при каскадах.",
 "p-pg-cic-invalid": "После падения CREATE INDEX CONCURRENTLY невалидный индекс не используется для чтения, но Postgres всё равно поддерживает его при каждом INSERT/UPDATE — то есть ты платишь за индекс, не получая выгоды, пока не сделаешь DROP INDEX CONCURRENTLY. Проверять: indisvalid в pg_index.",
 "p-pg-skip-locked": "SKIP LOCKED не гарантирует порядок (FIFO ломается) и при коротких транзакциях воркеры могут конкурировать за хвост; нужен ORDER BY + LIMIT внутри подзапроса. Главное — закоммитить/удалить взятую строку, иначе при падении воркера задача 'застрянет залоченной' лишь до конца его транзакции, потом снова станет видимой (риск повторной обработки — делай идемпотентно).",
 "p-pg-pgbouncer-txn": "С PgBouncer transaction mode JDBC-драйвер Postgres надо переключать на server-side prepared statements off (prepareThreshold=0) или включать pooler-aware режим — иначе ошибки 'prepared statement S_1 already exists' под нагрузкой. И session-advisory-локи/LISTEN-NOTIFY через такой пул использовать нельзя.",
 "p-sql-null-not-in": "Та же ловушка шире NOT IN: любое сравнение с NULL даёт UNKNOWN, поэтому WHERE col <> 'x' молча отбрасывает строки с col IS NULL, а UNIQUE-constraint считает несколько NULL различными (дубли проходят). Для NOT IN канонично лечится переходом на NOT EXISTS, который ведёт себя корректно при NULL.",
 "g-db-gin-jsonb": "GIN большой и медленный на запись (особенно с jsonb_ops vs jsonb_path_ops — последний компактнее, но только для @>). Для ускорения вставок есть fastupdate (pending list), но он временно замедляет чтение, пока список не смержится. Btree всё же нужен, если ищешь по конкретному скаляру data->>'id' = ? — для этого делают expression-индекс.",
 "g-db-brin": "BRIN полностью держится на физической корреляции данных с колонкой: если порядок вставки не совпадает с created_at (бэкфилл, обновления, перемешанные блоки) или прошёл VACUUM FULL/перезаливка — BRIN деградирует до почти бесполезного, отбрасывая мало блоков. Требует регулярного brin_summarize и не годится для точечного поиска/уникальности.",
 "g-db-partial-index": "Planner применит partial index, только если его WHERE-предикат доказуемо покрывает условие запроса — и константа должна совпадать буквально (индекс WHERE status='NEW' не сработает для status=:param, если planner не уверен в значении). Удобный побочный трюк — частичный UNIQUE-индекс (уникальность только среди активных строк).",
 "g-db-expression-index": "Выражение в индексе должно совпадать с выражением в запросе ПОБУКВЕННО и быть IMMUTABLE — например lower(email) ок, а now()-based или зависящее от timezone (col::date в timestamptz) — нет, индекс не создастся или не применится. Статистику по выражению planner собирает отдельно — после создания полезен ANALYZE.",
 "g-db-pool-size": "Контринтуитив: при нехватке коннектов ответ почти всегда 'уменьшить пул', а не увеличить — большой пул лишь переносит очередь с пула на CPU/диск БД и бьёт по соседним сервисам через общий max_connections. Реальный потолок — max_connections базы минус другие потребители; за ним ставят PgBouncer, а не раздувают пул приложения.",
 "g-db-fk-cascade-storm": "ON DELETE CASCADE выполняется БД построчно и не виден в коде приложения — мониторинг и аудит часто его пропускают, а каскад без индексов на дочерних FK делает seq scan на каждую строку. Для больших объёмов безопаснее удалять детей явными батчами (DELETE ... LIMIT в цикле) или soft-delete.",
 "g-db-recursive-cte": "Рекурсивный CTE без защиты зациклится навсегда при цикле в данных (parent_id указывает на предка) — нужен либо UNION (дедуп), либо ограничение глубины/трекинг пути массивом с проверкой на повтор. И в старом Postgres CTE был optimization fence (материализовался) — с PG12 инлайнится, но рекурсивный CTE по-прежнему материализуется.",
 "g-db-prepared-plan-cache": "Generic-план выбирается после 5 выполнений, только если его оценочная стоимость не хуже custom — но при перекосе данных он промахивается и убивает быстрый случай. Лечение: plan_cache_mode=force_custom_plan, либо в JDBC снизить prepareThreshold. Этот же эффект — причина, почему 'тот же запрос то быстрый, то медленный' без видимых изменений.",
 "arch-event-driven": "Событие — это не «вызов через очередь»: продюсер теряет контроль и не знает, обработали ли его. Главные грабли — гарантии доставки (at-least-once → дубли, нужна идемпотентность) и порядок: в Kafka он гарантирован только внутри партиции, а ключ партиционирования выбирают неправильно и ломают последовательность для одного агрегата.",
 "arch-api-gateway": "Gateway легко превращается в God Object: в него тащат бизнес-логику, агрегацию и трансформации, и он становится узким местом и точкой отказа. Держи его тонким (auth, routing, rate limit), а оркестрацию выноси в BFF/сервисы.",
 "arch-db-per-service": "На практике «своя БД» ломается на отчётах и join'ах через границы сервисов: запросы по нескольким сервисам делают через API-композицию или CQRS read-model, а не через прямой join. И самый частый скрытый антипаттерн — общая БД с разными схемами, но одним инстансом: формально раздельно, фактически связаны через ресурсы и миграции.",
 "arch-saga-orch-choreo": "Главные грабли саги — компенсации не откатывают, как rollback в БД: побочные эффекты уже случились (письмо ушло, деньги списались), компенсация лишь делает обратное действие. Плюс нужна идемпотентность шагов и semantic lock — иначе при параллельных сагах данные в промежуточном состоянии прочитают как валидные.",
 "arch-event-sourcing": "Главная боль — версионирование событий: старые события в сторе нельзя менять, а схема эволюционирует, поэтому нужны upcasters. И никогда не вызывай внешние сайд-эффекты при replay (отправка письма, оплата) — реплей прогонит их заново; сайд-эффекты выносят в проекции/process manager.",
 "arch-replication": "Асинхронная реплика даёт read-your-writes аномалию: пользователь записал и тут же читает со слейва старое значение. Лечат маршрутизацией критичных чтений на мастер или sticky-чтением. Ещё грабли — replication lag растёт под нагрузкой незаметно, пока кто-то не прочитает устаревшее.",
 "arch-sharding": "Боль не в самом шардинге, а в выборе ключа: плохой ключ даёт hot shard (всё валится на один) и кросс-шардовые запросы/join'ы, которые почти невозможны. Решардинг живой системы — отдельный ад, поэтому ключ выбирают сразу с запасом и часто берут consistent hashing.",
 "arch-caching-strategies": "Cache-aside классически ловит race condition при инвалидации: один поток читает старое из БД и кладёт в кэш ровно после того, как другой обновил БД и удалил ключ — кэш застывает с устаревшими данными. Отсюда же thundering herd при массовом истечении TTL и cache stampede на популярном ключе.",
 "arch-rate-limiting": "Наивный fixed-window лимитер пропускает 2x лимита на стыке окон (всплеск в конце одного окна + начало следующего) — поэтому в проде берут sliding window или token bucket. В распределённой системе счётчик должен быть атомарным (Redis INCR/Lua), иначе гонка обнуляет лимит.",
 "arch-consistency-models": "«Eventual» не значит «скоро» — гарантии на время сходимости нет, и без read-your-writes/monotonic-reads пользователь видит то новое, то старое значение, прыгающее туда-сюда. Сильная консистентность по CAP жертвует доступностью при разделении сети — при partition узлы просто откажут в записи.",
 "arch-distributed-lock": "Redis-лок на одном инстансе не безопасен при failover: лок реплицируется асинхронно, мастер падает до репликации — и второй процесс берёт тот же лок. Redlock тоже критикуют (Kleppmann): GC-пауза или сетевая задержка дольше TTL → процесс думает, что держит лок, а он уже отдан. Спасает не лок, а fencing token + идемпотентность.",
 "arch-2pc-vs-saga": "2PC блокирует ресурсы на время всего протокола и не переживает падение координатора в фазе commit (in-doubt транзакции висят с блокировками) — поэтому в микросервисах его почти не используют. Saga взамен жертвует изоляцией: промежуточные состояния видны другим, нужны semantic lock и идемпотентные компенсации.",
 "g-arch-aggregate": "Главная ошибка — раздутый агрегат: тянут в один корень половину домена ради «удобных» навигаций, и тогда каждая запись лочит огромный кусок и ловит конфликты при конкурентном доступе. Правило «одна транзакция = один агрегат» нарушают, меняя два агрегата в одной транзакции вместо eventual consistency через события.",
 "g-arch-value-object": "VO обязан быть immutable, иначе при шеринге одного экземпляра между сущностями мутация в одном месте незаметно меняет данные в другом. Частая грабля в Java — забыть переопределить equals/hashCode, и VO начинает сравниваться по ссылке, ломая поиск в коллекциях и сравнение по значению.",
 "g-arch-idempotent-consumer": "Проверка messageId и сама бизнес-запись должны быть в ОДНОЙ транзакции с БД — иначе при падении между ними либо потеряешь обработку, либо задублируешь. И dedup-таблица растёт бесконечно: нужна чистка по TTL, но окно хранения должно перекрывать максимальный лаг ретраев брокера.",
 "g-arch-outbox-vs-cdc": "Outbox-релейер даёт at-least-once — одно и то же событие может уйти в брокер дважды (упал после отправки, до отметки в БД), поэтому consumer обязан быть идемпотентным. CDC же требует не делать UPDATE-then-DELETE строки outbox без INSERT, иначе Debezium не увидит её, и ловит проблему с initial snapshot и порядком при множестве партиций.",
 "g-arch-strangler": "Самая недооценённая часть — данные: пока старый и новый код пишут в одну БД, нужна синхронизация в обе стороны или единый источник правды, иначе разъезжается состояние. И фасад-роутер нельзя выпиливать, пока хоть один кусок ходит в легаси — он живёт всё время миграции, которая длится месяцами.",
 "g-arch-multitenancy": "Модель «общая схема + tenant_id» ловит утечки данных при ЛЮБОМ забытом WHERE tenant_id — один пропущенный фильтр в запросе показывает чужие данные. Поэтому фильтр выносят на уровень ниже кода (RLS в Postgres, Hibernate filter), а не оставляют на дисциплину разработчика.",
 "web-idempotent": "Идемпотентность по спеке HTTP — это про конечное состояние сервера, а НЕ про одинаковый код ответа: повторный DELETE законно вернёт 404 вместо 204. И сама твоя реализация PUT/DELETE может быть неидемпотентной (PUT с server-side инкрементом, DELETE с триггером) — спека не заставляет, ответственность на тебе.",
 "web-status": "403 vместо 404 на чужой ресурс — это утечка: подтверждаешь существование объекта. Для приватных данных часто намеренно отдают 404. И 401 ОБЯЗАН по RFC сопровождаться заголовком WWW-Authenticate — без него формально это не 401.",
 "web-pagination": "Keyset стабилен, только если сортируешь по уникальному монотонному ключу; по неуникальному полю (created_at с дублями) строки на границе курсора теряются или дублируются — нужен составной курсор (created_at, id). И keyset плохо умеет прыжок на произвольную страницу N — только next/prev.",
 "web-post-201": "Частая грабля: Location при создании за reverse-proxy указывает на внутренний хост/схему (http вместо https), потому что строится из Host/X-Forwarded-* без правильной настройки прокси-заголовков.",
 "web-tls": "Сертификат сам по себе не доказывает, что сервер 'тот самый' — браузер ещё обязан сверить имя в SAN с хостом (CN давно игнорируется) и проверить отзыв (CRL/OCSP). Срок и доверие к CA — это не то же самое, что совпадение домена.",
 "web-auth-schemes": "JWT в Bearer сервер проверяет по подписи БЕЗ похода в БД — поэтому досрочно отозвать/разлогинить такой токен нельзя, он валиден до exp. Отсюда короткий TTL + refresh либо чёрный список. И классическая дыра — принять alg:none или перепутать RS256/HS256.",
 "x-web-cors-preflight": "CORS защищает только чтение ответа в браузере — сам запрос на сервер всё равно уходит и сайд-эффект выполняется (поэтому CORS != защита от CSRF). И ответ на ошибку CORS невозможно прочитать из JS: видишь только 'CORS error', реальный статус скрыт. Wildcard '*' несовместим с credentials.",
 "x-web-idempotency-key": "Ключ надо вставлять в БД с UNIQUE в ТОЙ ЖЕ транзакции, что и платёж, иначе при гонке два параллельных ретрая оба пройдут до записи ключа. И кэшировать нужно сам ответ: иначе на повтор вернёшь 200 без данных или повторно стриганёшь оплату.",
 "x-web-rate-limit-429": "Наивный fixed-window даёт всплеск на стыке окон (2x лимита за пару секунд на границе) — поэтому берут sliding window или token bucket. И в кластере счётчик в локальной памяти инстанса бесполезен — нужен общий (Redis), иначе лимит умножается на число подов.",
 "x-web-etag-caching": "Грабли: gzip/сжатие на прокси меняет ETag, и weak (W/) против strong ETag — для range-запросов нужен strong. Главное — 304 экономит трафик, но НЕ нагрузку на бэкенд: чтобы посчитать ETag, ты обычно всё равно лезешь в БД, если только не кэшируешь сам ETag.",
 "web-http-versions": "HTTP/2 убрал HOL-блокировку на уровне HTTP, но не на уровне TCP: потеря одного пакета тормозит ВСЕ мультиплексированные потоки одного соединения — именно это и чинит HTTP/3 на QUIC. Поэтому под потерями h2 иногда медленнее h1 с несколькими соединениями.",
 "web-cors": "CORS — это исключительно браузерная защита: curl, бэкенд и Postman игнорируют её полностью. И она защищает не сервер, а пользователя от чтения его данных чужим JS; сам запрос с сайд-эффектом всё равно доходит.",
 "web-tcp-udp": "'TCP надёжный' — на уровне доставки байт, но не сообщений: это поток без границ, два send могут склеиться/разрезаться при recv (нужен свой фрейминг по длине/разделителю). А ещё открытый TCP-сокет не замечает, что пир умер, пока не пошлёшь данные или не включишь keep-alive.",
 "g-web-oauth-flows": "Authorization code обязателен с проверкой state (анти-CSRF) и точного redirect_uri — без этого код угоняют через подменённый redirect. Для SPA refresh-токен в localStorage уязвим к XSS: безопаснее httpOnly-cookie + ротация refresh-токенов.",
 "g-web-csp": "CSP легко обойти, если разрешён 'unsafe-inline' или весь домен CDN с уязвимыми библиотеками (JSONP-эндпоинт на whitelisted-домене = дыра). Современный подход — nonce/hash вместо whitelist по доменам, плюс strict-dynamic.",
 "g-web-hsts": "Самый первый визит к новому домену HSTS не защищает (заголовок ещё не получен) — закрывает это только preload-список, вшитый в браузер. И includeSubDomains + длинный max-age на домене без HTTPS на каком-то поддомене положит его намертво, откатить мгновенно нельзя.",
 "g-web-samesite": "SameSite=Lax не панацея: GET с сайд-эффектом и top-level POST-навигация (form target) частично проходят, а сабдомены считаются same-site (атака с скомпрометированного поддомена пролезет). Поэтому Lax не заменяет CSRF-токен для критичных операций.",
 "g-web-idempotency-key": "UNIQUE-вставка ключа и сама операция должны быть в одной транзакции, иначе гонка двух ретраев пройдёт оба. Тонкость: что отдать, если первый запрос ещё ВЫПОЛНЯЕТСЯ (ключ есть, ответа нет) — обычно 409/'в обработке', а не молчаливый дубль.",
 "g-web-sse-vs-ws": "SSE поверх HTTP/1.1 жрёт лимит ~6 соединений на домен в браузере (несколько вкладок — и всё висит); на HTTP/2 это снимается мультиплексом. Плюс корпоративные прокси/балансировщики любят буферизировать или рвать долгоживущий SSE-стрим.",
 "g-web-3xx-statuses": "Главная грабля прямо в теме: 301/302 многие клиенты (и старые браузеры) превращают в GET и ТЕРЯЮТ тело — POST-платёж станет GET. Для редиректа не-GET бери строго 307/308. Ещё: после 308 нельзя менять метод даже намеренно.",
 "g-web-keepalive": "Создавать новый HttpClient на запрос (классика в Java/.NET) исчерпывает эфемерные порты и оставляет горы TIME_WAIT под нагрузкой — клиент надо переиспользовать как синглтон. И keep-alive-соединение в пуле может протухнуть на стороне сервера/LB, дав случайный сброс на следующем запросе.",
 "g-web-csrf-token": "Double-submit-токен ломается, если поддомен может ставить cookie на родительский домен (поддомен подделает и cookie, и заголовок). Тогда нужен привязанный к сессии synchronizer-token, а не stateless double-submit.",
 "web-http-anatomy": "Грабля парсинга/безопасности: рассинхрон Content-Length и Transfer-Encoding между фронт- и бэкендом даёт HTTP request smuggling. И заголовки регистронезависимы, но значения — нет; дубли заголовков обрабатываются прокси по-разному.",
 "web-https-what": "HTTPS шифрует тело и путь, но НЕ скрывает сам домен: имя хоста уходит открытым текстом в SNI при handshake (и в DNS), так что 'куда ты ходишь' видно наблюдателю. Закрывает это только ECH, который ещё не повсеместен.",
 "web-grpc": "gRPC из браузера напрямую не работает (нет доступа к HTTP/2-фреймам и трейлерам из JS) — нужен grpc-web + прокси. И в protobuf удаление/переиспользование номера поля ломает обратную совместимость: номера, а не имена, нельзя трогать.",
 "web-websocket-proto": "После апгрейда WebSocket — это НЕ HTTP: обычные L7-фичи (REST-роутинг, кэш, статус-коды, авторизация по заголовкам на каждый кадр) не работают, балансировщик нужен с поддержкой Upgrade и sticky. Браузер не шлёт кастомные заголовки при handshake — токен суют в query/subprotocol.",
 "web-graphql-deep": "Главная грабля — N+1: один запрос с вложенностью разворачивается в лавину походов в БД, лечится DataLoader (батчинг). И публичный GraphQL без ограничения глубины/стоимости запроса — это DoS: клиент сам конструирует чудовищный вложенный запрос.",
 "web-oauth-tokens": "Частая ошибка — использовать access_token как доказательство 'кто юзер': он для доступа к API, личность даёт id_token (OIDC). И ресурс-сервер обязан валидировать audience/issuer токена, иначе токен, выданный для другого API, пройдёт (confused deputy).",
 "web-mtls": "mTLS перекладывает всю боль на управление сертификатами: протухший или непереротированный клиентский серт кладёт интеграцию намертво, а отзыв (CRL/OCSP) в межсервисном mTLS часто фактически не проверяется — отозванный серт продолжает работать до истечения.",
 "web-grpc-vs-rest": "gRPC через L7-балансировщик требует осторожности: одно долгоживущее HTTP/2-соединение мультиплексирует все RPC, и naive round-robin по соединениям шлёт весь трафик на один бэкенд — нужна балансировка на уровне запросов (gRPC client-side LB или L7-aware прокси).",
 "sp-cfgproxy": "Подмена работает только в @Configuration (proxyBeanMethods=true). На @Component / @Configuration(proxyBeanMethods=false) проксирования нет — прямой вызов @Bean-метода создаст НОВЫЙ объект мимо контейнера, и у тебя окажется два разных инстанса 'синглтона'.",
 "sp-circular": "Ранняя ссылка кладётся в кеш ДО проксирования. Если бин участвует в цикле и должен быть обёрнут в AOP-прокси (@Transactional/@Async), инжектится сырой объект без прокси — Spring это ловит и падает на старте (BeanCurrentlyInCreationException), если не успевает доресолвить.",
 "sp-scope": "ObjectProvider/Provider.get() и scoped-proxy дают новый prototype на каждый вызов, но Spring НЕ управляет его уничтожением — @PreDestroy у prototype-бина не вызывается никогда, освобождать ресурсы надо вручную.",
 "sp-rollback": "rollbackOn задаётся на самой аннотации, а не глобально: @Transactional(rollbackFor=Exception.class). И ещё грабли — если внутренний метод бросил и пометил транзакцию rollback-only, внешний 'поймал' исключение и хочет закоммитить, он получит UnexpectedRollbackException.",
 "sp-prop": "REQUIRES_NEW берёт ВТОРОЕ соединение из пула, держа первое приостановленным. При pool size=1 (или нехватке коннектов) это классический самодедлок: внешняя транзакция держит коннект и ждёт второй, которого в пуле уже нет.",
 "sp-osiv": "OSIV маскирует LazyInitializationException в dev и взрывается в проде: соединение из пула удерживается на всё время сериализации JSON, под нагрузкой пул исчерпывается и запросы встают в очередь. В Boot отключается spring.jpa.open-in-view=false (по умолчанию true + warning в логе).",
 "sp-propord": "В Boot 2.4+ порядок мерджа profile-specific файлов изменился (spring.config.import, документный порядок), и @PropertySource НЕ участвует в этой иерархии вообще — он грузится раньше и его легко перебьёт что угодно.",
 "x-sp-optimistic-lock": "@Version проверяется только при dirty-update самой версионируемой сущности. Изменение лишь её дочерней @OneToMany-коллекции (другой таблицы) version родителя не двигает — lost update в связанных данных оптимистик-лок не поймает, нужен @OptimisticLock(LockModeType.OPTIMISTIC_FORCE_INCREMENT).",
 "x-sp-isolation": "PostgreSQL не имеет READ_UNCOMMITTED (его dirty read недоступен, тихо апгрейдится до READ_COMMITTED), а его REPEATABLE_READ на деле уже почти snapshot/SERIALIZABLE — поведение уровней изоляции зависит от СУБД, не от спеки JPA.",
 "sp-dirty": "Dirty checking работает только для managed-сущностей в открытой сессии. Отредактировал detached-объект (вернулся из контроллера, сессия закрыта) — UPDATE не уйдёт; нужен явный merge/save, и merge возвращает НОВЫЙ managed-инстанс, а твой старый остаётся detached.",
 "g-sp-scheduled": "fixedDelay/fixedRate с одним default-потоком: долгая задача блокирует ВСЕ остальные @Scheduled в приложении, а не только себя. Нужен пул: задать spring.task.scheduling.pool.size или свой ThreadPoolTaskScheduler, иначе одна зависшая джоба останавливает планировщик целиком.",
 "g-sp-async-self": "Дефолтный executor @Async — SimpleAsyncTaskExecutor, который НЕ пулится: создаёт новый поток на каждый вызов и под нагрузкой положит JVM через OOM из-за тысяч потоков. В проде обязательно задавать свой ThreadPoolTaskExecutor (в Boot 3.2+ можно включить виртуальные потоки).",
 "g-sp-eventlistener": "@TransactionalEventListener(AFTER_COMMIT) по умолчанию выполняется в ТОМ ЖЕ потоке после коммита, но транзакция уже закрыта — любой save() в слушателе либо требует REQUIRES_NEW, либо тихо не запишется (нет активной транзакции). Если транзакции при публикации нет вообще — слушатель по умолчанию вообще не вызовется.",
 "g-sp-value-spel": "@Value читается до автоконфигурации некоторых property source'ов, плюс на конструкторе зависимого бина значение может быть ещё не подставлено. Для типобезопасности и порядка лучше @ConfigurationProperties. И помни: ${} с отсутствующим ключом без дефолта роняет старт, а #{} (SpEL) выполняет произвольное выражение — инъекция извне опасна.",
 "g-sp-controlleradvice": "401/403 из Security-фильтров надо обрабатывать через AuthenticationEntryPoint/AccessDeniedHandler, а не @ControllerAdvice. Частая ловушка: бросаешь AccessDeniedException ВНУТРИ контроллера — вот его @ControllerAdvice как раз поймает (он уже за DispatcherServlet), а тот же эксепшн из фильтра — нет.",
 "sp-proxytype": "С Boot 2.x по умолчанию spring.aop.proxy-target-class=true — CGLIB используется даже при наличии интерфейса. Поэтому 'есть интерфейс → JDK-прокси' в чистом Boot часто неверно; и при CGLIB инжект бина по типу интерфейса всё равно работает, а вот final-метод молча теряет advice.",
 "de-lsp": "LSP ломается тихо: компилятор пропускает override, который сужает контракт (бросает UnsupportedOperationException, ужесточает precondition, ослабляет postcondition). Классика в JDK — Collections.unmodifiableList: тип List, но add() кидает исключение в рантайме, нарушая контракт List.",
 "de-singleton": "Spring/Quarkus-бин со scope singleton — НЕ Singleton из GoF: это один экземпляр на контейнер, а не на JVM, и не потокобезопасен сам по себе. Главная грабля singleton-бина — хранить в поле мутабельное состояние (счётчик, текущего юзера): на проде разные запросы из разных потоков перетирают друг друга.",
 "de-builder": "Builder не даёт неизменяемость и валидность сам по себе: если build() не проверяет обязательные поля, получишь полусобранный объект с null. Валидацию инвариантов делай внутри build()/конструктора, а не в сеттерах билдера.",
 "x-de-observer": "Встроенный java.util.Observer/Observable объявлены @Deprecated с Java 9 — не используй. Грабли паттерна: синхронные слушатели делают уведомление по сути блокирующим (один медленный/упавший observer тормозит или роняет весь notify), плюс утечки памяти, если забыл отписаться.",
 "p-ddd-one-agg-per-tx": "Нарушение всплывает не сразу, а под нагрузкой: правка двух аггрегатов в одной транзакции расширяет границу блокировки и даёт deadlock/contention на горячих строках. Цена правила — eventual consistency: между двумя транзакциями система в промежуточном состоянии, и UI/потребитель должны это переживать.",
 "g-de-value-object": "Если VO мутабельный или забыл переопределить equals/hashCode по значениям — он ломается как ключ HashMap и при сравнении (два Money(100,KZT) окажутся != ). Ещё грабля: equals по полям обязан включать ВСЕ значимые поля (валюту, не только сумму), иначе 100 USD == 100 KZT.",
 "g-de-proxy": "Spring/Quarkus-прокси не перехватывает self-invocation: вызов this.method() внутри того же бина идёт мимо прокси, поэтому @Transactional/@Cacheable на внутреннем вызове просто не срабатывают. Также прокси на private/final-методах не вешается.",
 "x-de-dip-vs-di": "Field injection (@Inject/@Autowired на поле) — частая грабля: прячет зависимости от конструктора, мешает тестам (нельзя подставить мок без рефлексии/контейнера) и не ловит циклические зависимости на старте. Предпочитают constructor injection.",
 "g-de-anemic-vs-rich": "Главный практический подвох богатой модели — JPA/Hibernate требует no-arg конструктор и доступ к полям, что тянет назад к сеттерам и публичным полям. Поэтому инварианты в rich-модели охраняют через фабричные методы и приватные сеттеры, а не публичный setter, который ORM всё равно может обойти.",
 "de-comp-inherit": "Хрупкий базовый класс на практике: переопределение метода, который базовый класс зовёт изнутри другого своего метода (self-call), ломает поведение неочевидно. Поэтому если наследование всё же нужно — либо проектируй класс под наследование явно и документируй self-calls, либо делай его final.",
 "alg-hidden-n2": "Конкатенация String в цикле — это O(n²) по времени И по мусору: каждый '+' создаёт новый объект и копирует всё накопленное. Лекарство — StringBuilder. Но javac уже оптимизирует одиночный 'a+b+c' в один StringBuilder; квадрат возникает именно когда '+' внутри цикла.",
 "alg-recursion": "StackOverflowError ловит не глубина сама по себе, а размер фрейма: много локалок/крупные параметры = меньше допустимая глубина. Дефолтный стек ~512KB–1MB ≈ десятки тысяч кадров; поднять можно -Xss или флагом размера стека в new Thread(...), но это лечит симптом, а не причину.",
 "alg-sort": "Arrays.sort(int[]) — это dual-pivot quicksort, у которого есть худший O(n²) и он НЕ стабилен; Arrays.sort(Object[]) и Collections.sort — TimSort, стабильный O(n log n). Поэтому для примитивов нельзя полагаться на стабильность, а для объектов — можно.",
 "x-alg-stream-overhead": "Боксинг убивает не только скорость, но и параллелизм/память: используй IntStream/LongStream вместо Stream<Integer>. И parallelStream по умолчанию шарит общий ForkJoinPool.commonPool — одна блокирующая операция в нём тормозит весь процесс.",
 "alg-binsearch": "Классический баг: mid = (lo+hi)/2 переполняет int на больших индексах. Пиши lo + (hi-lo)/2. В Java есть готовый Arrays.binarySearch/Collections.binarySearch, но на НЕотсортированном массиве он молча вернёт мусорный (любой) результат, а не ошибку.",
 "alg-balanced": "HashMap «озеленяет» бакет в red-black дерево только при TREEIFY_THRESHOLD=8 узлах И вместимости таблицы ≥64 (MIN_TREEIFY_CAPACITY), иначе сначала ресайзит. И требует, чтобы ключи были Comparable, иначе сравнивает по identity hash — дерево не спасёт от плохого hashCode.",
 "alg-hashtable": "O(1) держится, только пока hashCode равномерный и согласован с equals. Сломанный/мутирующий после put hashCode → элемент «теряется» в мапе (не находится тем же ключом). В Java 8 длинная цепочка превращается в дерево (O(log n)), что смягчает worst-case, но не отменяет требование к hashCode.",
 "alg-greedy": "Главная ловушка: жадность кажется правильной на примерах, но даёт неоптимум — классика размена монет {1,3,4} на сумму 6 (жадный 4+1+1=3 монеты вместо 3+3=2). Корректность жадного нужно ДОКАЗЫВАТЬ (matroid/exchange argument), а не проверять на паре тестов.",
 "alg-heap-pq": "PriorityQueue в Java — это min-heap по natural ordering; для max нужен Comparator.reverseOrder(). Её итератор и toString НЕ возвращают элементы в отсортированном порядке (только peek/poll сортируют). И она не потокобезопасна — для конкурентного доступа PriorityBlockingQueue.",
 "g-alg-open-vs-chain": "В открытой адресации простое удаление ломает поиск (разрывает цепочку проб) — нужны tombstone-метки, которые со временем засоряют таблицу и требуют rehash. Поэтому при частых удалениях чаще берут цепочки.",
 "g-alg-dijkstra": "Дейкстра ломается именно на отрицательных рёбрах, а не на отрицательных циклах — даже одно отрицательное ребро без цикла даёт неверный результат, потому что вершина фиксируется как 'окончательная' преждевременно. В реализации на PriorityQueue не забывай отбрасывать устаревшие записи (lazy deletion), иначе вершина обрабатывается повторно.",
 "g-alg-lru": "LinkedHashMap не потокобезопасен, а accessOrder=true МУТИРует структуру даже на get() — два параллельных чтения = ConcurrentModificationException/порча. Для конкурентного LRU нужна внешняя синхронизация или Caffeine/Guava Cache.",
 "g-alg-amortized": "Амортизированный O(1) ломается, если игнорировать его условие: каждый рост ArrayList копирует весь массив, поэтому при известном размере зови ensureCapacity/конструктор с capacity. А вот add в начало/середину — это O(n) на КАЖДУЮ операцию, амортизация тут не помогает.",
 "g-alg-bit-tricks": "В Java сдвиг вправо: >> сохраняет знак (арифметический), >>> заполняет нулями (логический) — для беззнаковых битовых масок нужен именно >>>. И величина сдвига берётся по модулю 32 для int / 64 для long: x<<32 == x, а не 0 — частый сюрприз.",
 "co-volatile": "volatile long/double до Java можно было читать «рваными» половинами — сама volatile это чинит, но обычные (не volatile) long/double до сих пор не атомарны при записи на 32-битных JVM. И главная грабля: long счётчик под volatile всё равно нельзя инкрементить (++) — нужен AtomicLong.",
 "co-hb": "Частая ошибка: 'я взял volatile/synchronized — значит видно'. Видимость даёт только ПАРНОЕ совпадение: запись и чтение должны идти через ОДИН и тот же монитор/volatile-переменную. Запись под одним локом и чтение под другим (или без него) happens-before НЕ создаёт.",
 "co-chm": "ConcurrentHashMap атомарен по отдельной операции, но get-затем-put — это гонка. Используй computeIfAbsent/merge/putIfAbsent. И не вызывай внутри computeIfAbsent операции над той же мапой по другому ключу — можно словить deadlock/IllegalStateException (рекурсивное обновление).",
 "co-vt": "Виртуальные потоки не ускоряют CPU-bound код (карриеров всё равно столько же, сколько ядер) — выигрыш только на blocking IO. И их нельзя пулить: смысл в том, чтобы создавать новый на каждую задачу; ThreadLocal на миллионах vthreads — это утечка памяти.",
 "co-tl": "remove() в finally обязателен, но есть вторая грабля: значение по умолчанию через withInitial вычисляется ЛЕНИВО на первом get() уже на потоке-исполнителе пула — переопределённый initialValue не спасает от протечки между запросами, нужен именно remove().",
 "co-pool-reject": "Дефолтный Executors.newFixedThreadPool использует НЕОГРАНИЧЕННУЮ LinkedBlockingQueue — RejectedExecutionHandler не сработает никогда, очередь будет расти до OOM вместо бэкпрешера. Для реального backpressure нужен явный ThreadPoolExecutor с bounded-очередью и CallerRunsPolicy.",
 "x-co-pinning-vthreads": "С Java 24 (JEP 491) pinning на synchronized убран — vthread больше не закрепляет carrier на блокирующих мониторах. До 24 правило 'меняй synchronized на ReentrantLock' актуально; pinning остаётся только при нативных вызовах (JNI) и внутри методов с synchronized-блоком в нативном стеке.",
 "x-co-double-checked-locking": "volatile-чтение в DCL надо кэшировать в локальную переменную (читать поле один раз), иначе два volatile-чтения — лишний барьер на горячем пути. И для простого синглтона DCL вообще не нужен: holder-idiom (статический вложенный класс) проще и без volatile.",
 "x-co-false-sharing": "@Contended (jdk.internal.vm.annotation) работает только с флагом -XX:-RestrictContended или в JDK-классах; в обычном коде паддинг приходится делать вручную. JDK уже паддит LongAdder/ConcurrentHashMap counter cells — поэтому LongAdder обгоняет AtomicLong на высокой конкуренции именно за счёт устранения false sharing.",
 "x-co-completablefuture-compose": "thenApply/thenCompose без явного Executor выполняются на потоке, который завершил предыдущий этап (часто это common ForkJoinPool или поток-комплитер) — блокирующий код там тормозит весь пул. Для блокирующих шагов всегда передавай свой Executor (thenApplyAsync(fn, pool)).",
 "co-executor": "shutdown() не прерывает уже бегущие задачи и не ждёт их — нужен shutdownNow() + awaitTermination. И submit() глотает исключения внутри Future: если не звать get(), упавшая задача умрёт молча, без стектрейса в логах.",
 "co-sync-tools": "CyclicBarrier при таймауте/прерывании ОДНОГО потока ломается весь барьер (BrokenBarrierException у всех остальных) — частая боль. Semaphore по умолчанию нечестный (non-fair): возможна starvation; и release() можно вызвать больше раз, чем acquire — он молча раздаст лишние пермиты.",
 "co-cow": "Каждая запись копирует весь массив O(n) — на больших или часто меняющихся списках это убивает производительность и память. Итератор работает на снимке: ты НЕ увидишь изменений, сделанных после его создания (читаешь устаревшие данные).",
 "g-co-stampedlock": "StampedLock НЕ реентрантный (повторный захват тем же потоком — deadlock) и не поддерживает Condition. После оптимистичного чтения обязательно копируй поля в локальные переменные ДО validate() — если читать после, можно увидеть полу-обновлённое состояние.",
 "g-co-blockingqueue-types": "Главная прод-грабля: LinkedBlockingQueue без явной ёмкости безгранична — теряется backpressure, продьюсер забивает память до OOM, потребитель не успевает. Для пулов/очередей под нагрузкой всегда задавай capacity явно.",
 "g-co-sleep-vs-wait": "wait/notify надо вызывать строго внутри synchronized на том же мониторе (иначе IllegalMonitorStateException), и wait ВСЕГДА в цикле while(условие) — из-за spurious wakeups и того, что между notify и пробуждением условие мог изменить другой поток.",
 "g-co-tlrandom": "Нельзя сохранять ThreadLocalRandom.current() в поле и переиспользовать с другого потока — current() надо звать каждый раз на нужном потоке, иначе теряется весь смысл (общий seed → contention и пересечение последовательностей).",
 "g-co-condition-lostwakeup": "await() надо звать только удерживая lock и обязательно в цикле while(условие) — как и wait. И при использовании отдельных condition легко промахнуться: signal на 'notFull' не разбудит ждущих на 'notEmpty', так что нужно сигналить именно тот condition, чьё условие стало истинным.",
 "devops-deploy": "Blue-green требует совместимости БД с обеими версиями одновременно (катятся на общую базу): несовместимая миграция ломает откат на blue. И canary, и blue-green бесполезны для stateful-сессий в памяти инстанса — нужен sticky session либо вынос сессии наружу.",
 "devops-serverless": "Cold start особенно больно бьёт по JVM (Quarkus/Spring) из-за прогрева — отсюда GraalVM native image для Lambda. Второй неочевидный капкан: Lambda масштабируется по событиям без счёта, и пул коннектов к БД мгновенно исчерпывается (тысячи параллельных инстансов × коннект) — нужен RDS Proxy/pooler.",
 "x-ops-container-vs-vm": "Контейнер делит ядро хоста, поэтому Linux-образ не запустится на ядре Windows нативно (Docker Desktop поднимает скрытую Linux-VM). И из-за общего ядра контейнер видит CPU/RAM всего хоста, а не свои лимиты — старые JVM до контейнерных флагов вычисляли heap по всей памяти ноды и ловили OOM.",
 "x-ops-k8s-basics": "Service типа ClusterIP даёт стабильный DNS, но при долгоживущих TCP/gRPC-коннектах балансировки по подам фактически нет: соединение прибивается к одному поду и держится. Для gRPC нужен L7-балансировщик или headless Service + клиентский балансинг.",
 "x-ops-horizontal-scaling-lb": "Stateless — это не только про сессию: локальный кэш, счётчики в памяти, фоновые таймеры и запись на локальный диск тоже ломаются при N инстансах. Классический баг — крон/планировщик внутри приложения, который после масштабирования срабатывает на каждом инстансе сразу.",
 "ops-maven": "`mvn install` без явного `test` всё равно прогонит тесты (фаза test идёт раньше package) — пропустить можно только `-DskipTests` (скомпилит, но не запустит) или `-Dmaven.test.skip=true` (даже не скомпилит). И install кладёт артефакт в локальный ~/.m2, а не в общий Nexus — это deploy; путаница ломает шаринг между разработчиками.",
 "g-ops-feature-flag-debt": "Флаг, который читается в разных местах запроса, может дать неконсистентность, если переключить его в середине обработки — снапшоти значение флага один раз на запрос. И флаги для бизнес-логики (а не релизные) живут вечно — их нельзя чистить, что размывает смысл «временного флага».",
 "g-ops-prometheus-pull": "Скрейп даёт метрику только в момент опроса (обычно 15-60с) — короткий всплеск ошибок между скрейпами Prometheus не увидит. И counter, обнулённый рестартом пода, корректно считается только через rate()/increase(), которые умеют детектить reset; raw-разница даст отрицательный мусор.",
 "g-ops-gradle-vs-maven-incremental": "Gradle build cache коварен: «грязный» вход (не объявленный как input таски) даёт ложное cache hit и старый артефакт — отсюда привычка `--no-build-cache`/`clean` при загадочных багах. Демон тоже копит состояние между билдами и иногда требует `--stop`.",
 "sd-interview-flow": "⚠️ Не молчи, считая в уме. Озвучивай допущения («предположим 100M записей, 10:1 read/write») — иначе интервьюер не понимает, откуда у тебя цифры, и думает что ты угадал.",
 "sd-latency-budget": "⚠️ Усреднённая latency лжёт. Система с avg=50ms может иметь p99=2s — и именно эти 1% юзеров громче всех жалуются. Всегда меряй и обещай в перцентилях.",
 "sd-availability-nines": "⚠️ Доступность последовательной цепочки — это ПРОИЗВЕДЕНИЕ, а не минимум. Пять сервисов по 99.9% дают уже ~99.5%. Чем больше хопов, тем ниже итоговая доступность.",
 "sd-sql-vs-nosql": "⚠️ «NoSQL = без схемы» — миф. Схема есть, она просто переезжает в код приложения. Без дисциплины это превращается в свалку разнородных документов, которую невозможно мигрировать.",
 "sd-sharding-key": "⚠️ Самая частая ошибка — шард-ключ с низкой кардинальностью (например, страна или статус). Весь трафик стянется в пару шардов, и ты получишь распределённую систему со скоростью одной ноды.",
 "sd-replication": "⚠️ Read-реплики масштабируют ЧТЕНИЕ, но не запись — все записи всё равно идут через один мастер. Если упёрся в потолок записи, реплики не спасут, нужен шардинг.",
 "sd-rate-limiter": "⚠️ Fixed window на границе окна пропускает до 2×лимита: N запросов в конце минуты + N в начале следующей. Для жёстких SLA берут sliding window.",
 "sd-url-shortener-id": "⚠️ Не используй UUID как короткий код — 36 символов, никакой «короткости». UUID годится только как внутренний PK, не как публичный short.",
 "sd-url-shortener-redirect": "⚠️ Поставив 301, ты НЕ сможешь нормально пересчитать клики и переназначить ссылку — браузеры и CDN закэшируют редирект надолго. Откатить тяжело.",
 "sd-feed-fanout": "⚠️ Чистый push на звезде = «fan-out storm»: один твит порождает десятки миллионов записей и лаги. Поэтому звёзд всегда выносят в pull-ветку.",
 "sd-notifications": "⚠️ Без jitter в backoff все воркеры ретраят синхронно и устраивают «thundering herd» по провайдеру в момент его восстановления. Добавляй случайный разброс.",
 "sd-counter-leaderboard": "⚠️ ZINCRBY на одном ключе для очень популярного объекта тоже создаёт hot-key в Redis — упрётся в один шард/поток. Для экстремальной записи комбинируй sharded counters + периодический сброс агрегата в ZSET.",
 "sd-payment-ledger": "⚠️ Идемпотентность по «сумма+счёт+время» — ловушка: два легитимных одинаковых платежа схлопнутся в один. Ключ должен генерировать клиент заранее (на кнопке/в форме), а не сервер.",
 "sd-chat-delivery": "⚠️ Глобальный порядок на весь мессенджер не нужен и не масштабируется — порядок важен только внутри одного диалога. Не делай один глобальный счётчик-боттлнек.",
 "sd-object-storage-upload": "⚠️ Pre-signed URL = capability: кто получил ссылку, тот и пишет. Делай короткий TTL и узкие права (только PUT, только этот key), иначе утечка ссылки = запись чужого.",
 "sd-autocomplete-search": "⚠️ Trie в памяти на весь корпус запросов огромен. В проде — шардируют по первой букве/хешу префикса и держат только top-K в узлах, а не все варианты.",
 "sd-distributed-cache": "⚠️ Распространённая ошибка инвалидации — обновлять кэш ПОСЛЕ записи в БД (set вместо delete): при гонке двух апдейтов в кэше осядет старое значение. Безопаснее delete-on-write, пусть следующий read перечитает.",
 "bld-lifecycle-phases": "⚠️ Нюанс: `install` кладёт артефакт в ЛОКАЛЬНЫЙ кэш `~/.m2/repository`, а `deploy` — в УДАЛЁННЫЙ репозиторий. Путать их в CI — классика: думают, что install куда-то «выложил».",
 "bld-dependency-scopes": "⚠️ Нюанс: `provided` НЕ транзитивна. Если твоя либа объявила что-то provided, потребитель твоей либы это не получит — он должен сам предоставить. Частый источник NoClassDefFoundError у downstream.",
 "bld-version-mediation": "⚠️ Нюанс: nearest-wins может тихо понизить версию (downgrade) до дырявой/старой, потому что она оказалась ближе. Безопаснее не полагаться на mediation, а пинить версии в dependencyManagement.",
 "bld-dependency-management-bom": "⚠️ Нюанс: dependencyManagement переопределяет ДАЖЕ транзитивные версии. Это его суперсила и одновременно грабли — можно случайно форсить версию глубокой транзитивной либы и сломать совместимость.",
 "bld-multimodule-reactor": "⚠️ Нюанс: при `-pl app` без `-am` reactor возьмёт core из `~/.m2` (возможно устаревший!), а не пересоберёт. Забыл `-am` — ловишь сборку против старого core.",
 "bld-profiles": "⚠️ Нюанс: `activeByDefault` коварен — он работает, ТОЛЬКО пока не активирован ни один другой профиль через -P в этом же pom. Активировал любой другой -P — дефолтный молча выключился. Лучше активировать по property с дефолтным значением.",
 "bld-fatjar-shade-relocation": "⚠️ Нюанс: relocation переписывает имена пакетов в байткоде, но НЕ чинит строковые ссылки в рефлексии/конфигах (Class.forName(\"com.google...\")). После shading такой код молча падает в рантайме.",
 "bld-impl-vs-api": "⚠️ Нюанс: `compile` устарела и удалена в Gradle 7+. Старые гайды с `compile` фактически = `api` (с утечкой), что и было причиной раздутых classpath. Мигрируя, по умолчанию переводи на `implementation`, а на `api` — только где реально нужно.",
 "bld-version-resolution": "⚠️ Нюанс: `force` (старый способ) грубо переопределяет версию без объяснения причины и плохо комбинируется. Современный путь — `constraints` + `strictly`, они дают понятные сообщения о конфликте и rich-версии (диапазоны, reject).",
 "bld-build-cache": "⚠️ Нюанс: привычка гонять `clean` «на всякий случай» убивает инкрементальность и build cache. `clean` нужен редко — при смене Gradle/JDK или подозрении на битый стейт, а не как ритуал перед каждой сборкой.",
 "bld-gradle-vs-maven": "⚠️ Нюанс: «Gradle быстрее» верно только при включённых caching/incremental и корректно объявленных тасках. Плохо написанный build.gradle с побочными эффектами в configuration-фазе может быть медленнее Maven.",
 "bld-dependency-tree": "⚠️ Нюанс: проверяй именно RUNTIME-classpath, а не compile. Часто `dependency:tree` без скоупа вводит в заблуждение — добавь `-Dscope=runtime`, иначе можно чинить не ту версию.",
 "bld-semver-classpath": "⚠️ Нюанс: semver — обещание, а не гарантия. Библиотеки нарушают его (ломают на MINOR). Поэтому одних версий мало — нужны lock-файлы и тесты, ловящие реальный classpath, а не вера в номер версии.",
 "rx-backpressure": "⚠️ Backpressure ≠ «всё магически не упадёт». Если источник push-only и ты выбрал buffer без лимита — получишь тот же OOM, только позже. Всегда задавай границу буфера.",
 "rx-hot-cold": "⚠️ Грабли: дважды подписался на cold WebClient-Flux — отправил два HTTP-запроса, хотя думал, что один. Если нужен один вызов на нескольких подписчиков — `.cache()` или `.share()`.",
 "rx-vs-imperative-loom": "⚠️ Главная ловушка reactive — спрятанный блокирующий вызов (JDBC, `Thread.sleep`, sync-клиент) в event-loop потоке: пропускная способность рушится. На VT той же проблемы нет — блокировать можно.",
 "rx-map-flatmap-concatmap": "⚠️ Классическая ошибка: использовать `map` для асинхронного вызова, который возвращает `Mono<R>`. Получите `Flux<Mono<R>>` — вложенный паблишер, который никто не подпишет. Нужен `flatMap`/`concatMap`.",
 "rx-error-handling": "⚠️ retry переподписывается на ИСТОЧНИК целиком — если в источнике есть побочные эффекты (POST-запрос, инкремент), они повторятся. Для не-идемпотентных операций ретрай опасен.",
 "rx-cold-nothing-without-subscribe": "⚠️ Самая частая ошибка новичка: вызвать `repo.save(x)` и не подписаться — данные не сохранятся, ошибки не будет, тишина. Любой Mono/Uni из IO нужно либо вернуть наверх, либо подписать.",
 "rx-schedulers-blocking": "⚠️ `parallel()` — НЕ для блокирующего IO: пул размером с число ядер, забьёте мгновенно и так же положите throughput. Для блокировки только `boundedElastic` (Reactor) или worker-пул (Quarkus). И несколько `subscribeOn` подряд — обычно баг.",
 "grpc-http2": "⚠️ Нюанс: браузеры не дают коду напрямую управлять HTTP/2-фреймами и trailer'ами, поэтому чистый gRPC из браузера невозможен — нужен gRPC-Web + прокси (Envoy).",
 "grpc-schema-evolution": "⚠️ Нюанс: в proto3 нет `required`, и по умолчанию не отличить «поле не прислали» от «прислали дефолт (0/\"\")». Если разница важна — оборачивай в `optional` (proto3) или wrapper-типы.",
 "grpc-deadlines-status": "⚠️ Нюанс: если не выставить deadline вообще, вызов может висеть бесконечно — gRPC по умолчанию НЕ ставит таймаут. Всегда задавай `withDeadlineAfter` на клиенте.",
 "crypto-aes-modes": "⚠️ Нюанс: повтор nonce в AES-GCM под одним ключом — катастрофа, а не просто 'некрасиво': атакующий может восстановить authentication key и подделывать теги. Под высокой нагрузкой счётчиком на 96 бит легко переполниться — для случайных nonce безопасный лимит ~2^32 сообщений на ключ.",
 "crypto-hash-properties": "⚠️ Нюанс: 'парадокс дней рождения' урезает стойкость к коллизиям вдвое по битам — у SHA-256 collision resistance ~128 бит, не 256. Для подписей это всё ещё с запасом, но при выборе длины хеша держи это в голове.",
 "crypto-password-hashing": "⚠️ Нюанс: bcrypt молча обрезает пароль до 72 байт — длинные парольные фразы и пароли с многобайтовыми UTF-8 символами могут совпасть. Если важны длинные пароли — argon2 или предварительный SHA-512 перед bcrypt (но это свои тонкости).",
 "crypto-hmac": "⚠️ Нюанс: сравнение тегов обычным `Arrays.equals`/`String.equals` течёт по времени — атакующий подбирает тег побайтно по задержке. Всегда constant-time (`MessageDigest.isEqual` в Java). И не путай HMAC (нужен общий секрет) с подписью (приватный/публичный ключ).",
 "crypto-at-rest-in-transit": "⚠️ Нюанс: at-rest шифрование тома защищает только от физического уноса диска — для работающего сервера с правами доступа данные расшифрованы 'прозрачно'. От SQL-инъекции или скомпрометированного приложения disk encryption не спасает; нужно ещё app-level шифрование чувствительных полей.",
 "crypto-encrypt-vs-hash-passwords": "⚠️ Нюанс: на собесе это маркер-вопрос. Ответ 'зашифруем пароли AES' = красный флаг для senior-роли. Правильная формулировка: пароли *хешируют* медленным алгоритмом с солью; *шифруют* — обратимые данные, которые надо прочитать назад.",
 "crypto-asymmetric": "⚠️ Нюанс: «зашифровать приватным ключом» в обиходе часто говорят про подпись, но это путаница. RSA-подпись — это не шифрование приватным ключом, а отдельная операция (sign/verify). Не путай Cipher и Signature в API: для подписи бери класс Signature.",
 "crypto-dh-fs": "⚠️ Нюанс: сам по себе DH не защищает от MITM — это просто согласование ключа без аутентификации. Аутентичность даёт уже подпись/сертификат поверх него. «DH = безопасно» без проверки личности собеседника — ложное чувство защиты.",
 "crypto-pki-chain": "⚠️ Нюанс: классическая ошибка в Java/сервисах — сервер отдаёт только лист без промежуточного сертификата. В браузере работает (он подтянет intermediate из кэша), а строгий клиент типа curl/Java падает с «unable to verify». Всегда отдавай полную цепочку (fullchain.pem), кроме корня.",
 "crypto-tls-handshake": "⚠️ Нюанс: распространённое заблуждение — «TLS шифрует данные RSA-ключом сервера». Нет: RSA/ECDSA-ключ сервера только подписывает/аутентифицирует. Данные всегда шифрует выведенный симметричный ключ. Если бы данные шли через RSA, соединение было бы дико медленным и без forward secrecy.",
 "crypto-jwt-sign": "⚠️ Нюанс: никогда не доверяй полю alg из самого токена. Печально известная атака — клиент меняет alg на none или с RS256 на HS256, и кривая библиотека проверяет HMAC публичным ключом (который общеизвестен) — подпись «сходится». Жёстко задавай разрешённые алгоритмы в коде верификации.",
 "api-richardson-maturity": "⚠️ Нюанс: гнаться за L3 без реальной нужды — оверинжиниринг. HATEOAS усложняет и клиент, и сервер, а большинство фронтов всё равно хардкодят URL. Берите L3 только если клиенты по-настоящему слабосвязаны (публичный API, долгая эволюция).",
 "api-status-codes": "⚠️ Нюанс: 422 формально из WebDAV (RFC 4918), но прижился в REST для валидации. Часть команд осознанно используют только 400 ради простоты — это допустимо, главное единообразие в рамках одного API, а не «тут 400, там 422 наугад».",
 "api-idempotency": "⚠️ Нюанс: храните под ключом не «факт обработки», а сам результат+статус, и обрабатывайте гонку (два параллельных запроса с одним ключом) через уникальный индекс/блокировку, иначе оба пройдут. И обязательно TTL на ключи — иначе таблица распухнет.",
 "api-versioning": "⚠️ Нюанс: при header/media-type не забудь `Vary: Api-Version` (или Vary: Accept), иначе CDN/прокси отдадут закэшированный ответ не той версии. Это классические грабли, которые ловят уже в проде.",
 "api-problem-json": "⚠️ Нюанс: не клади в detail сырой stacktrace или внутренние сообщения БД — это утечка для атакующего. detail должен быть безопасным для клиента; технические подробности — в логи по traceId/instance.",
 "api-resources-verbs": "⚠️ Нюанс: не пытайся впихнуть ВСЁ в чистый CRUD ради догмы. Бизнес-действия типа «подтвердить платёж», «отменить заказ» часто чище выразить POST /resource/{id}/action, чем извращаться с PATCH состояния. Догматизм тут вредит читаемости.",
 "api-pagination-cursor": "⚠️ Нюанс: keyset «из коробки» даёт только следующую/предыдущую страницу. Для двунаправленной навигации нужны два курсора (before/after) и аккуратная обработка границ. И помни про tie-breaker — без уникального хвоста в ORDER BY курсор будет терять или дублировать строки.",
 "api-rate-limit-headers": "⚠️ Нюанс: заголовки rate-limit не стандартизированы жёстко — GitHub, Stripe, Twitter отдают их по-разному (X-RateLimit- vs RateLimit- vs свои). Никогда не хардкодь имена под один API; читай Retry-After как основной источник истины, остальное — best-effort.",
 "api-content-negotiation": "⚠️ Нюанс: версионирование через Accept (media-type versioning) красиво на бумаге, но ломает простое тестирование из браузера/curl и путает прокси. Для корпоративного сервиса, который поддерживают в т.ч. junior'ы, /v2/ в URL почти всегда практичнее — выбирай Accept-версии только если у тебя жёсткая HATEOAS/гипермедиа-дисциплина.",
 "api-backward-compat": "⚠️ Нюанс: «добавить поле безопасно» ломается, если у клиента строгая JSON-схема с additionalProperties:false или строгий десериализатор (например, старый Jackson с FAIL_ON_UNKNOWN_PROPERTIES). Тогда даже новое поле = 500 у клиента. Всегда проверяй, что потребители — tolerant readers, прежде чем считать additive-изменение безопасным.",
 "api-rest-rpc-grpc-graphql": "⚠️ Нюанс: GraphQL легко превращается в перформанс-ловушку — один «красивый» вложенный запрос порождает N+1 обращений к БД и обходит привычные HTTP-кэши/rate-limit'ы. Нужны DataLoader-батчинг, ограничение глубины/сложности запроса и продуманная авторизация на полях. Это не «REST, только удобнее» — это другой класс эксплуатационных задач.",
 "ds-trie": "⚠️ Нюанс: Trie не находит подстроку в середине («ats» в «cats») — он только про префиксы. Для произвольных подстрок нужен suffix trie/suffix automaton или просто индекс. И не делай детей массивом на 65536 для Unicode — лопнет память, бери HashMap.",
 "ds-balanced-bst": "⚠️ Нюанс: если тебе не нужны упорядоченные операции (диапазоны, ceiling/floor, отсортированный обход) — бери HashMap, у него O(1) против O(log n). Балансированное BST оправдано именно ради порядка, а не ради скорости точечного поиска.",
 "ds-union-find": "⚠️ Нюанс: рекурсивный find с path compression на цепочке в миллионы узлов может словить StackOverflow до первого сжатия. В проде на больших n делают итеративный find в два прохода либо path halving (parent[x] = parent[parent[x]]).",
 "ds-fenwick-segtree": "⚠️ Нюанс: классический Fenwick — на сумму/xor (обратимые операции: range = prefix(r) - prefix(l-1)). Для min/max на произвольном отрезке вычитание не работает — там нужен segment tree. Не пытайся «вычесть минимумы».",
 "ds-lru-cache": "⚠️ Нюанс: голый LinkedHashMap НЕ потокобезопасен — при многопоточном доступе перестройка порядка ломает структуру. Либо оборачивай в synchronized/Collections.synchronizedMap, либо бери Caffeine. И не забудь accessOrder=true: по умолчанию LinkedHashMap хранит порядок ВСТАВКИ, а не доступа — получишь FIFO вместо LRU.",
 "ds-bloom-filter": "⚠️ Нюанс: нельзя превышать заявленное expectedInsertions — после переполнения FP rate деградирует нелинейно и быстро уходит к ~100%. Размер фиксирован при создании, «дорастить» нельзя — только пересоздать (или брать Scalable Bloom).",
 "ds-heap-priority-queue": "⚠️ Нюанс: PriorityQueue в Java НЕ потокобезопасна и НЕ обеспечивает FIFO для равных приоритетов (порядок равных не определён). Нужна конкурентность — PriorityBlockingQueue; нужен FIFO-tiebreak — добавляй в компаратор монотонный seq-номер.",
 "ds-consistent-hashing": "⚠️ Нюанс: consistent hashing решает «минимум переездов», но НЕ решает горячие ключи. Если один ключ получает 50% трафика, vnodes не помогут — он всё равно на одном узле. Для hot keys нужен отдельный механизм (репликация ключа, кэш перед шардом).",
 "ds-cardinality-sketches": "⚠️ Нюанс: оба врут на «хвостах». HLL на маленькой кардинальности (десятки элементов) использует поправки/linear counting, иначе ошибка велика. CMS сильно переоценивает редкие элементы при перегрузе — для редких частот результат почти бесполезен, точность держится только для частых (heavy hitters).",
 "mq-exchanges": "⚠️ Нюанс: одно сообщение, привязанное N бинами к одной очереди, всё равно попадёт в неё один раз (RabbitMQ дедуплицирует по очереди). Но в РАЗНЫЕ очереди уйдут независимые копии — каждая со своим ack.",
 "mq-ack-prefetch": "⚠️ Нюанс: requeue=true на постоянно падающем сообщении = бесконечный hot loop, пожирающий CPU. Лечится x-delivery-limit (quorum queues) или счётчиком ретраев + DLX.",
 "mq-rabbit-vs-kafka": "⚠️ Нюанс: «RabbitMQ нельзя перечитать» — про классические очереди. Streams в RabbitMQ (с 3.9) — это лог-структура с оффсетами, ближе к Kafka. Не путай classic/quorum queues со streams.",
 "mq-dlx": "⚠️ Нюанс: TTL очереди истекает только у сообщения В ГОЛОВЕ очереди — RabbitMQ проверует expiry при попытке доставить. Сообщение в середине может «пережить» свой TTL, пока до него не дойдёт очередь чтения.",
 "mq-sqs": "⚠️ Нюанс: даже FIFO даёт exactly-once на ДОСТАВКУ-в-очередь и обработку через дедуп, но это не магическая защита от двойного сайд-эффекта при сбое между обработкой и delete. Идемпотентность всё равно полезна.",
 "mq-ordering": "⚠️ Нюанс: «нужен порядок» почти всегда означает «порядок в пределах агрегата», а не глобальный. Требование глобального тотального порядка через брокер — красный флаг дизайна: оно убивает масштабирование.",
 "mq-competing-consumers": "⚠️ Нюанс: добавление консьюмеров сверх числа партиций (Kafka) не ускоряет — лишние просто idle. В RabbitMQ предел иной: разумность prefetch и способность даунстрима (БД, API) держать нагрузку, иначе перенесёшь bottleneck дальше.",
 "mq-queue-vs-stream": "⚠️ Нюанс: попытка сделать «реплей» поверх обычной очереди (перечитать обработанное) — антипаттерн: придётся хранить копии и городить велосипед. Нужен реплей — это сигнал, что тебе изначально нужен лог, а не очередь.",
 "gap-sc-structured-task-scope": "⚠️ Нюанс: после `scope.fork()` ОБЯЗАТЕЛЕН `scope.join()` (или `joinUntil`) перед чтением результатов через `subtask.get()` — иначе `get()` кинет `IllegalStateException`, потому что результат ещё не зафиксирован. И scope нельзя расшаривать между потоками: он привязан к потоку, который его создал (confinement). Отмена детей делается через interrupt, поэтому дочерние задачи должны корректно реагировать на InterruptedException, иначе ShutdownOnSuccess/Failure не сможет их быстро погасить.",
 "gap-jwt-alg-none": "⚠️ Нюанс: «у меня jjwt последней версии, я защищён» — не всегда. Разбор токена и проверка подписи это разные шаги. Если в коде где-то есть `Jwts.parser().build().parse(token)` без `verifyWith(key)` (старое `parseClaimsJws` vs `parseClaimsJwt`), ты можешь читать payload неподписанного токена и случайно доверять ему дальше по коду. Подпись должна проверяться явно, а её отсутствие — это ошибка, а не «пустой алгоритм».",
 "gap-alg-floyd-cycle": "⚠️ Нюанс: условие цикла `while (fast != null && fast.next != null)` — порядок проверок важен. Если проверить `fast.next.next` без предварительного `fast.next != null`, получишь NPE на нечётной длине списка без цикла. И стартовать оба указателя надо из head (не slow=head, fast=head.next) — иначе ломается формула поиска начала цикла.",
 "gap-alg-quickselect": "⚠️ Нюанс: quickselect ПЕРЕСТАВЛЯЕТ исходный массив (partition мутирует вход). Если массив нельзя портить — копируй заранее, иначе огребёшь баг у вызывающего кода. И второе: индексация k нульбазовая — «медиана» это `k = n/2` (для нечётного n), а «k-й по счёту с единицы» это `k-1`; на собесе путаница в off-by-one тут классическая.",
 "gap-rx-context": "⚠️ Нюанс: типичные грабли — поставить .contextWrite() в самом конце цепочки в надежде, что значение увидят операторы, написанные выше. Это как раз работает (выше = видно). Но обратная ошибка фатальна: если deferContextual стоит НИЖЕ contextWrite (ближе к subscribe), он значение НЕ увидит и упадёт на ctx.get() с NoSuchElementException. Правило: contextWrite должен быть НИЖЕ (ближе к subscribe), чем читающий его deferContextual.",
 "gap-ap-apt-rounds": "⚠️ Нюанс: Lombok тут белая ворона. Стандартный APT новые файлы ПИШЕТ, а Lombok ПРАВИТ существующий AST твоего класса (вставляет getter/setter/toString прямо в дерево User). Официального API для мутации AST в javac нет — Lombok лезет во внутренние com.sun.tools.javac.* классы. Поэтому на новых JDK его регулярно «подбивает» --add-opens/--add-exports, а в IDE нужен отдельный плагин, чтобы редактор видел методы, которых в исходнике физически нет.",
 "gap-oh-direct-memory": "⚠️ Нюанс: классика утечки — короткоживущий direct-буфер внутри долгоживущего объекта. Обёртка пережила реальную надобность, GC до неё не доходит, и native-память тихо растёт. RSS процесса пухнет, а heap-дамп чистый — мониторь именно direct-память (BufferPoolMXBean / NMT), а не только heap. И не делай allocateDirect для мелких/частых буферов: аллокация дороже heap и очистка недетерминирована — пуль или бери heap.",
 "gap-oom-oomkilled-vs-javaoom": "⚠️ Нюанс: `MaxRAMPercentage` управляет ТОЛЬКО heap. Если поставить 90-100%, heap съест почти весь лимит, а metaspace, стеки потоков (по ~1 MB на поток!) и direct-память пойдут поверх — и ядро снова даст 137, хотя Java-OOM так и не случится. Реальные грабли: приложение с пулом из 200 потоков незаметно тратит ~200 MB вне heap. Держи MaxRAMPercentage в районе 70-75% и мониторь RSS контейнера, а не только heap usage.",
 "gap-kms-envelope-encryption": "⚠️ Нюанс: расшифрованный (plaintext) data-key нельзя логировать, кэшировать надолго или писать на диск — это сводит всю схему на нет. Используй его в памяти и сразу обнуляй ссылку. И вторая грабля: при ротации мастера старую версию ключа в KMS НЕ удаляй сразу — пока есть хоть один data-key, закрытый ею, удаление версии = безвозвратная потеря данных.",
 "de-server-lifecycle": "«Сервер» путают с «машиной». На одной машине крутится много серверов-процессов; один логический сервис — это много машин. И ключевое: thread-per-request упирается не в CPU, а в число потоков (память под стеки + context switch) — отсюда event-loop под c10k. Если держишь состояние в памяти процесса (HttpSession в heap) — теряешь горизонтальное масштабирование: запрос обязан попасть на «свой» инстанс (sticky), а упал инстанс — потерял сессию.",
 "inf-autoscale-mechanics": "CPU как метрика врёт для I/O-bound сервисов: поток висит на ответе БД, CPU низкий — HPA не добавит поды, хотя латенси уже растёт. Масштабируй по RPS или глубине очереди. И всегда помни про лаг: метрика усредняется (~15с) + решение + cold start пода = десятки секунд; короткий пик может пройти раньше, чем поды поднимутся — поэтому держат baseline-реплики с запасом.",
 "inf-autoscale-coldstart": "Readiness-проба — твой главный предохранитель: пока под не прогрет, не помечай Ready, и балансировщик не пошлёт на него трафик. На JVM cold start особенно больно (интерпретация → C1 → C2), поэтому Quarkus native / GraalVM AOT — это не хайп, а реальный ответ на autoscaling: старт за мс вместо секунд прогрева. Liveness ≠ readiness: liveness перезапустит живой-но-холодный под и сделает только хуже.",
 "de-estimate-latency": "Эти числа — инструмент дизайна, а не зубрёжка к собесу. Главный вывод: один межрегиональный round-trip дороже сотен локальных операций, поэтому N+1 по сети между регионами убивает латенси, а N+1 к локальной БД лишь неприятен. И помни про «хвост»: средняя латенси врёт — клиент чувствует p99, который при фан-ауте в N сервисов получает worst-of-N и растёт.",
 "de-estimate-qps": "Цель прикидки — не точное число, а архитектурное решение «одна коробка или дата-центр». Частая ошибка: считать по среднему QPS и забыть пик-фактор (вечерний трафик, рассылка, флешмоб) — система ляжет именно на пике, который в разы выше среднего. Всегда: средний → пик-фактор → запас. И отдельно прикидывай bandwidth (QPS × размер ответа) — иногда упираешься в сеть, а не в CPU/диск.",
 "di-leader-raft": "Кворум большинства диктует **нечётный** размер кластера: 3 узла переживут отказ 1, 5 — отказ 2. Чётный (4) даёт ту же отказоустойчивость, что 3, но дороже и рискует tie. Ключевое свойство: лидер не коммитит, не реплицировав на большинство — поэтому при сетевом расколе меньшая часть замирает (CP-выбор по CAP), а не выдаёт второго лидера. Голос идёт только за не-отстающий лог — иначе можно потерять закоммиченные записи.",
 "di-split-brain-fencing": "Главная ловушка — доверять времени: «у меня lease на 10с, я лидер» → процесс встал на 15с GC-паузу, lease истёк, выбрали нового, но старый, проснувшись, всё ещё думает что лидер и пишет. Часы и таймауты ненадёжны (NTP-скачки, паузы, заморозка VM) — доверяй только монотонному fencing-счётчику на стороне ресурса. Кворум предотвращает двух активных лидеров, fencing — добивает зомби, который уже считает себя живым.",
 "di-batch-vs-stream": "Не путай **Lambda-архитектуру** (batch+stream слои) с **AWS Lambda** (FaaS) — одно имя, разные вещи, классический подвох на собесе. Главный нюанс стриминга — **event time vs processing time**: событие произошло в 10:00, а дошло в 10:05; корректные оконные агрегаты считают по event-time с watermark, иначе поздние события теряются или падают не в то окно. И помни: «реалтайм» стрим дороже в эксплуатации (состояние, exactly-once) — бери его только когда свежесть реально нужна.",
 "di-oltp-vs-olap": "Частая ошибка — лить тяжёлую аналитику (`GROUP BY` по всей таблице) прямо в OLTP-базу продакшена: лочит, раздувает буферы, бьёт по латенси транзакций. Аналитику выноси в OLAP/реплику/warehouse через CDC или ETL. Обратное тоже верно: колоночную БД нельзя гонять как OLTP — `UPDATE` одной строки в columnar дико дорог. Правило: OLTP пишет, OLAP читает агрегаты; между ними — пайплайн, а не один инстанс на всё.",
 "de-sysdesign-framework": "Две главные ошибки на собесе: (1) прыгнуть в технологии до требований — «возьмём Kafka и Cassandra» до того, как ясен масштаб; (2) не озвучивать tradeoff'ы — сениор всегда говорит «выбрал X, минус в Y, потому что для нас важнее Z». Молчаливый «идеальный» дизайн читается как junior. Думай вслух, веди диалог с интервьюером и сам называй слабые места своего решения раньше, чем их найдёт он.",
 "jc-pass-by-value": "⚠️ Реальная ловушка: метод, принимающий `List`/`Map`/массив и делающий `param.clear()` или `param.add()`, молча мутирует коллекцию вызывающего — частый источник багов в legacy-коде (особенно когда коллекцию шарят между потоками или кладут в кэш). Защита: либо передавать `List.copyOf(...)`/оборонительную копию, либо принимать неизменяемую коллекцию. И наоборот: если думаешь, что `param = Collections.emptyList()` внутри метода «очистит» список снаружи — нет, это no-op для вызывающего.",
 "jc-mutable-key": "⚠️ Самая коварная форма — даже HashSet.remove(самогоОбъекта) НЕ удалит мутированный элемент: remove ищет по новому хешу в другом бакете и не находит. Элемент остаётся в множестве навсегда (видно по size()), но недостижим — это реальная утечка памяти в долгоживущих коллекциях. Особенно опасно с JPA-сущностями в Set: equals/hashCode на mutable-полях типа id, который проставляется БД после persist, ломает Set уже после flush.",
 "jc-chm-internals": "⚠️ Внутри `computeIfAbsent`/`compute`/`merge` нельзя модифицировать тот же самый `ConcurrentHashMap` — лямбда выполняется под `synchronized` на головном Node бакета. В Java 8 рекурсивный `computeIfAbsent` по ключу в том же бакете давал зависший CPU/дедлок без исключения (известный баг JDK-8071667); с Java 9+ прямая рекурсия на тот же ключ кидает `IllegalStateException: Recursive update`, но через другие бакеты можно тихо словить блокировку до сих пор. И помни: атомарность гарантирована только для одной операции — связка `get` потом `put` НЕ атомарна, нужен `putIfAbsent`/`compute`.",
 "jc-iterator-removal": "⚠️ Классическая ловушка: на ArrayList из ровно 2 элементов цикл `for-each` с удалением предпоследнего элемента НЕ кинет CME, а тихо пропустит последний. Причина — хитрый порядок в ArrayList$Itr: hasNext() это просто `cursor != size`, и проверка checkForComodification сидит внутри next(), а не hasNext(). После remove() size=1, cursor=1 → hasNext() даёт false, цикл выходит, next() с проверкой modCount даже не вызывается. То есть fail-fast «срабатывает» нестабильно и зависит от позиции элемента — нельзя считать, что любое нарушение будет поймано.",
 "gap-co-sync-vs-reentrantlock": "⚠️ `ReentrantReadWriteLock` НЕ поддерживает upgrade с readLock на writeLock — попытка взять writeLock, держа readLock, ведёт к мгновенному deadlock (поток ждёт сам себя). Downgrade (write → read) разрешён. Плюс на write-heavy нагрузке RWLock часто медленнее обычного ReentrantLock из-за сложного учёта состояния, а писатели могут голодать под потоком читателей (в нечестном режиме). Для оптимистичного чтения вместо него берут StampedLock — но он НЕ реентрантный, и это ловушка номер два.",
 "gap-co-interruption-cancellation": "⚠️ Самая частая ошибка: `catch (InterruptedException e) { log.error(e); }` без восстановления флага. После выброса исключения флаг УЖЕ СБРОШЕН, и если ты его не вернёшь через `Thread.currentThread().interrupt()`, то вышестоящий код в `while(!Thread.currentThread().isInterrupted())` крутится вечно, а `ExecutorService.shutdownNow()` не сможет остановить воркеров. Никогда не проглатывай InterruptedException — либо восстанови флаг, либо проброси исключение.",
 "gap-co-safe-publication-final": "⚠️ `final` НЕ делает поле «навсегда видимым во всех сценариях» — гарантия привязана к завершению конструктора и к тому, что `this` не утёк наружу раньше времени. Если в конструкторе вы сделали `EventBus.register(this)`, `executor.submit(this)` или присвоили `this` статическому полю до выхода из конструктора — freeze ещё не произошёл, и другой поток может прочитать ваши final-поля как 0/null. Также `final`-ссылка на изменяемый объект (например `final List`, который потом мутируется) даёт безопасную публикацию только начального состояния списка, но НЕ его последующих изменений — для них нужна отдельная синхронизация.",
 "gap-co-wait-notify-spurious": "⚠️ Замена `notifyAll()` на `notify()` «для оптимизации» — классический источник зависших систем: при двух разных условиях на одном мониторе notify может разбудить «не тот» поток, тот проверит своё условие, уснёт обратно — и сигнал безвозвратно потерян (lost wakeup), остальные висят навсегда. Баг невоспроизводим под нагрузкой dev-стенда и стреляет только в проде. Если очень нужен notify() — выноси каждое условие на отдельный объект-монитор или используй отдельные Condition на одном ReentrantLock.",
 "gap-jvm-gc-roots": "⚠️ `static`-поле — это GC root, и про это постоянно забывают. Положив объект в `static Map`/`static List` (кэш, реестр листенеров, ThreadLocal без remove), вы делаете его вечно достижимым от корня — он НЕ соберётся, даже если на него больше никто не ссылается. Это классическая «утечка памяти в managed-языке»: GC работает идеально, объект просто формально жив. Лечится `WeakHashMap`, явным удалением или `WeakReference`; именно так протекают перезагружаемые класслоадеры в app-серверах (static ссылка из «вечного» класса держит весь старый ClassLoader и все его классы).",
 "gap-jvm-write-barrier-cardtable": "⚠️ Card marking barrier выполняется на КАЖДУЮ запись ссылки, а не только old→young — JIT не знает поколение цели в момент записи, так что помечает безусловно (unconditional barrier в Parallel GC). Это значит, что даже запись ссылки внутри young в young всё равно дёргает barrier и грязнит карту. Отсюда два следствия для сеньора: (1) аллокационно-тяжёлый код платит скрытый налог на каждую запись ссылочного поля; (2) при профилировании long young-пауз смотрите не только на размер young, но и на объём грязных карт — write-heavy мутации долгоживущих коллекций (большой кэш, который постоянно перезаписывают) раздувают scan-фазу minor GC, хотя сам young маленький.",
 "gap-jvm-object-header-coops": "⚠️ Поднимая heap с 31 ГБ до, скажем, 36 ГБ, легко получить МЕНЬШЕ полезной памяти: распухание ссылок съедает прирост, и приложение может начать чаще падать в GC, чем при 31 ГБ. Практическое правило — либо держать `-Xmx` ниже ~32 ГБ (порог зависит от alignment и версии JVM, иногда ~30–31 ГБ), либо прыгать сразу на 40+ ГБ, чтобы перекрыть провал. `-XX:ObjectAlignmentInBytes=16` поднимает порог до ~64 ГБ ценой большего паддинга.",
 "gap-jvm-classloader-leak": "⚠️ ThreadLocal на потоках из пула — самая частая и коварная ловушка: поток **переиспользуется** между запросами и редеплоями, поэтому `set()` без `remove()` в `finally` оставляет значение жить вечно. Даже если ваш `ThreadLocal`-ключ — статическое поле в библиотеке вне webapp, value-объект класса из webapp удержит весь загрузчик. И WeakReference на ключе не спасает — утекает именно value, а не key. После каждого redeploy в Metaspace копится ещё один «мёртвый» WebappClassLoader со всеми классами.",
 "gap-jvm-invokedynamic-lambda": "⚠️ Method references на instance-метод по факту захватывают ресивер: `list::add` тащит `list`, поэтому это **capturing** и аллоцирует объект на каждом проходе indy-сайта — люди ошибочно считают method reference «бесплатной» и суют её в горячий цикл. Второй частый сюрприз: `LambdaMetafactory` генерирует класс лениво при **первом** исполнении сайта, из-за чего «холодная» первая лямбда платит за бутстрап (спиннинг hidden class) — это бьёт по latency на старте/прогреве и видно в бенчмарках первого запроса.",
 "jc-optional-misuse": "⚠️ `orElse(value)` вычисляет свой аргумент жадно — ВСЕГДА, даже если Optional непустой. Поэтому `optionalUser.orElse(repository.createDefault())` ударит в БД на каждом вызове, включая случай, когда пользователь нашёлся. Для дорогого или с побочными эффектами фоллбэка всегда используй ленивый `orElseGet(() -> repository.createDefault())`. Это классический скрытый источник лишних запросов и багов в продакшене.",
 "jc-optional-orelse": "⚠️ Самая болезненная ловушка — не «лишний расчёт», а скрытый side-effect: `repo.findById(id).orElse(repo.save(newDefault()))` будет писать дефолт в БД на КАЖДЫЙ вызов, даже когда запись уже есть (eager-аргумент отрабатывает всегда). Сениор обязан рефлекторно ставить `orElseGet(() -> repo.save(...))` для всего, что аллоцирует, ходит в БД/сеть или имеет побочный эффект — иначе получите дубли, лишние INSERT'ы и проседание латентности под нагрузкой.",
 "gap-serial-version-uid": "⚠️ Самая частая ловушка: НЕ объявить serialVersionUID вообще. Тогда его генерирует компилятор по сигнатуре класса, и любая «безобидная» правка (новый private-метод, лямбда, смена версии javac) меняет хэш → старые объекты в Redis/Kafka/сессии/БД перестают десериализоваться с InvalidClassException в проде. И обратное: НЕ меняй UID руками, если просто добавил поле — иначе ты сам ломаешь обратную совместимость со всеми ранее сохранёнными данными.",
 "gap-serial-deser-security": "⚠️ Главная ловушка: люди ставят guard ВНУТРИ своего кастомного `readObject()` или валидируют объект ПОСЛЕ десериализации — это бесполезно, потому что gadget chain отрабатывает прямо в процессе восстановления графа, до возврата из `readObject()` верхнего объекта. Единственный надёжный барьер — `ObjectInputFilter` (JEP 290, Java 9+, бэкпортирован в 8u121) с allowlist по классам/глубине/размеру, выставленный ДО чтения. И помни: фильтр — это про снижение риска; правильный senior-ответ — вообще не принимать нативную сериализацию из недоверенного источника, заменив её на JSON/protobuf с явной схемой.",
 "gap-exc-interrupted": "⚠️ Реальная ловушка: `catch (InterruptedException e) { throw new RuntimeException(e); }` — частый «компромисс», но он часто хуже проглатывания. Флаг прерывания при этом НЕ восстанавливается, а RuntimeException всплывает наверх и может, например, уронить пул потоков или привести к лишним ретраям там, где надо было просто тихо остановиться. Правильно: сначала `Thread.currentThread().interrupt();`, и только потом, если действительно нужно прервать выполнение, пробрасывать своё исключение.",
 "sp-tx-rollback-only": "⚠️ Главная ловушка: люди ставят `REQUIRES_NEW` на внутренний метод и удивляются, что флаг rollback-only всё равно «прилип» — потому что метод вызывается через `this.inner()` внутри того же бина, и AOP-прокси НЕ перехватывает self-invocation, новая транзакция не создаётся. Аннотация работает только при вызове через прокси (из другого бина или self-injection). Вторая ловушка: `noRollbackFor` лечит, только если *ты* контролируешь аннотацию метода, помечающего rollback-only — а checked-исключения по умолчанию вообще НЕ вызывают rollback (откат только на RuntimeException и Error), что отдельно сбивает с толку.",
 "sp-aspect-order": "⚠️ Самая частая боль: `@Retryable` ВНУТРИ `@Transactional` (ретрай ближе к методу). После первой неудачной попытки текущая транзакция помечается `rollback-only`, и все последующие повторы выполняются в той же мёртвой транзакции — в итоге `UnexpectedRollbackException` на commit, хотя «ретрай прошёл успешно». Если нужен реальный ретрай с откатом БД, ставьте `@Retryable` СНАРУЖИ, а внутри — отдельный bean-метод с `@Transactional(propagation = REQUIRES_NEW)`; тогда каждая попытка получает свежую транзакцию. И помните: self-invocation внутри того же бина обходит прокси — аннотации просто не сработают.",
 "sp-config-props": "⚠️ Для вложенного объекта внутри @ConfigurationProperties валидация JSR-380 НЕ каскадируется автоматически: без @Valid на поле вложенного типа аннотации (@NotBlank и т.п.) внутри него игнорируются — конфиг с битым вложенным блоком молча пройдёт старт. И второй частый капкан: если на classpath нет Hibernate Validator (забыли spring-boot-starter-validation), @Validated и все JSR-380 аннотации просто не срабатывают — без единого предупреждения.",
 "h-l1-persistence-context": "⚠️ L1-кэш не «отдаёт свежие данные из БД». Если внутри транзакции кто-то изменил строку в обход вашего EntityManager (другой коннект, нативный UPDATE, триггер), то повторный `find()`/JPQL по этому id вернёт СТАРЫЙ managed-объект из контекста — Hibernate не перечитает колонки. Чтобы получить актуальное состояние, нужно `em.refresh(entity)` (или `em.clear()`/`detach()`). Это регулярно стреляет в долгих транзакциях и в тестах, где данные правят напрямую в БД.",
 "h-l2-cache-query-cache": "⚠️ Самая частая ловушка: L2 кэширует сущность, но НЕ её коллекции. Кэширование `@OneToMany` требует отдельной аннотации `@Cache` на самой коллекции — иначе при hit по сущности коллекция всё равно грузится из БД. И при этом collection cache хранит только id связанных сущностей: чтобы коллекция реально читалась из кэша, дочерняя сущность тоже должна быть `@Cacheable` + `@Cache`. Забыл одну из трёх частей — и «закэшированный» агрегат всё равно бьёт в БД, а ты сидишь и не понимаешь, почему SQL-запросы не исчезли.",
 "h-entity-equals-hashcode": "⚠️ Lombok `@Data` / `@EqualsAndHashCode` на JPA-сущности — типичная мина. `@Data` генерирует hashCode по ВСЕМ полям, включая lazy `@OneToMany`-коллекции: обращение к ним инициирует подгрузку (или `LazyInitializationException` вне сессии), а сам hashCode становится изменяемым и рекурсивным (entity ↔ коллекция). Никогда не вешай `@Data`/дефолтный `@EqualsAndHashCode` на entity — только явный бизнес-ключ или паттерн «id-based equals + константный hashCode».",
 "g-db-normalization-forms": "⚠️ Нормализация — это НЕ всегда правильный финал. В OLTP-системах целятся в 3NF/BCNF, но в аналитике/отчётах и под высокой нагрузкой на чтение сознательно **денормализуют** (звезда/снежинка, дублирование `city_region` в строку заказа), чтобы убрать дорогие JOIN-ы. Типичная ловушка джуна — «всё всегда в 3NF»; senior понимает, что нормализация оптимизирует целостность и запись, а денормализация — скорость чтения, и выбирает осознанно под нагрузку. Ещё одна засада: 3NF не равно BCNF — на собеседовании любят спросить про перекрывающиеся составные кандидат-ключи, где схема в 3NF, но НЕ в BCNF.",
 "g-db-denormalization": "⚠️ Самая частая ловушка — дублировать данные, но забыть про путь обновления: добавили в `orders` колонку `customer_name` для скорости, а при смене имени клиента в `customers` старые заказы остаются со старым именем, и никто этого не замечает месяцами. Если решили денормализовать — сразу пишите, КТО и КАК синхронизирует копию (триггер, CDC, джоба), и закладывайте сверку/recon. Отдельная мина — `REFRESH MATERIALIZED VIEW` без `CONCURRENTLY` берёт `ACCESS EXCLUSIVE` lock и блокирует чтения вьюхи на время пересчёта.",
 "g-db-clustered-index": "⚠️ В InnoDB «толстый» или случайный PK (UUIDv4) — двойная боль: копируется в каждый вторичный индекс и вызывает page split'ы. В Postgres этого нет, но PK не даёт бесплатного упорядоченного доступа — за range-локальность платишь руками (CLUSTER/BRIN).",
 "g-db-ranking-functions": "⚠️ ROW_NUMBER() без полностью детерминированного ORDER BY (с уникальным tie-breaker вроде `id`) возвращает НЕДЕТЕРМИНИРОВАННЫЙ результат: при ничьей по `amount` движок может в разных запусках поставить «1» разным строкам. На проде это даёт «прыгающий топ-1» и невоспроизводимую дедупликацию — всегда добавляйте уникальную колонку (PK) в конец ORDER BY.",
 "g-db-gap-next-key-locks": "⚠️ Gap-локи берутся ТОЛЬКО когда условие идёт по индексу. Если `WHERE non_indexed_col = 5` не покрыт индексом, InnoDB сканирует и лочит next-key'ами фактически весь диапазон строк (вплоть до всей таблицы), а не одну «логическую» строку — это убивает конкурентность и плодит deadlock'и. Также gap-локи НЕ берутся для запросов с уникальным индексом и точным равенством (`WHERE pk = 5`) — там достаточно record lock. Многие думают, что лочится «строка по условию», а на деле лочится промежуток индекса.",
 "de-dynamic-dispatch": "⚠️ Классическая боль с `null`: при `p(null)` компилятор выбирает наиболее специфичную перегрузку (p(String) специфичнее p(Object)), но если есть две несвязанные перегрузки одного уровня — p(String) и p(Integer) — будет ошибка компиляции «reference to p is ambiguous». А `equals(MyType)` вместо `equals(Object)` — тихий баг: компилируется, но коллекции (HashMap/HashSet) зовут `equals(Object)` через override-контракт, и твоя перегрузка просто не вызывается, объекты не находятся в мапе.",
 "de-chain-of-responsibility": "⚠️ В Servlet/Spring `Filter` забыть вызвать `chain.doFilter(req, res)` — значит молча оборвать цепочку: запрос НЕ дойдёт до контроллера, последующие фильтры и сам DispatcherServlet не выполнятся, а клиент получит пустой 200 без тела и без явной ошибки. Симметрично опасно вызвать `doFilter` дважды или продолжить писать в response после делегирования — это `IllegalStateException`/повреждённый ответ. И помни: порядок фильтров (`@Order`, `FilterRegistrationBean.setOrder`) — часть контракта; CORS/auth-фильтр, стоящий не на своём месте, ломает безопасность.",
 "de-service-locator": "⚠️ Главная ловушка: в Spring/Quarkus думают «у нас же DI-контейнер, значит Service Locator у нас нет». А потом в коде встречается `applicationContext.getBean(X.class)`, `CDI.current().select(X.class).get()` или поле-зависимость через сервис-реестр — это полноценный Service Locator внутри DI-фреймворка со всеми его минусами. На код-ревью красный флаг — это любой ручной `getBean`/`CDI.current()` в бизнес-классе (не в фабрике/composition root): он прячет зависимость и делает класс нетестируемым без поднятого контекста.",
 "de-tell-dont-ask": "⚠️ Догматичное Tell-Don't-Ask легко скатывается в God Object.",
 "gap-ds-kafka-transactional-producer": "⚠️ transactional.id ДОЛЖЕН быть стабильным и уникальным на каждую логическую задачу/партицию входа — нельзя генерировать его рандомно (UUID на старте) и нельзя шарить один на несколько параллельных инстансов. Рандомный id убивает fencing: после рестарта координатор не свяжет нового продьюсера со старым, незавершённая транзакция предшественника не абортится, и `read_committed`-консьюмеры зависнут на ней (LSO не двигается), пока не истечёт transaction.timeout.ms. А общий id на N инстансов приведёт к тому, что они будут постоянно фенсить друг друга ProducerFencedException. В Kafka Streams это решается автоматически (id = applicationId + taskId), а в ручном consume-process-produce маппинг id→partition надо строить самому.",
 "gap-ds-auto-offset-reset": "⚠️ offsets.retention != retention топика. Закоммиченный офсет живёт в __consumer_offsets ограниченное время (7 дней, исторически 24 часа на Kafka до 2.0).",
 "gap-ds-kafka-streams-ktable": "⚠️ **Тихая потеря/дубли при отключённом EOS.** По умолчанию (`processing.guarantee=at_least_least_once`, точнее `at_least_once`) state store, offset и output-топик коммитятся НЕ атомарно: упал между записью в store и коммитом offset — после рестарта повторно обработаешь те же события и агрегат раздуется (double-counting). Включай `processing.guarantee=exactly_once_v2` для атомарной consume-process-produce транзакции. Вторая ловушка: RocksDB-state хранится на ЛОКАЛЬНОМ диске пода — в Kubernetes без PersistentVolume каждый рестарт пода стирает state.dir, и весь store при старте полностью реплеится из changelog-топика. На больших store это минуты простоя на каждом рестарте/ребалансе; лечится StatefulSet + PVC и/или standby-репликами.",
 "gap-ds-clock-skew-ordering": "⚠️ Классический прод-инцидент: измерение длительности/таймаута через currentTimeMillis(). NTP делает step назад (или прыжок при leap second / переводе часов), и elapsed = end − start выходит отрицательным или гигантским — таймаут срабатывает мгновенно либо «зависает» навечно, кэш с TTL внезапно протухает весь разом. Любой код вида `long start = System.currentTimeMillis(); ... ; if (System.currentTimeMillis() - start > timeout)` — это баг; для длительностей всегда System.nanoTime(). И отдельная ловушка: nanoTime() монотонен, но его абсолютное значение бессмысленно и несравнимо между JVM/узлами — им нельзя обмениваться по сети.",
 "gap-ds-group-coordinator-offsets": "⚠️ Самый частый прод-сюрприз: офсеты можно «потерять» не из-за брокера, а из-за `offsets.retention.minutes`. Если группа простаивает дольше retention (по умолчанию 7 дней) и в этот момент нет активных консьюмеров, её закоммиченные офсеты в `__consumer_offsets` удаляются компакцией → при следующем старте группа берёт `auto.offset.reset` (часто `latest`) и молча проскакивает накопившиеся сообщения либо (при `earliest`) перечитывает всё заново. Сезонные/редко работающие консьюмеры обязаны мониторить это и/или увеличивать retention.",
 "g-te-classicist-mockist": "⚠️ Главная ловушка — мокать то, что тебе не принадлежит: `when(externalSdkClient.call()).thenReturn(...)`. Твой мок описывает контракт чужого API так, как ты его ПОНЯЛ, а не как он реально работает. Когда вендор поменяет поведение (формат ответа, новый exception, retry) — твои тесты остаются зелёными, а прод падает. Правило: мокай только свои порты/адаптеры (то, что владеешь), а интеграцию с чужим SDK покрывай contract/integration-тестами (Pact, WireMock, Testcontainers). Второй симптом over-mocking — `MockitoExtension` со `STRICT_STUBS` начинает сыпать `UnnecessaryStubbingException` на каждый рефакторинг.",
 "g-te-fake-vs-stub": "⚠️ В Mockito `mock()` и `spy()` — это техническая реализация, НЕ роль из таксономии Мезароша. `Mockito.mock()` с `when().thenReturn()` без `verify()` — это на самом деле **stub**, а не mock (verification поведения нет). А `Mockito.spy()` оборачивает реальный объект и по умолчанию зовёт настоящие методы — легко словить реальный side-effect (поход в БД, отправку письма), думая, что объект «заглушён». И классический капкан: `when(spy.foo()).thenReturn(x)` на spy РЕАЛЬНО вызовет `foo()` — для spy надо писать `doReturn(x).when(spy).foo()`, иначе настоящий метод отработает на этапе стабинга.",
 "g-te-mockstatic-smell": "⚠️ `MockedStatic` живёт только в потоке, где создан, и thread-local по умолчанию: если код под тестом делает статический вызов из другого треда (executor, `@Async`, parallel stream), мок там НЕ сработает — увидишь реальный метод. И если забыть try-with-resources/close(), стаб статики утекает в следующие тесты того же потока и даёт «летающие» падения, которые невозможно воспроизвести по одному тесту.",
 "g-te-doreturn-void": "⚠️ Потеря compile-time проверки типов: `doReturn(\"text\").when(mock).getCount()` где `getCount()` возвращает `int` — компилятор молчит (аргумент `Object`), но в момент стаба прилетит `WrongTypeOfReturnValue`/`ClassCastException`. С `when(mock.getCount()).thenReturn(\"text\")` ошибка ловится компилятором. Поэтому do* применяют ТОЛЬКО когда без него нельзя (void/spy), а не как стиль по умолчанию.",
 "g-te-mockbean-context": "⚠️ Классическая ловушка: разработчики думают, что @MockBean переиспользуется, если «тип тот же», но кэш чувствителен к ИМЕНИ бина и к qualifier'ам, и главное — добавление мока ТОЛЬКО в один класс ломает шеринг контекста для всей группы похожих тестов. В Spring Boot 3.4 @MockBean объявлен deprecated в пользу core-аннотации @MockitoBean из spring-test — при миграции это другой пакет (org.springframework.test.context.bean.override.mockito), и семантика кэша та же, проблему миграция НЕ решает.",
 "g-web-session-vs-jwt-revocation": "⚠️ Не клади JWT в localStorage — он доступен любому JS, и одна XSS = кража токена, который ты не можешь отозвать до exp. Храни в HttpOnly+Secure+SameSite cookie (тогда нужен CSRF-щит). И не используй `alg:none` / не доверяй `alg` из заголовка токена — классическая атака подмены алгоритма: жёстко фиксируй ожидаемый алгоритм (например RS256) на стороне валидатора.",
 "g-web-refresh-token-rotation": "⚠️ Если хранить refresh-токен в `localStorage` (а не в HttpOnly Secure cookie), любой XSS моментально его читает — и rotation тут НЕ спасает: вор просто сам прокручивает цепочку быстрее жертвы, а reuse detection в худшем случае выкинет легитимного пользователя, оставив сессию вору. Rotation защищает от УЖЕ УКРАДЕННОГО токена постфактум, но не заменяет защиту от кражи (HttpOnly, CSP, sender-constrained токены DPoP/mTLS из RFC 9700).",
 "g-web-put-vs-patch": "⚠️ Классическая ловушка прода: PUT с частичным телом молча затирает поля. Клиент шлёт `PUT /user/42` с `{\"name\":\"Ivan\"}`, забыв про `email` — по строгой семантике PUT это значит «сделай весь ресурс таким», и сервер обязан обнулить `email`. Многие реализуют PUT как merge и думают, что делают PUT, а на деле — PATCH; это ломает контракт и сбивает интеграторов. Если нужна частичная правка — это PATCH, а не «удобный» PUT.",
 "g-web-tcp-handshake-lifecycle": "⚠️ HTTP/2 НЕ убирает head-of-line blocking — он лишь переносит его с уровня HTTP на уровень TCP. Мультиплексирование стримов в одном TCP-соединении означает, что потеря одного TCP-сегмента стопорит ВСЕ стримы сразу (на потерянных сетях HTTP/2 может быть медленнее, чем HTTP/1.1 с пулом соединений). Реально проблему снимает только HTTP/3 поверх QUIC. Второй частый просчёт: ставить очень большой keep-alive timeout на сервере без учёта лимита файловых дескрипторов/потоков — idle-соединения съедают ресурсы и приводят к отказам под нагрузкой.",
 "g-web-token-storage-cookie-vs-header": "⚠️ SameSite=Lax НЕ блокирует CSRF на top-level GET-навигации (клик по ссылке, form GET) и не защищает, если поддомены не изолированы — `Domain=.example.com` cookie уйдёт на evil.example.com при стороннем поддомене. И помни: localStorage уязвим не только к XSS прямого чтения — любая сторонняя JS-библиотека (supply-chain) в вашем бандле молча читает токен; httpOnly-cookie от этого защищает, а localStorage — принципиально нет.",
 "jc-eqeq": "Ловушка: == для Integer иногда «работает» из-за IntegerCache — кэшируются значения -128..127, поэтому Integer.valueOf(100)==Integer.valueOf(100) даёт true, а с 200 уже false. То же с автобоксингом в коллекциях; никогда не полагайся на == для обёрток — только equals или примитивный int.",
 "jc-checked": "Ловушка: в лямбдах и Stream API нельзя бросить checked-исключение — функциональные интерфейсы (Function, Supplier) его не объявляют, и компилятор заставит ловить прямо внутри лямбды или оборачивать в RuntimeException. Это одна из реальных причин, почему чисто функциональный код вытесняет checked-исключения, а не «мода».",
 "jvm-stackheap": "Ловушка: «объекты всегда в куче» — не абсолют. JIT через Escape Analysis может разложить объект, не убегающий из метода, на скалярные поля прямо в стеке/регистрах (scalar replacement), и тогда new вообще не выделит память в куче. Поэтому микробенчмарки с локальными объектами врут, если не отключить EA или не дать объекту «убежать».",
 "jvm-leak": "Ловушка: ThreadLocal в пуле потоков течёт даже при WeakReference на ключ — слабая только ссылка на сам ThreadLocal-объект, а значение держится сильной ссылкой в ThreadLocalMap живого потока пула и не очищается, пока поток жив. Всегда вызывай remove() в finally, а не надейся на «слабость» ThreadLocal.",
 "co-race": "Ловушка: даже одиночное чтение/запись без гонки на запись может быть «сломано» из-за видимости — без volatile/synchronized один поток может вечно видеть устаревшее значение поля (JIT кэширует его в регистре), и цикл while(!flag) не завершится никогда. Это не race condition в классике, а проблема memory visibility / happens-before, и lock её тоже решает.",
 "co-sva": "volatile НЕ работает для long/double-операций вида счётчика и не спасает массивы: `volatile int[] a` делает volatile саму ссылку, а не элементы — запись `a[i]=x` другим потокам не видна. Для отдельных элементов нужен AtomicIntegerArray или VarHandle, а для составного `count++` даже на volatile-поле нужен Atomic/synchronized, т.к. инкремент не атомарен.",
 "co-pool": "Дефолтные Executors.newFixedThreadPool/newSingleThreadExecutor используют LinkedBlockingQueue без границ — задачи копятся до OOM, а maximumPoolSize при unbounded-очереди вообще не достигается (новые потоки сверх core не создаются). Создавай ThreadPoolExecutor вручную с bounded-очередью и осознанной RejectedExecutionHandler (например CallerRunsPolicy для backpressure).",
 "co-deadlock": "В Java 21+ виртуальные потоки прячут deadlock иначе: при pinning внутри synchronized (до JDK 24 / JEP 491) виртуальный поток не отцепляется от carrier и может застопорить весь ForkJoinPool — это не классический lock-cycle, и `jstack` не напишет «Found one Java-level deadlock». Поэтому для виртуальных потоков предпочитают ReentrantLock вместо synchronized.",
 "sp-bpp": "BeanPostProcessor сам инстанцируется РАНЬШЕ обычных бинов, поэтому если в BPP заинжектить обычный бин (особенно @Autowired), тот может создаться слишком рано — до того как другие BPP успеют его обработать, и на него не навесятся @Transactional/AOP-прокси. Spring как раз логит «is not eligible for getting processed by all BeanPostProcessors»; держи зависимости BPP минимальными или ленивыми.",
 "sp-self": "Self-injection как лекарство ломается при spring.main.allow-circular-references=false (дефолт с Spring Boot 2.6) — контейнер упадёт с циклической зависимостью; нужен @Lazy на self-поле. И помни про @Transactional-нюанс: при self-invocation даже корректный внешний вызов не откатит транзакцию по checked-исключению, если не указан rollbackFor — по умолчанию rollback только на RuntimeException/Error.",
 "sp-nplus1": "JOIN FETCH лечит N+1, но молча ломает пагинацию: при `JOIN FETCH` коллекции с `setMaxResults`/Pageable Hibernate не может применить LIMIT в SQL (строки размножены join'ом), тащит ВЕСЬ результат в память и режет уже там — в логе появится `HHH000104: firstResult/maxResults specified with collection fetch; applying in memory`. Для пагинации с коллекциями используй @BatchSize или @EntityGraph(fetchgraph) с двухшаговой загрузкой, а не fetch join.",
 "sp-lazyinit": "OSIV (spring.jpa.open-in-view) в Spring Boot включён ПО УМОЛЧАНИЮ и маскирует LazyInitializationException — он держит сессию открытой до конца HTTP-ответа, поэтому проблема не воспроизводится в веб-контроллере, но мгновенно вылезает в @Async, Kafka-листенере или тесте без веб-контекста. На старте Boot пишет WARN про это; отключи `open-in-view: false`, чтобы ловить N+1 и lazy-проблемы сразу, а не на проде.",
 "sp-sba": "Помимо «положи main-класс в корень»: @SpringBootApplication можно настроить, но scanBasePackages/exclude на нём — это атрибуты, проброшенные в @ComponentScan/@EnableAutoConfiguration через @AliasFor, и если ты добавишь СВОЙ явный @ComponentScan на тот же класс, он ПЕРЕОПРЕДЕЛИТ встроенный, а не дополнит — внезапно перестанет работать автосканирование дефолтного пакета. Используй атрибуты самой @SpringBootApplication, а не вторую аннотацию.",
 "sp-autoconfig": "Порядок и расположение условий — главная ловушка: @ConditionalOnBean/@ConditionalOnMissingBean видят только бины, ЗАРЕГИСТРИРОВАННЫЕ К МОМЕНТУ обработки данного автоконфига, поэтому всё зависит от порядка (@AutoConfiguration(before/after=...)), а на @Configuration пользователя эти условия по бинам вообще ненадёжны — компонент-скан пользователя обрабатывается ПОСЛЕ автоконфигов. Также с Boot 2.7+ список лежит в `META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports`, а старый `spring.factories` объявлен deprecated.",
 "sp-filterchain": "С Spring Security 6 / Boot 3 окончательно убрали WebSecurityConfigurerAdapter — теперь надо объявлять бин SecurityFilterChain и authorizeHttpRequests (вместо authorizeRequests). Тонкая ловушка: при нескольких цепочках выбирается ПЕРВАЯ, чей securityMatcher подошёл, поэтому порядок бинов через @Order критичен, а authorizeHttpRequests матчит правила сверху вниз — широкий anyRequest().permitAll() выше конкретных правил молча открывает всё.",
 "sp-jwt": "По умолчанию Spring мапит роли из claim 'scope'/'scp' с префиксом 'SCOPE_', а не из realm_access.roles Keycloak, поэтому hasRole('ADMIN') молча не срабатывает — нужен кастомный JwtAuthenticationConverter/GrantedAuthoritiesConverter, выгребающий realm_access/resource_access и добавляющий префикс 'ROLE_'. Отдельная мина: NimbusJwtDecoder кэширует JWKS, но валидацию aud по умолчанию НЕ делает — добавляй JwtValidators/audience-проверку вручную, иначе токен для другого клиента пройдёт.",
 "db-explain": "Голый EXPLAIN ANALYZE в Postgres не показывает реальное чтение страниц — без BUFFERS не видно, сколько ушло в shared hit/read, а это часто и есть источник тормозов; на параметризованных запросах план из prepared statement (generic plan) может отличаться от того, что покажет EXPLAIN с литералами. Плюс сам ANALYZE добавляет ощутимый оверхед на таймингах из-за gettimeofday на каждом узле — для голого тайминга в PG12+ есть EXPLAIN (ANALYZE, TIMING OFF).",
 "db-eav": "JSONB как замена EAV не бесплатен: до тех пор пока не повесишь GIN-индекс (или выражательный B-tree на конкретный путь), любой фильтр по полю внутри JSONB — это seq scan, а GIN не умеет ускорять диапазоны/сортировку и не даёт honest-статистику планировщику. Ещё ловушка: оператор '@>' ловит GIN-индекс, а '->>' с '=' — нет, поэтому неверно написанный запрос тихо скатывается в полный перебор.",
 "ds-eos": "EOS не включается одной настройкой: помимо enable.idempotence (по умолчанию true с Kafka 3.0) и transactional.id у продюсера, КОНСЬЮМЕР должен стоять в isolation.level=read_committed (по умолчанию read_uncommitted!), иначе он прочитает абортированные/незакоммиченные сообщения и весь EOS рушится. Также transactional.id должен быть СТАБИЛЬНЫМ между рестартами инстанса — случайный UUID при старте ломает zombie-fencing и допускает дубли.",
 "jc-arr-linked": "LinkedList проигрывает даже на «вставке в середину»: чтобы вставить по индексу через list.add(i, x), он сначала ЛИНЕЙНО доходит до узла (O(n) обхода), так что амортизированно ArrayList с memmove обычно быстрее. O(1)-вставка реальна только если у тебя уже есть ListIterator на нужной позиции; вызов remove(Object)/contains в обоих — O(n), а jdbc/stream-обход LinkedList бьёт по кэшу из-за прыжков по куче.",
 "jc-hashtable-chm": "Атомарность ConcurrentHashMap распространяется на отдельные операции, но НЕ на связки вроде `if(!map.containsKey(k)) map.put(k,v)` — между ними другой поток вклинится. Используйте атомарные `putIfAbsent`, `computeIfAbsent`, `merge`. И осторожно: внутри лямбды `compute/computeIfAbsent` нельзя трогать ту же мапу (рекурсивный update того же бакета) — в Java 9+ это бросает IllegalStateException, до этого мог быть тихий дедлок.",
 "jc-hashset": "`HashSet.contains`/`remove` сначала ищут по hashCode-бакету и только потом сравнивают equals — поэтому inconsistent equals/hashCode (equals true, а hashCode разный) даёт «элемент есть, но не находится». А `Collectors.toSet()` НЕ гарантирует тип возвращаемого Set (может быть не HashSet) и его модифицируемость — не полагайтесь на это.",
 "de-srp": "Частый перекос при «лечении» God Class — anemic-разнос: вытащили логику в кучу классов, но состояние осталось в DTO, и связность (cohesion) упала вместо роста. SRP про одну ОСЬ изменения (один actor/stakeholder по Мартину), а не про размер: класс на 1000 строк с единственной причиной для изменения формально SRP не нарушает.",
 "de-ocp": "OCP не бесплатен: точку расширения надо угадать ЗАРАНЕЕ и правильно — абстракция, спроектированная под не ту ось вариативности, потом мешает сильнее, чем switch (придётся менять и интерфейс, и все реализации). Это «преждевременная абстракция»; на практике дешевле сначала продублировать/оставить if, а вынести в Strategy после второго-третьего реального варианта (правило трёх).",
 "de-isp-dip": "В DI-фреймворках DIP легко выродить: интерфейс с единственной реализацией, живущей в том же модуле, инверсии не даёт — ядро по-прежнему компилируется только вместе с деталью. Настоящая инверсия требует, чтобы порт лежал в модуле домена, а адаптер — в отдельном модуле, ЗАВИСЯЩЕМ от домена (как audit-spi vs adapter в эталоне); иначе это «интерфейс ради интерфейса».",
 "de-strategy": "Типичная ловушка `Map<String, Strategy>` в Spring: ключом регистрации становится имя бина, а не доменный ключ — при инъекции `Map<String, Strategy>` Spring подставляет beanName→bean, и ваш `map.get(\"VIP\")` тихо вернёт null. Делайте ключ явным (метод `key()` в интерфейсе + сборка мапы в @Configuration или @PostConstruct), а не полагайтесь на имена бинов.",
 "de-factory": "Статический метод-фабрика (Integer.valueOf, EnumSet.of) сам по себе не Factory Method из GoF — настоящий Factory Method виртуальный и переопределяется подклассом. Путаница ведёт к ошибочным ответам на собеседовании: 'статическую фабрику нельзя переопределить' — она не участвует в полиморфизме и потому не паттерн Factory Method.",
 "inf-redis": "Однопоточность относится только к выполнению команд: одна O(n)-команда (KEYS *, большой SUNION, FLUSHALL по огромной БД) блокирует ВЕСЬ инстанс и валит latency всем клиентам. В проде используйте SCAN вместо KEYS и следите за slowlog; именно 'тяжёлая' команда, а не нагрузка, чаще всего роняет p99.",
 "inf-eviction": "Дефолтная политика maxmemory-policy в Redis — noeviction, а не LRU: при достижении maxmemory записи начинают падать с OOM-ошибкой вместо вытеснения, и 'кэш' внезапно перестаёт принимать новые ключи. Для кэша явно ставьте allkeys-lru/allkeys-lfu, иначе ключи без TTL под volatile-* политиками никогда не вытесняются.",
 "inf-es": "Маппинг и анализатор фиксируются при создании индекса: сменить тип поля или analyzer у существующего поля нельзя — нужен новый индекс и reindex (обычно через alias, чтобы не было простоя). Поэтому 'данные есть, но не ищутся' часто значит, что документы проиндексированы старым analyzer'ом, и переиндексация обязательна, а не просто смена настройки.",
 "inf-docker": "Слой-кэш инвалидируется каскадно: изменение ранней инструкции (например COPY . . до RUN mvn install) пересобирает ВСЕ последующие слои, поэтому копируют сначала pom.xml/package.json, ставят зависимости, и лишь потом COPY исходники. Плюс удаление файла в позднем слое не уменьшает образ — он остаётся в нижележащем слое; чистить нужно в той же RUN-инструкции (или multi-stage build).",
 "jc-stream-reduce": "reduce требует, чтобы аккумулятор был ассоциативным и без состояния, иначе на parallelStream() результат станет недетерминированным; а трёхаргументный reduce(identity, accumulator, combiner) дополнительно требует, чтобы combiner был совместим с accumulator (combiner.apply(u, accumulator.apply(identity, t)) == accumulator.apply(u, t)) — нарушение этого контракта молча даёт неверные суммы только под нагрузкой параллелизма.",
 "jc-optional-chain": "Optional не Serializable, и поле/параметр типа Optional ломает фреймворки (Jackson по умолчанию сериализует его как {\"present\":...} без модуля Jdk8Module, JPA/Hibernate не маппит его на колонку); кроме того orElse(buildDefault()) вычисляет аргумент ВСЕГДА — даже когда значение присутствует — поэтому для дорогого дефолта обязателен orElseGet(() -> ...).",
 "te-hexagon-test": "In-memory фейк порта легко расходится с реальным адаптером по семантике, которую интерфейс не выражает: уникальные индексы, каскады, оптимистичная блокировка (@Version → OptimisticLockException), флаш Hibernate на границе транзакции, чувствительность к регистру/коллации в LIKE — поэтому фейк нужно покрывать тем же контрактным набором тестов, что и Testcontainers-адаптер, иначе зелёные unit-тесты прячут баг, который вылезет только в проде.",
 "web-versioning": "Добавление поля «совместимо» только если клиенты толерантны к неизвестным полям: Jackson с FAIL_ON_UNKNOWN_PROPERTIES=true (или старые потребители на строгой схеме) упадут на новом поле в ответе, а изменение enum (новое значение) сломает клиента, у которого десериализация enum — строгая; настоящие breaking-change прячутся и в семантике (поменяли смысл/единицы поля при том же типе), что не ловится никаким версионированием URI.",
 "alg-bigo": "Big-O игнорирует константы и реальную аппаратную модель, из-за чего «асимптотически худший» алгоритм часто быстрее: линейный проход по ArrayList обгоняет «O(1)» LinkedList из-за cache locality, а HashMap деградирует с O(1) до O(n) при коллизиях (в Java 8+ — до O(log n), бакет превращается в дерево при ≥8 элементах и Comparable-ключах); амортизированная O(1) у ArrayList.add тоже скрывает разовый O(n)-резайз.",
 "alg-structure": "Treeification HashMap (Java 8+) срабатывает только при TREEIFY_THRESHOLD=8 коллизий В ОДНОЙ корзине И при capacity >= MIN_TREEIFY_CAPACITY=64; если корзин меньше 64, вместо превращения в дерево HashMap просто делает resize. Плюс дерево требует Comparable-ключи: для несравнимых объектов оно деградирует к O(n) даже после treeify, так что 'дерево спасает от плохого hashCode' — миф для произвольных ключей.",
 "web-nonrest": "gRPC из браузера напрямую работать не будет: браузер не даёт коду полный контроль над HTTP/2-фреймами (trailers, поток), поэтому нужен прокси gRPC-Web (Envoy grpc_web filter) и кодген на клиенте — обычный fetch к gRPC-сервису не подключится.",
 "web-dns-lb": "Распространённая ловушка: JVM кэширует успешные DNS-резолвы: по умолчанию 30 секунд, а навсегда (ttl=-1) — только при включённом SecurityManager, которого с JDK 24 включить уже нельзя, поэтому даже при коротком TTL у записи приложение продолжит ходить на старый IP после failover — лечится выставлением networkaddress.cache.ttl в java.security или DNS-балансировкой через стабильный VIP.",
 "git-bisect": "git bisect run считает виновным коммит только по exit-кодам скрипта: 0 = good, 1-124/126/127 = bad, а код 125 означает «коммит нетестируемый» (skip). Если твой тест случайно вернёт 127 (команда не найдена) или 128+ — bisect примет это за bad и укажет на неверный коммит; для невоспроизводимых сборок возвращай ровно 125, чтобы коммит пропустился, а не пометился как плохой.",
 "git-flow": "Главная боль git flow на практике — не сами ветки, а долго живущая develop: фичи отрезаются от неё и неделями не вливаются, из-за чего merge release/* в main регулярно даёт конфликты и «дрейф» между develop и main. Именно это, а не «избыточность», заставляет CD-команды переходить на trunk-based с фиче-флагами вместо долгих веток.",
 "devops-cicd": "Классическая ловушка: pipeline зелёный, потому что упавший шаг не уронил сборку — в shell-скрипте каждая команда отдаёт свой exit-код, и без set -e (или set -o pipefail для пайпов) ошибка в середине молча проглатывается. В GitHub Actions `run:` по умолчанию запускается с bash -e, а в GitLab CI — нет, поэтому там же легко получить «успешный» деплой битого артефакта.",
 "devops-protected": "Включить protected branch недостаточно: по умолчанию правила обычно не распространяются на админов/maintainer'ов, и обязательный «зелёный CI» легко обойти merge'ем в обход status check, если он не отмечен как required. В GitHub нужно явно включить 'Do not allow bypassing the above settings' и 'Require branches to be up to date', иначе можно смержить PR с устаревшей и реально красной базой.",
 "devops-soa-msa": "Самый частый провал на собеседовании и в проде — «распределённый монолит»: формально микросервисы со своими репозиториями, но с общей БД или синхронной REST-цепочкой A→B→C, где отказ одного валит все. Признак настоящей независимости — раздельная БД и асинхронные события: если деплой сервиса B требует одновременного деплоя A, это ещё SOA-связность под видом MSA.",
 "devops-linux": "free -h обманчиво показывает мало «free» памяти, потому что Linux отдаёт неиспользуемую RAM под page cache — реально доступную память смотри в колонке `available`, а не `free`, иначе ложно диагностируешь нехватку памяти. А факт OOM-kill ищи не в выводе free (он уже в прошлом), а в `dmesg`/`journalctl -k` по строке 'Out of memory: Killed process'.",
 "te-junit-mockito": "Mockito не умеет мокать `static`/`final` методы и конструкторы старым `mock()`: для статиков нужен `mockito-inline` (по умолчанию с Mockito 5) и `Mockito.mockStatic(...)` в try-with-resources, иначе мок утечёт в другие тесты того же потока. А `verify` после `verifyNoMoreInteractions` на спае часто ловит вызовы реальных методов — спай вызывает реальный код, если стаб не задан через `doReturn().when(spy)`.",
 "jc-marker-iface": "`Serializable` — это не просто пассивная метка: JVM при десериализации НЕ вызывает конструктор сериализуемого класса (создаёт объект через `ObjectInputStream`/`Unsafe`), но ВЫЗЫВАЕТ no-arg конструктор первого несериализуемого предка — если его нет, прилетит `InvalidClassException`. И `Cloneable` без переопределённого `clone()` бесполезен, а дефолтный `Object.clone()` делает поверхностную копию.",
 "jc-abstract-iface": "Ловушка default-методов: если класс реализует два интерфейса с одинаковой сигнатурой default-метода, код НЕ компилируется (диамант) — нужно явно переопределить и вызвать `Interface.super.method()`. Плюс default-методы не видят полей и не могут синхронизироваться по состоянию, поэтому интерфейс с default'ами не заменяет абстрактный класс там, где нужна общая мутабельная база.",
 "jc-annotations": "RUNTIME-аннотации не наследуются дочерними классами по умолчанию — рефлексия их увидит на сабклассе только если сама аннотация помечена мета-аннотацией `@Inherited`, и даже тогда `@Inherited` работает ТОЛЬКО для аннотаций на классах, а не на методах/полях. Поэтому Spring для своих аннотаций использует не `@Inherited`, а собственный `AnnotatedElementUtils`/`findAnnotation`, который обходит и интерфейсы, и мета-аннотации.",
 "jc-map-notcoll": "`entrySet()` возвращает живую вью на ту же Map, и `Map.Entry`, выданный итератором, валиден только в пределах текущей итерации: вызов `entry.setValue()` меняет саму Map, а после `next()` поведение старого Entry не определено. Поэтому хранить ссылки на Entry из обхода нельзя, а попытка структурно изменить Map во время итерации по `entrySet()` бросит `ConcurrentModificationException`.",
 "jc-prim-wrap": "Integer cache по умолчанию кэширует только -128..127, поэтому Integer a=127; a==127 даёт true, а с 128 уже false — но верхнюю границу можно поднять через -XX:AutoBoxCacheMax / -Djava.lang.Integer.IntegerCache.high, из-за чего код, работавший на одной JVM, ломается на другой. Никогда не полагайтесь на == для обёрток.",
 "co-atomic": "AtomicInteger гарантирует атомарность и видимость, но не справедливость и не отсутствие starvation: под высокой контенцией busy-retry CAS на одной ячейке деградирует (cache-line contention), и LongAdder/LongAccumulator с раздельными ячейками часто быстрее для счётчиков. Плюс есть теоретическая ABA-проблема — её решает AtomicStampedReference.",
 "db-pg-storage": "Index-only scan в Postgres всё равно лезет в heap, если страница не помечена all-visible в visibility map — а её обновляет только VACUUM, поэтому на свежезаписанной/часто обновляемой таблице covering-индекс внезапно работает как обычный index scan. Смотрите Heap Fetches в EXPLAIN ANALYZE и не забывайте про autovacuum.",
 "ds-queue-vs-svc": "Очередь даёт развязку, но взамен почти всегда даёт at-least-once, а не exactly-once — брокер передоставит сообщение при таймауте ack или ребалансе, поэтому консьюмер ОБЯЗАН быть идемпотентным (dedup по ключу/таблица обработанных id). Иначе ретраи, ради которых очередь и взяли, превращаются в двойные списания.",
 "ds-consumer-groups": "Каждый ребаланс группы — это stop-the-world: всё потребление встаёт, пока партиции перераспределяются, а долгая обработка в одном poll() превышает max.poll.interval.ms, и брокер выкидывает консьюмера, запуская новый ребаланс (каскад). Лечится cooperative-sticky assignor, static membership (group.instance.id) и уменьшением max.poll.records.",
 "x-java-pecs-wildcards": "Из-за стирания типов wildcard-границу нельзя обойти рефлексией или непроверяемым кастом без последствий: `((List<Number>) extendsList).add(x)` скомпилируется с warning, но взорвётся ClassCastException не на add, а позже — при чтении владельцем реального `List<Integer>`. Ещё тонкость: `List<?>` (unbounded) — это НЕ `List<Object>`, в него тоже нельзя класть ничего кроме null, а `Arrays.asList` возвращает фиксированный размер, так что даже `List<? super T>` от него кинет UnsupportedOperationException на add.",
 "x-sp-bean-lifecycle": "BeanPostProcessor'ы сами создаются раньше обычных бинов и НЕ проходят полную цепочку постпроцессинга — поэтому зависимости, заинжектированные в BPP, часто не проксируются (классический warning «is not eligible for getting processed by all BeanPostProcessors»). Ещё ловушка: проксирование через `...AfterInitialization` ломает инъекцию по конкретному классу при JDK-динамических прокси — поле типа `MyServiceImpl` не зарезолвится, нужен интерфейс или `proxyTargetClass=true` (CGLIB), а CGLIB в свою очередь не умеет проксировать final-классы/методы.",
 "x-sp-qualifier-primary": "Инъекция в `List<Payment>` собирает бины в порядке `@Order`/`Ordered`/`@Priority`, а НЕ в порядке объявления — частый сюрприз, когда стратегии «вдруг» поменяли приоритет. И `@Primary` НЕ помогает для коллекций (туда всё равно попадут все бины), зато молча проигрывает `@Qualifier` даже на самом `@Primary`-бине; а с несколькими `@Primary` одного типа Spring снова падает NoUniqueBeanDefinition — `@Primary` не «сильнее всех», он лишь tie-breaker среди кандидатов.",
 "x-ds-consumer-lag": "Lag измеряется в сообщениях, а не в секундах — поэтому при неравномерном размере записей или skew по ключу одна «горячая» партиция может иметь огромный lag при нулевом суммарном, и средняя метрика это замаскирует; смотри per-partition. Ещё коварство: после ручного сдвига offset'а или включения нового консьюмера с `auto.offset.reset=latest` lag показывает 0, хотя данные пропущены, а не обработаны — нулевой lag не равен «всё обработано».",
 "x-ds-rebalance": "С `enable.auto.commit=true` ребаланс — частый источник дублей и потерь: автокоммит происходит по таймеру внутри poll(), и при отзыве партиции уже обработанные, но не закоммиченные записи переедут к другому консьюмеру (at-least-once дубли), либо закоммиченные-но-не-обработанные пропадут. CooperativeStickyAssignor требует rolling-перезапуска ВСЕЙ группы (нельзя смешивать eager и cooperative assignor'ы одновременно), а static membership без аккуратного `session.timeout.ms` наоборот замораживает партиции упавшего пода до истечения таймаута — обработка стоит дольше, чем при обычном ребалансе.",
 "x-ds-saga": "Компенсации сами могут падать (сеть/сервис лежит), поэтому их нужно делать идемпотентными и retry-able с persistent-логом шагов, иначе сага зависнет в полу-откате; в orchestration-стиле это решает движок (Zeebe/Camunda) с durable-состоянием инстанса, но в choreography придётся строить retry/dead-letter руками. Отдельная ловушка — недостижимая компенсация: между шагом и его откатом другой сервис уже прочитал промежуточное состояние и принял решение (нет изоляции), поэтому компенсация должна быть семантически корректной (возврат денег + уведомление), а не «откатить как будто не было».",
 "x-ds-idempotency-key": "Классическая дыра — записывать idempotency-ключ и сохранять результат в РАЗНЫХ транзакциях с бизнес-операцией: если сервис упал между бизнес-коммитом и записью ответа, повтор увидит «ключа нет» и выполнит действие второй раз. Ключ, состояние операции (IN_PROGRESS/DONE) и сам эффект должны коммититься в одной локальной транзакции (или через outbox), а параллельный второй запрос по тому же ключу при статусе IN_PROGRESS обязан вернуть 409/ждать, а не «тихо» пропустить.",
 "x-de-decorator": "Декоратор ломается, когда клиент проверяет конкретный тип или вызывает методы, которых нет в общем интерфейсе: instanceof/каст до обёрнутого класса не пройдёт, а equals/hashCode обёртки теперь не совпадают с исходным объектом (identity-проблема в коллекциях/кэшах). Поэтому JDK-обёртки вроде Collections.synchronizedList или java.io опираются строго на интерфейс, а вытащить «настоящий» объект из-под слоёв штатно нельзя.",
 "x-de-law-of-demeter": "Закон Деметры про вызовы методов, а не про доступ к данным: цепочки навигации в JPA-сущностях (order.getCustomer().getAddress().getCity()) формально его нарушают, но прятать их за методами на агрегате опасно — каждый геттер может триггерить ленивую загрузку и N+1, а сама длинная цепочка по lazy-связи бросит LazyInitializationException вне транзакции. То есть слепое следование DoL в ORM-моделях маскирует производительностные грабли, которые лучше решать join-fetch/проекцией, а не очередным «удобным» методом.",
 "x-inf-es-text-vs-keyword": "С Elasticsearch 7.x строки по умолчанию маппятся как text + автоматический под-филд .keyword с ignore_above:256 — длиннее этого порога значение молча НЕ индексируется в keyword, поэтому точный фильтр/сортировка/агрегация по нему просто теряют такие документы без ошибки. Плюс text-поля не имеют doc_values: сортировка/агрегация по «голому» text потребует включить fielddata (жрёт heap и грозит OOM) — правильный путь именно явный keyword-подфилд, а не fielddata.",
 "x-inf-container-vs-vm": "Контейнер видит ядро и часть ресурсов хоста, и до недавнего времени JVM по умолчанию читала /proc хоста, а не cgroup-лимиты — поэтому на старых билдах (до JDK 8u191/10) Runtime.availableProcessors() и расчёт heap брались по железу узла, и контейнер с лимитом 512MB ловил OOMKill. Даже сейчас стоит проверять, что образ на JDK с поддержкой cgroups v2 (нужен JDK 15+ для корректного чтения v2), иначе пул потоков и heap масштабируются под весь хост, а не под cgroup.",
 "x-te-param-tests": "@MethodSource требует static-метод (или non-static при @TestInstance(PER_CLASS)), и его имя задаётся строкой — рефакторинг переименования метода молча не обновит ссылку, а тест упадёт с JUnitException только в рантайме. Ещё: @ValueSource нельзя использовать с массивами/несколькими параметрами, а @CsvSource по умолчанию трактует пустую строку как \"\", но отсутствие значения — как null только с явным nullValues/emptyValue.",
 "x-alg-amortized-arraylist": "Реальный рост Java ArrayList — не ровно 1.5x, а oldCapacity + (oldCapacity >> 1), и это вычисляется в grow(); первое расширение пустого списка идёт сразу до DEFAULT_CAPACITY=10. Подвох с предзаданной ёмкостью: new ArrayList<>(1000) убирает ресайзы, но add() в начало/середину (add(0, x)) всё равно O(n) из-за System.arraycopy сдвига — capacity спасает только от роста, не от вставок не в хвост.",
 "x-alg-space-complexity": "Глубина рекурсии при которой ловишь StackOverflowError зависит не от n абстрактно, а от размера фрейма и флага -Xss (по умолчанию ~512KB-1MB), то есть это обычно тысячи-десятки тысяч кадров, а не миллионы. Скрытая ловушка: даже без явной рекурсии глубокий поток на Stream/итераторах или цепочка CompletableFuture-колбэков может растить стек, а StackOverflowError — это Error, его нельзя ловить как обычное исключение в проде.",
 "x-alg-avg-vs-worst": "Treeify в O(log n) случается только если ключи Comparable; иначе при коллизиях сравнение идёт по hashCode-«тай-брейку», и при равных хешах несравнимых ключей дерево вырождается ближе к O(n)-обходу. Плюс важный нюанс: порог 8 (TREEIFY_THRESHOLD) срабатывает лишь при capacity ≥ 64 (MIN_TREEIFY_CAPACITY) — иначе HashMap сначала просто ресайзит таблицу, а не строит дерево.",
 "x-git-rebase-i": "--force-with-lease безопасен только если твой локальный remote-tracking ref свежий: если ты делал git fetch (или autofetch в IDE) после чужого пуша, lease «видит» уже обновлённый ref и затрёт чужие коммиты так же, как обычный --force. Надёжнее --force-with-lease=<ref>:<expected-sha> с явным SHA. Ещё ловушка: rebase -i, который что-то меняет (squash/reword), переписывает committer date и теряет оригинальный SHA — подписи GPG и ссылки в трекерах на коммит станут невалидными.",
 "p-ddd-ref-by-id": "Ссылка по ID ломает декларативную ссылочную целостность БД: вместо FK-констрейнта между таблицами агрегатов появляется «голый» UUID-столбец без foreign key (это сознательный выбор DDD — FK между агрегатами не ставят). Поэтому консистентность между агрегатами становится eventual и держится на доменной логике/сагах, а удаление клиента не каскадится автоматически — нужны явные проверки или soft-delete.",
 "p-hex-domain-vs-jpa": "Неочевидная цена раздельных моделей — потеря автоматического dirty checking: JPA сама делает UPDATE по изменённому managed-Entity, а при ручном маппинге domain→entity ты грузишь сущность, копируешь поля и обязан учесть optimistic locking (@Version) руками, иначе перетрёшь @Version и поймаешь StaleObjectStateException или потерянное обновление. Версию нужно протаскивать через domain-модель и обратно в entity при сохранении.",
 "p-hex-api-vs-spi": "Тонкое место — где сидит @Transactional: транзакция принадлежит inbound-стороне (use case, реализующий API), а не outbound-адаптеру, потому что один сценарий = одна транзакция поверх нескольких SPI-вызовов. Если @Transactional повесить на адаптер репозитория, два вызова порта в одном use case окажутся в разных транзакциях, и атомарность сценария рушится.",
 "p-deep-shallow-module": "Контринтуитивное следствие Оустерхаута — геттеры/сеттеры на каждое поле делают модуль мелким: они расширяют интерфейс до размера внутреннего состояния и выставляют наружу детали реализации, что прямо противоречит «узкий интерфейс». Поэтому анемичная модель из одних getX/setX — это набор мелких модулей, и дробление God Class на такие DTO-подобные классы не углубляет, а множит мелкость.",
 "p-info-leakage-temporal": "Частый ложный сигнал: «два класса всегда меняются вместе» НЕ всегда leakage — это может быть здоровая декомпозиция вокруг общего знания, спрятанного за абстракцией (например, encoder/decoder одного формата). Утечка — именно когда оба знают решение НАПРЯМУЮ, без общего владельца; лечится извлечением третьего класса-носителя знания, а не механическим слиянием двух.",
 "p-define-errors-out": "Опасная переоценка приёма: «define errors out of existence» легко скатывается в проглатывание реальных багов — возврат null/пустой коллекции/тихий no-op вместо нарушенного инварианта прячет дефект до момента, когда он всплывёт далеко от причины. Правило Ousterhout: убирать надо ЧАСТОТУ исключительных случаев через дизайн семантики, а не глушить уже наступившую ошибку (это antipattern «exception masking»).",
 "p-domain-vs-jpa-entity": "Подводный камень маппинга: Java record как domain-модель не работает с обратным маппингом графов и identity — record иммутабелен, поэтому циклические ассоциации (Order↔OrderLine) и ленивая дозагрузка в нём невыразимы, а equals по всем полям ломает идентичность сущности (две версии одного Order по бизнес-id должны быть равны). Для агрегатов с identity берут обычный класс с equals по id, record оставляют для value-объектов.",
 "p-architecture-quantum": "Неочевидное: квант определяется не только данными, но и СВЯЗНОСТЬЮ — два сервиса с раздельными БД, но синхронно связанные (один не может ответить без блокирующего вызова другого, общий шаблон availability), тоже образуют один динамический квант. И наоборот, общая read-only реплика (только чтение через неё) кванты не сливает — статическая связанность возникает именно от ПИСАТЕЛЕЙ схемы.",
 "p-legacy-code-no-tests": "Ловушка characterization-тестов: они фиксируют ТЕКУЩЕЕ поведение, включая баги — если legacy возвращает неверный результат, правильный characterization-тест должен пройти именно на неверном значении, иначе ты «чинишь» поведение до того, как покрыл его. Сначала зафиксируй то, что есть (даже кривое), потом отдельным осознанным шагом меняй спецификацию.",
 "p-seam-enabling-point": "Грабли object seam в Java: подменяемость требует, чтобы метод не был private/static/final — иначе шва нет (нельзя переопределить), и придётся вводить его рефакторингом (Extract Interface, обернуть static в инстанс-метод). Именно поэтому static-утилиты и new прямо в теле метода — главные убийцы тестируемости: enabling point отсутствует, мокать без PowerMock/инструментации байткода нечем.",
 "p-characterization-test": "Приём «заведомо падающей ассерции» молча врёт на нестабильных значениях: если result содержит таймстемп, HashMap-порядок, hashCode-зависимый toString() или Locale-зависимый формат, вставленное значение зафиксирует случайный снимок, и тест станет flaky. Перед фиксацией нормализуй такой вывод (фиксированный Clock, TreeMap/сортировка, явный Locale/UTC), иначе characterization-тест будет падать на CI у соседа.",
 "p-sprout-wrap": "Sprout Method соблазняет сделать новый метод private и звать его из легаси — но тогда его не достать тестом напрямую без рефлексии, и весь смысл (тестируемость) теряется. Делай sprout как минимум package-private (или выноси в Sprout Class), иначе ты получил тот же непротестированный код, только в новом методе.",
 "p-lean-on-compiler": "«Lean on the Compiler» бессилен против перегрузок и автобоксинга: смена параметра с int на Integer (или удаление одной перегрузки) не даёт ошибку компиляции, а молча резолвится в другую перегрузку/в boxing, и поведение тихо меняется. Поэтому правило «доверяй только IDE-рефакторингам» особенно важно там, где есть overload-методы и varargs — там компилятор не чек-лист, а ловушка.",
 "p-strangler-cutover": "Самая частая засада Strangler — не сам код, а данные: пока трафик идёт на оба контура, БД пишут обе версии, и delta-poll по modified_date пропускает удаления (DELETE не двигает modified_date) и ловит clock-skew между нодами. Нужен либо CDC/триггеры на удаления, либо tombstone-флаги; иначе откат на старый Postgres вернёт «воскресшие» записи.",
 "p-outbox-relay-race": "Идемпотентный консьюмер не спасает, если дедуп-ключ берётся из payload, а relay дублирует сообщение с другим Kafka-ключом или после ребаланса консьюмера дубли уходят в разные партиции — тогда обработчики на разных партициях не видят дубль друг друга. Дедуп-ключ должен быть бизнес-идентификатором (document_id), и желательно он же = Kafka message key, чтобы дубль гарантированно сел в ту же партицию.",
 "p-api-composition-latency": "Таймаут на отдельный HTTP-вызов не отменяет повисшую задачу: если оборачивать вызовы в CompletableFuture.supplyAsync, таймаут (orTimeout/completeOnTimeout) завершает только Future, но фоновый поток продолжает держать соединение из пула, пока не вернётся сам клиент. Реальный fail-fast даёт только таймаут на уровне HTTP-клиента (request/connect timeout) плюс отдельный bounded-пул под фан-аут, иначе общий ForkJoinPool.commonPool забивается зависшими задачами.",
 "p-api-composition-vs-cqrs": "Переход на CQRS легко превращается в скрытый дуальный-write: сервис кладёт строку в свою БД и шлёт событие на read-model двумя отдельными действиями, и при падении между ними проекция расходится с источником навсегда. Событие, питающее read-model, обязано идти через тот же transactional outbox/CDC, что и запись в источник, а сам consumer проекции должен быть идемпотентен по offset/версии, иначе ребилд после сбоя даст дубли.",
 "p-acl-not-just-mapper": "Частая утечка ACL — не доменные коды legacy CBS, а его исключения и типы: если адаптер пробрасывает наружу SQLException, vendor-specific runtime или даже jakarta-аннотации/Panache-сущность как «доменный» объект, домен снова привязан к источнику, хотя поля красиво смаплены. ACL обязан конвертировать и ошибки тоже — транслировать чужие сбои в доменные исключения порта, иначе catch (SQLException) всплывёт в use-case.",
 "p-kafka-minisr": "min.insync.replicas — это broker/topic-конфиг, а не producer: задать его только в коде продьюсера бесполезно, он не существует на стороне клиента, и без topic-override берётся дефолт брокера (часто 1), сводя acks=all к acks=1. Плюс важна асимметрия: при ISR<min блокируется только запись, а чтение уже закоммиченных сообщений продолжается, поэтому «топик не пишется, но читается» — нормальное, а не противоречивое состояние.",
 "p-kafka-ack-after-dbwrite": "С enable.auto.commit=true (дефолт в KafkaConsumer) порядок «БД потом ack» иллюзорен: poll() периодически коммитит оффсеты по auto.commit.interval.ms в фоне, поэтому оффсет уезжает раньше записи в БД сам по себе. Гарантия write-then-ack работает только при ручном управлении — enable.auto.commit=false и явный commitSync после успешной транзакции БД (в Quarkus/SmallRye — throttled/latest стратегия с явным ack()).",
 "p-kafka-autocommit-loses": "Контринтуитивно: даже с enable.auto.commit=true потеря случается не при падении, а при простом ребалансе — auto.commit фиксирует оффсет внутри poll() ДО возврата нового батча, поэтому если обработка предыдущего батча ещё не закончилась к следующему poll(), оффсет уезжает вперёд. Ручной commitSync() сам по себе не панацея: коммитишь по разделам асинхронно — следи за тем, что коммитишь именно offset+1 последней обработанной записи (Kafka хранит «следующий к чтению», а не «последний прочитанный»).",
 "p-tx-repeatable-read-name-trap": "Подвох SSI: SERIALIZABLE в Postgres не блокирует, а оптимистично отслеживает rw-зависимости и кидает serialization_failure (SQLSTATE 40001) уже на COMMIT — приложение ОБЯЗАНО иметь retry-цикл, иначе ты просто превратил write skew в необработанные исключения в проде. Плюс SSI требует, чтобы ВСЕ участвующие транзакции были SERIALIZABLE: одна READ COMMITTED транзакция в смеси сломает гарантию.",
 "p-db-find-save-race": "Ловушка JPA/Hibernate: @Version защищает только если ты грузишь и сохраняешь сущность через persistence context — массовый JPQL UPDATE (`update Account a set a.balance = ...`) НЕ инкрементит version-колонку автоматически и обходит optimistic lock, незаметно открывая ту же гонку. А голый атомарный `SET balance = balance - 10` спасает от lost update, но под READ COMMITTED всё ещё может прочитать неактуальное значение для бизнес-проверки — атомарность апдейта не равна корректности предусловия, считанного отдельным SELECT.",
 "p-cb-halfopen": "Грабли конкурентности Half-Open: пока пробный запрос «в полёте», все остальные должны мгновенно фейлиться, иначе при таймауте downstream в 30 сек ты за это время пропустишь сотни «проб». В Resilience4j это контролирует permittedNumberOfCallsInHalfOpenState, и важно понимать: переход Open→Half-Open у него ленивый (по следующему вызову после истечения wait-duration), а не по фоновому таймеру — без трафика CB может вечно висеть в Open.",
 "p-edm-notification": "Обратная сторона, о которой забывают: ECST устраняет temporal coupling, но вводит проблему устаревших данных и порядка — консьюмер строит read-model из снимков, и при out-of-order доставке (разные партиции/ретраи) новое событие может перетереться старым. Лечится не «положить данные в событие», а версией/timestamp в payload и upsert-логикой «применять только если версия больше текущей»; плюс растёт размер событий и риск утечки чувствительных полей всем подписчикам.",
 "p-edm-compaction": "Тонкость компакции: она НЕ гарантирует, что новый консьюмер не увидит дублей или промежуточных версий ключа — компактится только «хвост» (segments старше active segment и за пределами min.cleanable.dirty.ratio), поэтому свежие записи в active segment остаются неконсолидированными, и bootstrap-логика обязана быть идемпотентной (last-write-wins по ключу). Tombstone тоже не вечен: его удалят через delete.retention.ms (по умолчанию 24ч), и консьюмер, реплеящий стрим позже, рискует вообще не увидеть факт удаления — «воскрешение» удалённой сущности.",
 "p-stab-slow-vs-fail": "Главная засада таймаутов в Java — большинство «таймаутов» НЕ прерывают зависший поток: HttpURLConnection/Socket дают connectTimeout и readTimeout, но между пакетами read может висеть бесконечно, а JDBC-вызов вообще игнорирует Thread.interrupt() и продолжает держать соединение пула. Нужен отдельный statement/query timeout на драйвере (socketTimeout у PgJDBC, statement_timeout у Postgres) — иначе ваш circuit breaker откроется, но физический поток так и останется заблокированным до ответа сервера.",
 "p-stab-dogpile-jitter": "Неочевидный самострел — «full jitter против equal jitter»: классический exponential backoff с симметричным jitter (delay ± random) всё равно оставляет общий центр у всех ретраев, и стадо лишь слегка размывается. AWS-рекомендация — full jitter: sleep = random(0, cap·2^attempt), то есть полностью случайный интервал от нуля, иначе после общего сбоя клиенты повторно синхронизируются на следующей же волне.",
 "p-stab-backpressure-bounded": "Тонкость с ThreadPoolExecutor: bounded-очередь срабатывает не так, как ждут — пул создаёт новые потоки до maximumPoolSize ТОЛЬКО когда очередь полна, поэтому при corePoolSize<max и большой очереди потоки сверх core никогда не запускаются, задачи просто копятся. А «блокировка продюсера» из коробки не работает: дефолтный AbortPolicy кидает RejectedExecutionException — для реального back pressure нужен CallerRunsPolicy или собственный RejectedExecutionHandler, блокирующий на queue.put().",
 "p-saga-compensation": "В Zeebe/BPMN компенсация — НЕ автоматический rollback состояния: она запускается, только если для шага явно объявлен boundary-событие компенсации с прикреплённой compensation-задачей, и срабатывает лишь при выбросе compensation throw event (или ошибке, которую ловит соответствующий обработчик). Частая ошибка — рассчитывать, что упавший процесс «сам откатится»: без явно смоделированных компенсирующих задач Zeebe просто остановит инстанс в инцидент, оставив уже закоммиченные шаги как есть.",
 "p-pg-hot-fillfactor": "Подвох: HOT ломает ЛЮБОЙ индекс, чьё индексное выражение зависит от изменённой колонки, даже частичный — например partial index WHERE status='active' формально не содержит status в ключе, но Postgres всё равно считает его затронутым и не делает HOT-update. И fillfactor применяется только к новым/перезаписанным страницам: на уже забитой таблице нужен VACUUM FULL или pg_repack, иначе headroom появится не сразу.",
 "p-obs-cardinality-labels": "Коварство именно «бомбы с таймером»: в dev/стейдже сущностей мало, ряды влезают в RAM, проблема невидима до продакшена с реальным объёмом. Защита — не полагаться на ревью: ставь лимиты на стороне сервера (sample_limit в scrape_config, --query.max-samples) и алерт на prometheus_tsdb_head_series; в client-библиотеках Micrometer есть MeterFilter.maximumAllowableTags, который режет взрыв ещё до экспозиции.",
 "p-k8s-liveness-cheap": "Частая ошибка — один общий /health и для liveness, и для readiness: если он трогает БД, ты получаешь ровно тот restart-storm, которого избегал. Ещё ловушка: при медленном старте JVM liveness срабатывает раньше прогрева и крутит под в CrashLoopBackOff — для этого есть отдельная startupProbe (k8s 1.16+, GA в 1.20), которая отключает liveness/readiness, пока приложение не поднимется.",
 "p-obs-burn-rate": "Незаметный нюанс: alert на burn rate должен использовать short+long окна одновременно с условием AND (например 1ч И 5мин), иначе короткое окно даёт ложные срабатывания на одиночном спайке, а длинное — медленно гасит алерт после фикса (long tail). И помни о MTTR: алерт «2% за час при 14.4×» бесполезен, если on-call не успеет среагировать за это время — порог окна надо соотносить с реальным временем реакции команды.",
 "p-k8s-cpu-mem-qos": "Тонкость для JVM: до Java 10 (UseContainerSupport, бэкпортнут в 8u191) JVM видела память/CPU всей ноды, а не cgroup-лимит, и ставила Xmx по хосту → мгновенный OOM-kill в контейнере. Даже сейчас heap — не весь процесс: metaspace, thread stacks, direct buffers и code cache живут вне -Xmx, поэтому контейнеру надо давать limit с запасом над heap (или задавать -XX:MaxRAMPercentage ~75%), иначе RSS превысит limit и придёт OOM-kill без OutOfMemoryError.",
 "p-k8s-sigterm-drain": "Скрытая ловушка PID 1: shell-форма ENTRPOINT (`CMD java -jar app.jar`) запускает процесс под /bin/sh, который НЕ форвардит SIGTERM ребёнку — приложение никогда не увидит сигнал и всегда умрёт по SIGKILL. Нужна exec-форма (`CMD [\"java\",...]`) или init вроде tini/dumb-init. Плюс важен порядок: preStop sleep должен быть ДЛИННЕЕ времени распространения endpoint-removal по kube-proxy, иначе sleep кончится раньше, чем LB перестанет слать трафик.",
 "alg-bst": "Ловушка `TreeMap`/`TreeSet`: они на красно-чёрном дереве сравнивают элементы через `compareTo`/`Comparator`, а НЕ через `equals`. Если `compareTo` несогласован с `equals` (например, BigDecimal со scale: `new BigDecimal(\"1.0\").compareTo(\"1.00\")==0`), то TreeSet сочтёт их одним элементом и `contains` соврёт относительно HashSet.",
 "alg-btree-ds": "Неочевидно: B+tree-индекс по UUID/случайному ключу (или PK на random GUID) даёт page splits по всему дереву и убивает буферный кэш, тогда как монотонный ключ пишет всегда в один правый лист. Поэтому в PostgreSQL/MySQL под высокой вставкой выбирают bigserial/ULID, а не `uuid_generate_v4()` для кластеризующего/первичного ключа.",
 "alg-bfs": "Грабли «BFS = кратчайший путь» обрывается на взвешенных рёбрах: даже с весами 0/1 обычный BFS врёт — нужен 0-1 BFS на деке (push в голову для веса 0), а для произвольных весов Дейкстра. Частая ошибка на собесе — применить BFS к графу, где «рёбра» имеют разную стоимость.",
 "alg-dfs": "Тонкость с visited: для поиска цикла в ОРИЕНТИРОВАННОМ графе одного boolean-visited мало — нужны три цвета (white/gray/black) или отдельный «в текущем стеке рекурсии», иначе ребро в уже полностью обработанную вершину ложно засчитается как цикл. В неориентированном графе наоборот — надо игнорировать ребро к родителю, иначе любое ребро выглядит как цикл.",
 "alg-dp": "Подвох мемоизации в Java: HashMap-кэш с составным ключом обычно требует объекта-ключа (record/list), а примитивы боксятся — на горячем DP это бьёт по GC и скорости; bottom-up на `int[][]`/`long[]` часто в разы быстрее. Плюс при рекурсивной мемоизации легко словить `StackOverflowError` на больших n, чего нет у табличного варианта.",
 "alg-two-ptr": "Скрытая стоимость: «O(n) двумя указателями» честна только если массив уже отсортирован — добавив сортировку, ты платишь O(n log n), и тогда для задачи two-sum хеш-множество за чистый O(n) выигрывает. Two-pointer берут, когда сортировка и так нужна (или данные отсортированы), либо когда критична O(1) память против O(n) у хеша.",
 "alg-sliding": "Классический sliding window работает только когда расширение окна монотонно ухудшает условие, а сужение — улучшает. С отрицательными числами это ломается: для задачи 'минимальный подмассив с суммой ≥ k' с отрицательными значениями добавление элемента может уменьшить сумму, окно не сужается корректно — нужен префиксный массив + монотонный дек (или TreeMap), а не два указателя.",
 "jvm-jre-jdk": "Девиз 'write once, run anywhere' про байткод, но major version .class жёстко привязана: класс, скомпилированный JDK 17 (class file version 61), упадёт с UnsupportedClassVersionError на JVM 11. Поэтому в проде ставят таргет через --release (а не просто -target), иначе можно случайно использовать API новее, чем рантайм, и получить NoSuchMethodError уже при запуске.",
 "sp-stereotypes": "Трансляция исключений в @Repository не работает автоматически по самой аннотации — её включает PersistenceExceptionTranslationPostProcessor, который Spring Boot регистрирует за тебя, но в чистом Spring без Boot его нужно объявить bean'ом явно, иначе нативные PersistenceException/SQLException полетят наружу как есть. Плюс на дефолтных Spring Data репозиториях (SimpleJpaRepository) трансляция и так включена через @Transactional/прокси, так что для интерфейсных репозиториев аннотация роли не играет.",
 "sp-criteria": "Динамическая фильтрация через Specification легко взрывается N+1 и декартовым произведением: каждый .and() с join к коллекции (cb.join по @OneToMany) дублирует корневые строки, и без root.fetch + query.distinct(true) вернётся каша из дублей и лишних запросов. Плюс типобезопасность Criteria иллюзорна без сгенерированного metamodel (классы Entity_) — со строковыми именами полей root.get(\"naem\") вы получите ровно тот же рантайм-падёж, что и в JPQL.",
 "sp-di-types": "Главное реальное преимущество constructor-инъекции — что циклическая зависимость падает на старте — Spring Boot 2.6+ закрепил, по умолчанию запретив циклы вообще (spring.main.allow-circular-references=false), так что field-инъекция перестала их 'проглатывать'. Зато при constructor-инъекции ломается ленивый проксированный self-invocation для @Transactional/@Async: внедрить сам себя через конструктор нельзя (цикл), и приходится либо @Lazy на параметр, либо ObjectProvider — на field/setter self-inject раньше проходил молча.",
 "web-authn-authz": "Имя HTTP-статуса 401 — «Unauthorized» — историческая ошибка спецификации: семантически это про аутентификацию, и RFC 7235 требует возвращать вместе с ним заголовок WWW-Authenticate (иначе по букве стандарта ответ невалиден). Многие фреймворки шлют 401 без него; а в публичных API для скрытия факта существования ресурса от анонима часто намеренно отдают 404 вместо 403.",
 "db-sql-nosql": "«NoSQL = горизонтальное масштабирование, SQL = нет» — устаревший миф: современные SQL дают шардинг и distributed-ACID (CockroachDB, YugabyteDB, Spanner, Citus), а многие NoSQL под нагрузкой режут гарантии по CAP — например, MongoDB до версии 4.0 вообще не имел мультидокументных транзакций, а Cassandra даёт только tunable consistency без настоящих кросс-партиционных транзакций.",
 "jc-func-interfaces": "Тонкость: один и тот же лямбда-литерал может реализовать РАЗНЫЕ функциональные интерфейсы — компилятор выбирает целевой тип по контексту, и при перегрузке метода это даёт ambiguous-ошибку (классика: Runnable vs Callable, или Consumer vs Function для тела, которое и возвращает значение, и может его игнорировать). Лечится явным приведением (Runnable)() -> ... или указанием типа параметра.",
 "jc-flatmap": "flatMap НЕ ленив поэлементно в стороне обхода: внутренний поток, возвращённый функцией, потребляется целиком, прежде чем перейти к следующему элементу, и до Java 10 это ломало short-circuit — например, flatMap(...).findFirst() мог зря вычислить весь первый подпоток (JDK-8075939). А для примитивов есть flatMapToInt/Long/Double — обычный flatMap здесь даст автобоксинг.",
 "jc-primitive-streams": "Неочевидно: IntStream.range(0, n).sum() переполняется молча при суммах > Integer.MAX_VALUE — результат заворачивается без ошибки. Чтобы безопасно агрегировать, делай mapToLong перед sum(); а IntStream.average() возвращает OptionalDouble, и пустой поток даёт OptionalDouble.empty(), а не 0.0 — забытый orElse даёт NoSuchElementException.",
 "jc-collectors": "Неочевидно: Collectors.toMap() и Collectors.toList() возвращают изменяемые HashMap/ArrayList, но это НЕ контракт — Collectors.toList() не гарантирует ни тип, ни мутабельность, ни сериализуемость, поэтому полагаться на add() нельзя; нужен неизменяемый результат — бери toUnmodifiableList()/Stream.toList() (Java 16+), нужна мутабельность — явный toCollection(ArrayList::new). Ещё ловушка: toMap бросает NPE, если valueFn вернула null (в отличие от HashMap.put), потому что внутри используется Map.merge.",
 "jc-multicatch": "Неочевидно: запрещены не только прямые родственники, но и любая пара, где один тип — подкласс другого; при этом throws при rethrow из multi-catch работает умнее, чем кажется — компилятор (начиная с Java 7 'more precise rethrow') анализирует, какие конкретные типы реально могли прилететь, и позволяет объявить в throws более узкий набор, чем общий супертип переменной e.",
 "jc-private-iface": "Неочевидно: private static метод интерфейса может вызываться из static-методов И из default-методов, но обычный (нестатический) private-метод нельзя звать из static-метода интерфейса — нет instance. Ещё тонкость: private-методы НЕ участвуют в разрешении конфликта алмазного наследования (diamond), они невидимы для наследников, поэтому два интерфейса с одинаковым private-методом не конфликтуют.",
 "jc-nio2": "Неочевидно: Files.exists(path) и !Files.exists(path) НЕ являются противоположностями — при отсутствии прав оба могут вернуть false, поэтому для проверки несуществования есть отдельный Files.notExists(), возвращающий третье состояние через невозможность определить. Ещё грабли: Files.lines()/walk() возвращают Stream, держащий открытый дескриптор, и обычный forEach без try-with-resources течёт даже на маленьких файлах.",
 "jc-i18n": "Неочевидно: главная боль локализации — не тексты, а Locale.getDefault(), который незаметно влияет на String.format(\"%.2f\"), toLowerCase()/toUpperCase() и парсинг чисел; классический баг — 'turkish-i': в Locale tr_TR \"TITLE\".toLowerCase() даёт \"tıtle\" (точка над i пропадает), ломая сравнения ключей и SQL. Для машинных, не-UI операций всегда используй toLowerCase(Locale.ROOT).",
 "arch-layered-hex": "Частая ошибка реализации гексагона на JPA: доменная модель аннотируется @Entity и тащит lazy-связи, EntityManager и каскады — домен снова привязан к ORM, хоть порт и есть. Чистый гексагон требует отдельной persistence-сущности и ручного маппинга в адаптере (MapStruct), иначе LazyInitializationException и протечка инфраструктуры в домен.",
 "arch-mono-micro": "Модульный монолит часто проваливается не из-за кода, а из-за общей БД: модули лезут друг к другу через JOIN по чужим таблицам, и граница существует только на бумаге. Реальная изоляция требует схемы-на-модуль и запрета cross-schema FK/JOIN (или ArchUnit-правил на пакеты) — иначе при выделении сервиса вы обнаружите, что данные неразделимы.",
 "arch-12factor": "Stateless относится к памяти процесса, но HTTP-сессия часто остаётся скрытым состоянием: дефолтная in-memory HttpSession в Spring привязывает юзера к инстансу и ломается при масштабировании/рестарте. Нужен либо вынос сессии (Spring Session + Redis), либо stateless-JWT — иначе sticky sessions сводят на нет горизонтальное масштабирование.",
 "arch-bff": "BFF легко вырождается в распределённый God-object: бизнес-логика расползается в слой агрегации, и BFF превращается в де-факто монолит-фасад над всеми сервисами. Держите BFF тонким (только агрегация/трансформация под экран), а доменные решения оставляйте downstream-сервисам — иначе фронт-команда невольно владеет бизнес-правилами.",
 "arch-service-discovery": "Client-side discovery с кэшем реестра даёт окно устаревания: инстанс уже умер, но клиент несколько секунд шлёт на старый адрес, пока не истечёт TTL кэша/heartbeat. Поэтому discovery не заменяет retry + circuit breaker; в Eureka это усугубляет self-preservation mode, который при сетевых проблемах специально НЕ выкидывает «мёртвые» инстансы.",
 "arch-service-mesh": "Sidecar добавляет неочевидный race на старте пода: контейнер приложения может стартовать раньше, чем Envoy готов, и первые исходящие запросы падают (а на завершении приложение умирает, а sidecar ещё держит соединения). Лечится holdApplicationUntilProxyStarts / sidecar-контейнерами Kubernetes 1.28+ и корректным порядком SIGTERM — иначе flaky-ошибки только при деплоях.",
 "arch-read-write-split": "Прилипание к мастеру на N секунд после записи не спасает при чтении из другого инстанса приложения или после редеплоя — токен/маркер read-your-writes должен жить в сессии клиента, а не в памяти ноды; в Postgres надёжнее сравнивать LSN: запомнить pg_current_wal_lsn() после записи и читать с реплики, только когда её pg_last_wal_replay_lsn() догнал его.",
 "arch-cdn": "Vary: Cookie или забытый заголовок Set-Cookie на статике убивает эффективность CDN — edge кэширует по ключу, и куки либо дробят кэш до нуля, либо (хуже) CDN кэширует приватный ответ с чужой сессией и отдаёт его всем; для ассетов жёстко режьте куки и Vary, а приватку помечайте Cache-Control: private/no-store.",
 "arch-load-balancing": "На L7-балансировщике (nginx/ALB) бэкенды видят IP самого LB, а не клиента — без X-Forwarded-For и доверенного списка прокси ломаются гео, rate-limit и аудит; при этом XFF подделывается клиентом, поэтому доверять можно только значению, дописанному вашим LB, а не присланному снаружи.",
 "arch-consensus": "Линеаризуемое чтение нельзя просто взять у лидера: старый лидер мог быть смещён, но ещё считать себя лидером (stale read) — Raft требует, чтобы перед ответом лидер подтвердил лидерство свежим раундом heartbeat-кворума (ReadIndex) или дождался коммита no-op записи своего терма; иначе клиент прочитает устаревшие данные при сетевом разделении.",
 "g-java-navigablemap": "TreeMap сравнивает ключи только через compareTo/Comparator и полностью игнорирует equals — два ключа, не равных по equals, но равных по компаратору, считаются одним; классическая ловушка — Comparator, несогласованный с equals (например, по одному полю), молча перетирает записи, а в TreeSet даёт «исчезающие» элементы.",
 "g-java-generics-capture": "Capture-вывод срабатывает только на один уровень вложенности: List<List<?>> не «ловится» в List<List<T>>, и метод-хелпер не скомпилируется — компилятор не может доказать, что внутренние ? одинаковы; вложенные wildcard'ы требуют либо рекурсивного захвата на каждом уровне, либо явной параметризации.",
 "g-jvm-inlining": "Инлайнинг C2 спекулятивен: на bimorphic call-site (2 реализации) JIT встроит обе ветки с type-guard'ом, но если позже подгрузится третий класс — call-site станет мегаморфным и произойдёт деоптимизация с откатом в интерпретатор. Поэтому добавление новой реализации интерфейса может незаметно замедлить давно работающий горячий код; диагностируется через -XX:+PrintInlining и логи деоптимизаций (-XX:+TraceDeoptimization).",
 "g-jvm-zgc-shenandoah": "Суб-миллисекундные паузы ZGC/Shenandoah не означают суб-миллисекундную latency приложения: при высоком allocation rate сборщик не успевает освобождать память конкурентно и срабатывает allocation stall — поток, запросивший память, блокируется, пока GC не догонит. Лечится не \"включить ZGC\", а увеличением heap/числа конкурентных GC-потоков (-XX:ConcGCThreads), иначе p99 latency взлетает несмотря на \"паузы <1мс\".",
 "g-co-forkjoin-steal": "Размер common pool по умолчанию = доступные ядра − 1, поэтому на машине с 1-2 vCPU (типичный контейнер с заниженными CPU limits) parallelStream() может дать parallelism=1 и работать как последовательный — а Runtime.availableProcessors() в старых JDK не видел cgroup-лимиты. Для гарантированного контроля задавайте java.util.concurrent.ForkJoinPool.common.parallelism или передавайте свой ForkJoinPool в .submit(() -> stream.parallel()...).",
 "g-co-cf-combine-exc": "Если future уже завершён к моменту навешивания thenApply/handle, колбэк выполнится синхронно в потоке, вызвавшем thenApply, а не в пуле — поэтому \"асинхронная\" цепочка может неожиданно отработать на main/HTTP-потоке и заблокировать его. Когда нужен гарантированный отвод в пул, используйте *Async-варианты (thenApplyAsync) с явным Executor, не полагаясь на то, где \"должен\" исполниться колбэк.",
 "g-co-aba": "Распространённое заблуждение, что GC полностью спасает от ABA: он защищает от reuse памяти, но не от логического ABA — например, в lock-free очереди узел можно валидно удалить и снова добавить, ссылка та же, а семантика изменилась. Кроме того AtomicStampedReference внутри боксит пару (ссылка+стамп) в объект Pair на каждое обновление, что создаёт аллокационное давление — для счётчиков это лишнее, штамп нужен именно для указателей.",
 "g-sp-postconstruct": "@Async внутри @PostConstruct молчит, но @Transactional ведёт себя коварнее: self-invocation вообще никогда не открывает транзакцию (даже вне @PostConstruct), потому что вызов self.method() идёт по this мимо прокси — это отдельная, ещё более частая ловушка. И учти: с TransactionTemplate/ProgrammaticTransaction внутри @PostConstruct транзакция как раз сработает, т.к. она не зависит от прокси.",
 "g-sp-lookup": "@Lookup не сработает, если бин создан через @Bean-метод в @Configuration (фабричный метод), — CGLIB-наследование применяется только к компонентам, которые Spring инстанцирует через конструктор, поэтому на фабричных бинах метод останется неабстрактным/невызванным. В таких случаях бери ObjectProvider, который работает независимо от способа создания бина.",
 "g-db-explain-cost-rows": "Главная ловушка: EXPLAIN ANALYZE РЕАЛЬНО выполняет запрос, включая INSERT/UPDATE/DELETE — без обёртки BEGIN; ... ROLLBACK ты испортишь данные в проде. Ещё нюанс: для узлов с loops>1 (внутренняя сторона nested loop) actual rows показываются как СРЕДНЕЕ на одну итерацию, а не суммарно — умножай на loops, иначе кажется, что прогноз совпал, хотя расхождение огромное.",
 "g-db-window-vs-groupby": "Тонкость: при наличии ORDER BY внутри OVER, но без явного frame, дефолтная рамка — RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW, и при дубликатах ключа сортировки RANGE (а не ROWS) суммирует все peer-строки с тем же значением сразу — running total «прыгает» на дубликатах. Для честного построчного накопления указывай ROWS BETWEEN ... явно.",
 "g-ds-compaction": "Неочевидно: compaction НЕ применяется к активному (последнему) сегменту — самые свежие дубликаты ключа остаются в логе, пока сегмент не закроется по segment.ms/segment.bytes, поэтому консьюмер с начала топика всё равно может увидеть несколько версий одного ключа. Плюс min.cleanable.dirty.ratio (по умолчанию 0.5) откладывает зачистку, а tombstone может исчезнуть раньше, чем отставший консьюмер его прочитает, если delete.retention.ms мал — и удаление «потеряется».",
 "g-ds-retry-topics": "Грабли с многоуровневыми retry-топиками: их консьюмеры «спят» до момента дозревания сообщения, и если пауза превышает max.poll.interval.ms (по умолчанию 5 мин), брокер выкинет консьюмера из группы и спровоцирует ребаланс — вместо thread.sleep нужно pause()/resume() партиций либо отдельный scheduler. И помни: при наличии нескольких уровней одно сообщение может обрабатываться повторно дольше суммарного времени всех задержек, поэтому обработчик обязан быть идемпотентным.",
 "g-ds-vector-clock": "Подвох: vector clock сам по себе НЕ разрешает конфликт — он только обнаруживает конкурентность, а слияние (semantic merge или сбор siblings, как в Riak) лежит на приложении; наивно выбрать «больший» вектор нельзя, конкурентные векторы вообще несравнимы. И вектор по числу нод не растёт бесконечно безнаказанно: в Dynamo используют усечение по timestamp/size, что может ошибочно склеить реально конкурентные версии.",
 "g-ds-gossip": "Ловушка: длинная stop-the-world GC-пауза или сетевой фриз останавливает heartbeat-инкременты, и phi-accrual детектор пометит живую ноду упавшей — отсюда ложные failover и flapping. Поэтому пороги детекции (phi threshold, gossip-интервал) тюнят под P99 GC и RTT сети, а не агрессивно «по умолчанию», иначе кластер сам себя разваливает под нагрузкой.",
 "g-te-pact-cdc": "Pact матчит по примерам, а не по схеме, поэтому без matcher'ов (Matchers.like, eachLike, regex) контракт жёстко привязывается к конкретным значениям из теста — провайдер красит сборку, как только реальный id или дата отличаются от зафиксированных; всегда матчь по типу/форме, а не по литералу, иначе тест проверяет данные, а не контракт.",
 "g-te-test-data-builder": "Билдер, переиспользуемый между тестами как поле/синглтон, мутирует общее состояние и даёт зависимость порядка тестов: метод .withX() меняет внутреннее поле билдера, и второй build() наследует значение из первого теста; делай билдер иммутабельным (каждый .withX() возвращает копию) либо создавай свежий экземпляр в каждом тесте.",
 "g-te-line-vs-branch": "JaCoCo считает branch-покрытие по байткоду, а не по исходнику: компилятор разворачивает один тернарник или a&&b в несколько условных переходов, поэтому в отчёте появляются «фантомные» непокрытые ветки на строках без видимого if (например, на закрывающей скобке try из-за неявных finally/null-проверок), что регулярно ломает порог coverage без реального пробела в тестах.",
 "g-te-methodsource": "@MethodSource, отдающий Stream, нельзя переиспользовать: если ту же фабрику подключить к нескольким тестам или открыть Files.lines()/DB-stream, поток будет исчерпан/не закрыт — возвращай заново вычисляемый Stream (или List/массив) на каждый вызов, а внешнюю @MethodSource из другого класса указывай полным именем \"com.pkg.Class#method\".",
 "g-de-adapter-vs-facade": "Подвох: Adapter может быть классовым (extends чужой класс + implements целевой интерфейс) или объектным (хранит ссылку и делегирует) — на собесе ждут, что назовёшь объектный предпочтительным, т.к. классовый невозможен в Java при final-классе вендора и тащит лишнее наследование. А «двусторонний» Adapter (реализует оба интерфейса сразу) — антипаттерн: он нарушает ISP и обычно сигнал, что границы портов размыты.",
 "g-de-template-vs-strategy": "Грабли Template Method: переопределяемые шаги (hook'и) должны быть protected, а сам шаблонный метод — final, иначе подкласс переопределит «скелет» и сломает инвариант порядка шагов; вызов abstract-шага из конструктора базового класса — классический баг, т.к. поле подкласса ещё не инициализировано (NPE). В Strategy симметричная ловушка — stateful-стратегию нельзя делать синглтоном/шарить между потоками без синхронизации.",
 "g-de-command": "Подвох персистентной/очередной Command: команда обязана быть сериализуемой и идемпотентной — при ретраях из Kafka/Zeebe её исполнят ≥1 раза (at-least-once), поэтому без ключа идемпотентности «спиши деньги» спишет дважды. И undo() — это не «откат транзакции БД», а compensating action: для уже отправленного письма или внешнего API настоящего undo не существует.",
 "g-de-state-machine": "Грабли реальной State-машины: настоящая боль не сам switch, а где живут переходы и как они персистятся — если состояние хранится в БД как enum-строка, то переименование/удаление константы ломает чтение старых записей, а конкурентные переходы требуют оптимистичной блокировки (@Version), иначе два потока уведут заказ из одного состояния в разные. Классический GoF-State ещё и плодит лишние объекты-состояния, если они stateless — их стоит делать синглтонами.",
 "g-de-composite": "Подвох Composite в проде: рекурсивный обход глубокого/циклического дерева даёт StackOverflowError, а агрегаты (size()) пересчитываются при каждом вызове — на больших деревьях это O(n) на запрос, лечится кэшированием с инвалидацией вверх по родителям. Циклы (узел добавлен сам себе как потомок) рекурсия не ловит сама — нужна явная проверка при add().",
 "g-de-cohesion-coupling": "Подвох на собесе: low coupling — не «ноль связей», а отсутствие лишних; гонка за минимумом порождает анемичную модель и feature envy (логика утекла в сервис, данные остались в DTO) — это тоже плохое сцепление, просто замаскированное. И «temporal coupling» (методы обязаны вызываться в строгом порядке: init() перед use()) компилятор не ловит — его убирают конструктором/билдером, а не интерфейсами.",
 "g-de-dip-example": "Частая ловушка в Java/Spring: чтобы инверсия была настоящей, порт (interface OrderRepository) должен лежать в модуле/пакете core, а его реализация — в отдельном модуле адаптера, иначе при single-module проекте компилятор всё равно позволит core импортировать JDBC-классы, и DIP существует лишь на словах. Защита — физическое разделение на Maven/Gradle-модули (как в audit-service: audit-core отдельно от адаптеров), тогда нарушение стрелки не скомпилируется.",
 "g-inf-redis-sortedset": "Грабля ZSET для rate-limiter: members должны быть уникальны, иначе два запроса в одну и ту же миллисекунду с одинаковым member затрут друг друга (ZADD обновит score, а не добавит второй элемент) и окно недосчитает; кладите уникальный member (например, timestamp+UUID или counter), а score=timestamp. Также с Redis 6.2 у ZRANGEBYSCORE появился флаг REV и BYSCORE/BYLEX прямо в ZRANGE — старые ZREVRANGEBYSCORE считаются legacy.",
 "g-inf-redis-hll": "Подвох погрешности HLL: заявленные ~0.81% — это стандартное отклонение, а не максимум, поэтому на отдельных значениях ошибка бывает заметно больше, и счётчик может как недо-, так и переоценивать. Критично: PFCOUNT на одном ключе — O(1), но PFCOUNT по нескольким ключам выполняет merge на лету и становится дорогим; для регулярных объединений делайте PFMERGE заранее в отдельный ключ.",
 "g-inf-redis-streams-vs-pubsub": "Тонкость Streams: XACK лишь убирает сообщение из PEL (списка необработанных), но НЕ удаляет его из стрима — без MAXLEN/XTRIM лог растёт вечно даже при идеально работающих консьюмерах. И второе: при падении консьюмера сообщение не перевыдаётся само — нужен фоновый процесс с XAUTOCLAIM (Redis 6.2+) или XPENDING+XCLAIM, иначе подтверждённое-но-зависшее в PEL зависает навсегда.",
 "g-alg-union-find": "Грабля при объединении path compression и union by rank: после сжатия путей хранимый rank перестаёт быть реальной высотой дерева, поэтому его нельзя использовать как настоящую высоту — это просто верхняя оценка-эвристика (потому и называется rank, а не height). И ещё: классическая path compression рекурсивна и на цепочке из миллионов элементов даёт StackOverflowError в Java — для больших n пишите итеративный find или two-pass.",
 "g-alg-trie": "Наивный Trie с HashMap<Character,Node> на узел жрёт память катастрофически (накладные расходы HashMap + автобоксинг Character на каждый узел) и убивает кэш-локальность из-за прыжков по указателям, поэтому на больших словарях он часто медленнее HashMap даже на префиксах; для прод-нагрузок берут double-array trie или radix-tree, а не учебный вариант с мапой детей.",
 "g-alg-heapsort": "Build-heap за O(n) даёт строгую оценку, но интуиция «n узлов × log n» врёт: сумма работы сходится к 2n именно потому, что листьев (которые не просеиваются) ровно половина, а глубоких узлов мало — линейность держится только при sift-down снизу вверх, а не при наивных n вставках через sift-up, которые дадут честные O(n log n).",
 "g-alg-toposort": "Алгоритм Кана недетерминирован: при нескольких вершинах с in-degree 0 порядок зависит от структуры очереди, так что один и тот же DAG даёт разные валидные результаты — если нужна воспроизводимость (стабильная сборка, детерминированные миграции), берите PriorityQueue по ключу, а не обычный ArrayDeque.",
 "g-alg-binsearch-answer": "Классический баг — переполнение и зацикливание на середине: `mid = (lo+hi)/2` переполняет int при больших границах (пишите `lo + (hi-lo)/2`), а при поиске минимума выбор `mid = (lo+hi+1)/2` vs без +1 определяет, на какой стороне округление, и неверный выбор даёт бесконечный цикл, когда `hi-lo==1`.",
 "g-git-tag-annotated": "Ловушка `git checkout v1.0` и подобных: тег указывает на коммит, и переход на него даёт detached HEAD — новые коммиты «на теге» теряются при следующем переключении; плюс по умолчанию `git push` не отправляет теги, а annotated-тег с тем же именем, что и ветка, ломает разрешение ссылок, поэтому именуйте теги недвусмысленно (`v1.0`, не `release`).",
 "g-git-no-ff-merge": "git config merge.ff влияет только на ЛОКАЛЬНЫЙ merge: при squash- или rebase-merge через GitHub/GitLab UI узел слияния всё равно не создаётся, поэтому 'откатить одним revert -m 1' работает только если PR смержен именно merge-commit-стратегией. И помни: revert merge-коммита с -m 1 'пришивает' ветку как обработанную — повторный merge той же ветки потом не вольёт изменения, нужен revert of the revert.",
 "g-ops-docker-layer-cache": "Порядок COPY — лишь половина дела: в CI кэш слоёв по умолчанию ПУСТОЙ на каждом раннере (свежий Docker daemon), поэтому dependency:go-offline всё равно качает всё заново, пока не подключишь --cache-from / registry-cache (BuildKit) или persistent cache. И go-offline в Maven печально известен тем, что тянет не все плагины/зависимости — часть докачивается на этапе сборки, ломая офлайн-изоляцию слоя.",
 "g-ops-latest-tag": "Главный коварный момент: с imagePullPolicy ставится :latest по умолчанию Always, а с конкретным тегом — IfNotPresent, поэтому immutable-тег без digest всё равно небезопасен, если тег кто-то перезапушил (реестр это позволяет, кроме ECR immutable-режима). Реальную воспроизводимость даёт только pin по digest (app@sha256:...), а не текстовый тег.",
 "g-ops-semver-breaking": "Тонкость диапазонов: для 0.x.y npm трактует ^0.4.1 как >=0.4.1 <0.5.0 (caret ведёт себя как tilde), то есть 0.5.0 НЕ подтянется автоматически — частая причина 'почему не обновилось'. И SemVer покрывает только видимый API: смена транзитивной зависимости или поведения в рантайме (формат логов, дефолты) формально не breaking, но реально ломает потребителей.",
 "g-ops-ci-secrets": "Маскирование в логах ловит только точное совпадение строки: base64/URL-encoded или разбитый на части секрет (например в JSON-выводе) проходит в лог незамаскированным. А BuildKit --mount=type=secret защищает лишь от попадания в слой — если внутри RUN ты сделаешь echo секрета или запишешь его в файл, который потом COPY'ишь, он всё равно осядет в образе.",
 "g-ops-terraform-state": "Ловушка: S3+DynamoDB lock, который все знают как канон, с релиза Terraform 1.10 (ноябрь 2024) считается легаси — S3-backend теперь умеет нативный lockfile через параметр `use_lockfile = true`, а отдельная DynamoDB-таблица (`dynamodb_table`) объявлена deprecated и удаляется в Terraform 1.11+. Если копируете старый туториал на новую версию, ловите варнинги и лишний ресурс; если у вас уже есть DynamoDB-lock — нельзя выкидывать его одним коммитом, иначе часть команды на старых бинарниках останется без блокировки.",
 "g-ops-rollback-migration": "Неочевидное: expand/contract спасает от DROP COLUMN, но молча ломается на сужении типа и NOT NULL — например, `ALTER ... TYPE varchar(50)` или добавление `NOT NULL` без DEFAULT не обратно-совместимы, а на больших таблицах в Postgres такой ALTER берёт `ACCESS EXCLUSIVE` lock и кладёт сервис ещё до всякого отката. Поэтому новую NOT NULL-колонку добавляют как nullable + бэкфилл + отдельный constraint позже, а не «добавил колонку — значит безопасно».",
 "g-arch-bounded-context": "Тонкость, которую путают на собеседовании: Bounded Context — это граница ЯЗЫКА/модели, а не команды и не деплой-юнита, поэтому в одном микросервисе законно могут жить два контекста, а один контекст может разворачиваться несколькими сервисами. Частая ошибка — приравнять контекст к субдомену: субдомен — это часть проблемного пространства (что есть в бизнесе), контекст — решение в пространстве кода, и маппинг между ними не всегда 1:1.",
 "g-arch-domain-event": "Подвох: «синхронные обработчики в той же транзакции» — это удобно, но именно здесь рождается анти-паттерн, когда один domain-event-хендлер модифицирует ДРУГОЙ агрегат в той же транзакции, нарушая правило «один агрегат — одна транзакция» и порождая дедлоки/раздувание границ согласованности. Канонический DDD-совет: побочные эффекты на соседних агрегатах делать асинхронно (eventual consistency), а синхронно в транзакции трогать только тот же агрегат.",
 "g-arch-cqrs-readmodel": "Ловушка реализации: read-модель, обновляемая из событий, обязана быть идемпотентной и устойчивой к переупорядочиванию — при at-least-once доставке (Kafka) одно и то же событие прилетит дважды, а события разных партиций придут не по порядку, и наивный проектор задвоит/перезапишет строку устаревшими данными. Лечится версией/seqno агрегата в проекции (применять только если version > current) либо upsert по ключу, а не слепым INSERT.",
 "g-arch-acl": "Главная ловушка ACL — он живёт в твоём bounded context (на твоей стороне), а не у легаси: команды часто пихают трансляцию в общий shared-модуль или в сам легаси-сервис, и тогда чужая модель снова протекает к нескольким потребителям. Второй грабль — ACL не бесплатен по latency/CPU (маппинг + иногда доп. вызовы для обогащения), поэтому для критичного по производительности пути его надо профилировать, а не считать «тонким».",
 "web-soap": "Скрытая боль SOAP — не объём XML, а несовместимость стеков: WS-I Basic Profile появился именно потому, что один и тот же WSDL по-разному генерил клиентов на .NET и Java (особенно rpc/encoded, xsd:choice, полиморфные типы). Плюс WS-Security с XML Digital Signature крайне чувствителен к канонизации (C14N): любой прокси/балансировщик, переформатирующий XML, ломает подпись, хотя данные не менялись.",
 "web-webhook": "Неочевидная дыра — проверять HMAC-подпись надо по СЫРОМУ телу (raw bytes) до парсинга JSON: если фреймворк (Spring, Quarkus, Express) десериализует и пере-сериализует payload, порядок ключей/пробелы меняются и подпись перестаёт сходиться. Поэтому в Spring читают тело через ContentCachingRequestFilter / собственный фильтр, а не из уже распарсенного DTO.",
 "web-openapi": "Грабли code-first в Java: генераторы (springdoc, Quarkus SmallRye OpenAPI) часто не выводят корректно nullable/required, generic-обёртки и полиморфизм (oneOf/discriminator) — из-за стирания типов и того, что Bean Validation аннотации не всегда мапятся в схему. В итоге сгенерированный клиент валиден по спеке, но падает на реальном ответе; спасает контракт-тест против РЕАЛЬНОГО эндпоинта, а не против самой спеки.",
 "web-saml-oidc": "Классическая ловушка OIDC: для авторизации API нужно проверять Access Token, а не ID Token — ID Token предназначен только для клиента-аутентификации и его audience (aud) указывает на client_id, а не на API; если ресурс-сервер валидирует ID Token, любой клиент с тем же IdP пройдёт. У SAML аналогичная ловушка — обязательна проверка подписи assertion и поля Audience/Recipient/NotOnOrAfter, иначе классический XML Signature Wrapping (XSW) даёт обход.",
 "ws-camunda": "Грабли Camunda 7: каждый wait state (user task, async-before/after, таймер) — это коммит транзакции, но синхронный участок между двумя wait-state'ами выполняется в ОДНОЙ транзакции, и исключение в конце откатывает ВСЕ промежуточные сервис-таски, включая уже сделанные внешние вызовы. Поэтому перед/после нетранзакционных шагов (HTTP, отправка письма) ставят async-границы, иначе при ретрае шаг выполнится повторно.",
 "ws-bpmn": "Скрытая ловушка шлюзов: у exclusive (XOR) gateway, если ни одно условие не истинно и нет default-flow, движок бросает исключение и инцидент — всегда задавай default. И не путай parallel (AND) join, который ЖДЁТ все входящие ветки, с inclusive (OR) join, чья синхронизация дороже и требует, чтобы открывающий inclusive-шлюз корректно активировал ровно те ветки, что join потом дождётся — рассинхрон ветвей вешает токен.",
 "ws-job-worker": "Тонкость pull-модели: job-воркер должен завершить работу до истечения lock/job timeout, иначе движок считает job брошенным и отдаёт его ДРУГОМУ воркеру — получаешь двойное выполнение, а потом `complete` от первого воркера падает с NotFound. Поэтому таймаут ставят с запасом на p99 латентности, операцию делают идемпотентной по ключу job, а долгие задачи дробят или продлевают аренду.",
 "sd-back-of-envelope": "Где прикидка реально врёт: усреднённый QPS прячет хвост — при 50k QPS среднем латентность определяет p99/p999, а не среднее, и закон Литла (concurrency = throughput × latency) показывает, что рост latency раздувает число одновременных соединений/потоков и кладёт пул раньше, чем исчерпается CPU. Поэтому ёмкость считают по пиковому QPS И по tail-latency, а не по среднему.",
 "sd-qps-readwrite": "Ловушка деления на 10^5: трафик не размазан равномерно по суткам — у большинства продуктов дневной пик идёт сверху на и так неравномерный профиль, и реальное пиковое QPS бывает в 5-10x, а не ×2-3, от среднего (классика — Twitter-фан-аут на знаменитость или flash-sale). Считай ёмкость по worst-case паттерну, а не по усреднённому ×3, иначе ляжешь именно в тот момент, ради которого систему и строили.",
 "sd-cap-theorem": "Частая путаница на собесе: «C» в CAP — это линеаризуемость (строгая single-object консистентность), а НЕ ACID-'Consistency' из транзакций и не serializable-изоляция. Поэтому фраза «MongoDB/Postgres — CP» бессмысленна без указания уровня: одна и та же СУБД сдвигается по спектру настройками (write concern, read concern, sync-реплики), и реальная гарантия определяется конфигом, а не строкой в маркетинге.",
 "sd-chat-presence": "Скрытая боль presence — не сам TTL, а fan-out на «толстых» юзерах: один человек с миллионом подписчиков, заходя/выходя, порождает миллион notify-событий, и при флапающем коннекте это превращается в шторм. Поэтому presence-апдейты дебаунсят (не слать раньше, чем через N секунд стабильного состояния) и читают pull-моделью по запросу, а не пушат каждое мерцание онлайна.",
 "rx-streams-api": "Тонкость контракта, которую заваливают: onSubscribe/onNext/onComplete/onError одного Subscriber должны вызываться сериализованно (happens-before, как из одного потока) — Publisher НЕ имеет права слать onNext конкурентно из двух тредов, даже если суммарно request(n) позволяет. Именно поэтому свой Publisher почти никогда не пишут руками: в Reactor/RxJava за сериализацию и корректную доставку отвечают операторы вроде `serialize()` и сами фабрики (`Flux.create`).",
 "rx-overflow-strategies": "Грабли: операторы `onBackpressure*` управляют только границей МЕЖДУ конкретными стадиями, а не источником — если у тебя горячий источник без backpressure (timer, сетевой push), реальную защиту даёт стратегия на самой эмиссии (`Flux.create(sink, OverflowStrategy)`), иначе MissingBackpressureException прилетит выше по цепочке. И DROP/LATEST дропают молча — без `doOnDiscard`/метрик ты не увидишь, что данные теряются, и будешь искать «пропавшие» события в логах приёмника.",
 "rx-push-pull": "request(n) накапливается аддитивно (request(1) дважды = дем-энд 2), а не перезаписывается; при этом по спецификации Reactive Streams §3.17 суммарный demand не должен переполнять Long.MAX_VALUE, и request(Long.MAX_VALUE) трактуется как 'unbounded' — фактически отключает backpressure, превращая поток в чистый push. Многие операторы (например flatMap с concurrency по умолчанию 256, или onBackpressureBuffer) молча буферизуют, и OutOfMemoryError прилетает не там, где медленный консьюмер, а в неограниченном буфере выше по цепочке.",
 "rx-mono-flux-uni-multi": "Mono<Void> и пустой Mono — разные вещи на практике: оператор then()/thenEmpty() игнорирует значения, но Mono, который никогда не эмитит onComplete (например забытый sink.success()), молча подвешивает всю цепочку без ошибки и без таймаута. Ещё ловушка: Mono может легально завершиться вообще без onNext (как пустой Optional), поэтому код вроде mono.map(...) на пустом Mono просто не выполнится — нужен defaultIfEmpty/switchIfEmpty, а не предположение, что значение точно будет.",
 "rx-zip-merge-combine": "zip с источниками разной длины тихо ОБРЫВАЕТ результат по самому короткому и отменяет (cancel) остальные — лишние элементы длинного потока теряются молча, что особенно опасно если у длинного потока есть сайд-эффекты (запись, ack). combineLatest же может 'проглотить' самый первый элемент быстрого источника, если медленный ещё ничего не выдал, и выдаёт устаревшие комбинации при разной частоте входов — для гонки за финальным значением безопаснее zip/Uni.combine, а не combineLatest.",
 "grpc-codegen-idl": "Contract-first не спасает от семантической несовместимости: proto3 убрал required и сделал ВСЕ скалярные поля имеющими дефолт (0, \"\", false), без presence-информации — поэтому до добавления optional (proto3 presence, вернулось в protoc 3.15) нельзя отличить 'поле не прислали' от 'прислали 0/пустую строку'. Это регулярно ломает PATCH-семантику и валидацию: сервер видит amount=0 и не знает, обнуление это или просто отсутствие поля.",
 "grpc-call-types": "Порядок гарантирован только внутри ОДНОГО HTTP/2 stream'а (одного вызова); в bidirectional-стриме нет автоматической корреляции запроса с ответом — если шлёшь несколько запросов не дожидаясь ответов, сервер вправе отвечать в любом порядке, и сопоставление надо делать самому (по id в сообщении). Плюс classic-ловушка: gRPC-стримы держат HTTP/2-соединение открытым, и без явного deadline/keepalive 'подвисший' сервер-стриминг (котировки, подписка) может молча умереть на промежуточном L4-балансировщике/idle-timeout, а клиент будет вечно ждать.",
 "grpc-proto-fields": "Удалять поле просто стерев его из .proto — мина: номер может быть позже переиспользован под другой тип, и старые сериализованные данные/клиенты декодируются с порчей; именно поэтому нужен reserved (и для номеров, и для имён), который protoc принудительно запрещает занять снова. И ещё: смена типа поля при сохранении номера совместима ТОЛЬКО внутри одной wire_type-группы (int32/int64/uint32/bool/enum взаимозаменяемы как varint, но int32↔string ломает декодирование) — номер совпадает, а данные читаются мусором.",
 "grpc-vs-rest": "Дефолтный лимит размера сообщения в gRPC — 4 MB (maxInboundMessageSize), и при больших payload'ах вы внезапно ловите RESOURCE_EXHAUSTED, а не понятную ошибку; для крупных данных нужно либо поднимать лимит, либо переходить на streaming, потому что одно gRPC-сообщение всегда буферизуется в память целиком, а не стримится по байтам внутри самого сообщения.",
 "crypto-signature": "Распространённая ловушка — путать RSA-подпись с «шифрованием приватным ключом»: настоящие схемы (RSASSA-PSS, и даже старый PKCS#1 v1.5) включают padding и кодирование DigestInfo, а не голую модульную экспоненту хэша; наивная реализация «encrypt(hash, privateKey)» уязвима к forgery (атаки Bleichenbacher, e=3), поэтому всегда используйте проверенную библиотеку и PSS вместо самописного RSA.",
 "ds-skip-list": "ConcurrentSkipListMap НЕ хранит реальный size в поле — её size() обходит весь список за O(n) и не атомарен под конкурентными изменениями, поэтому частые вызовы size()/isEmpty() в горячем пути — скрытый killer производительности; для проверки пустоты используйте isEmpty() (он смотрит только первый узел), а не size()==0.",
 "web-owasp-top10": "⚠️ OWASP Top-10 — это baseline для awareness, а НЕ критерий «прошли — значит безопасны». Закрыть все 10 категорий не равно «приложение защищено»: это покрытие самых частых рисков, а не верификация. Для реальной проверки безопасности используйте OWASP ASVS (Application Security Verification Standard) с уровнями L1–L3, а Top-10 держите как стартовый ориентир в ревью, а не как финальный знак качества.",
 "web-supply-chain": "⚠️ Системный флаг `-Dlog4j2.formatMsgNoLookups=true` и переменная окружения НЕ являются полноценной защитой: они не закрывают все векторы и не работают для версий < 2.10. Единственный надёжный фикс — обновить сам артефакт до 2.17.1+. И не забудь про shaded-копии log4j внутри fat-jar других зависимостей — `dependency:tree` их не видит, нужен сканер содержимого (Trivy/grype).",
 "web-idor": "⚠️ Authentication ≠ authorization. Валидный JWT/сессия доказывают только КТО ты, но не что тебе можно ЭТОТ объект. Тысячи IDOR-уязвимостей живут именно в коде, где разработчик увидел `@Authenticated` и решил, что доступ закрыт — а проверки владения объектом там нет. И никогда не доверяй `owner_id`/`role`/`tenant_id`, пришедшим в теле запроса: бери их из серверного контекста аутентификации.",
 "web-secrets": "⚠️ git filter-branch/BFG и force-push НЕ удаляют секрет: форки, локальные клоны, кэши CI, PR-снапшоты GitHub и зеркала сохраняют старые коммиты. После любой утечки секрет надо немедленно ротировать (отозвать ключ) — «вычистить историю» это не защита, а косметика.",
 "web-security-headers": "⚠️ Браузер блокирует комбинацию `Access-Control-Allow-Origin: *` + `Allow-Credentials: true`, и многие ошибочно считают это «безопасным по умолчанию». Но если сервер вместо `*` рефлектит присланный `Origin` (или валидирует его через `contains`/`endsWith`), запрет обходится — это полноценная уязвимость на кражу данных. CORS-заголовки управляют чтением ответа, а не доступом к ресурсу: они НЕ заменяют авторизацию и НЕ защищают от CSRF.",
 "web-rate-limit": "⚠️ Одинаковый ТЕКСТ ошибки не спасает от enumeration, если тайминг разный: при отсутствующем юзере код часто пропускает bcrypt/argon2 и отвечает за миллисекунды, а при существующем — считает хэш сотни мс. Атакующий перечисляет аккаунты по времени ответа. Всегда выполняй проверку пароля против dummy-хэша даже когда пользователь не найден (constant-time path).",
 "jvm-thread-dump": "⚠️ Встроенный deadlock-детектор JVM находит взаимоблокировки на intrinsic-мониторах (`synchronized`) и на ownable-локах из `java.util.concurrent.locks` (через `ThreadMXBean.findDeadlockedThreads()`), но НЕ видит дедлоки на семафорах, `CountDownLatch`, обмене сообщениями или внешних ресурсах (пул JDBC-соединений). Поэтому отсутствие строки «Found one Java-level deadlock» в дампе НЕ гарантирует, что система не висит в живом залоке — visually-stuck потоки на park()/wait() придётся разбирать руками по нескольким дампам.",
 "jvm-heap-dump": "⚠️ Снятие heap dump — это stop-the-world: для кучи в 8–16 ГБ JVM замирает на десятки секунд, и .hprof весит столько же, сколько занятая куча (нужно место на диске + туда же может прилететь по флагу при OOM). Не запускай `jmap -dump` вслепую на пиковом проде — уведёшь инстанс в таймауты health-check и его перезапустят. Снимай на реплике/канарейке или в окно низкой нагрузки.",
 "jvm-profiling": "⚠️ В Docker/Kubernetes `async-profiler -e cpu` молча деградирует или падает, если в контейнере недоступны `perf_events` (`kernel.perf_event_paranoid > 1` или нет `CAP_SYS_ADMIN`/`CAP_PERFMON`). Симптом — пустой или искажённый flame graph. Лечение: либо понизить `perf_event_paranoid`, либо запускать с `-e itimer` (работает без привилегий, но менее точен для нативных кадров). И без `-XX:+DebugNonSafepoints` ты теряешь точность даже у async-profiler — JVM не пишет debug-инфо вне safepoint'ов по умолчанию.",
 "sp-jpa-projection": "⚠️ Open interface-projection с `@Value(\"#{target...}\")` (SpEL по target) тайно грузит ПОЛНЫЙ entity и применяет выражение в памяти — `SELECT *` + managed-объект, вся экономия проекции теряется. Для узкого `SELECT` нужна closed-проекция: только простые геттеры, мапящиеся 1:1 на колонки, без SpEL.",
 "ops-correlation-id": "⚠️ MDC сидит в ThreadLocal — на каждой async/reactive/Kafka-границе traceId теряется, если контекст не перенести явно (TaskDecorator, context-propagation, record headers). И зеркальная беда: пул потоков переиспользует поток, поэтому забытый `MDC.clear()` тащит чужой traceId в следующий запрос — логи «склеиваются» не с тем трейсом.",
 "jc-init-order": "⚠️ Частая ошибка в объяснении: `class Child { final String name = \"x\"; }` + виртуальный getName() из конструктора Parent НЕ печатает null — печатает \"x\". `final String name = \"x\"` это constant variable (JLS 4.12.4, правило действует и для instance-полей), компилятор делает constant-folding: байткод getName() это `ldc \"x\"; areturn`, поле вообще не читается. null вы увидите только если final НЕ константный: blank final (`final String name;` + `this.name = \"x\"` в теле конструктора) или инициализатор-выражение (`final String name = compute()`). Оба проверены — печатают null.",
 "jc-final-finally-finalize": "⚠️ Главный миф: \"finalize() уже отключена в новых JDK\". Нет — по умолчанию она ЕЩЁ ВЫЗЫВАЕТСЯ. Отключается только явным флагом `--finalization=disabled` (JEP 421, Java 18). И путаница в датах: `forRemoval=true` на самом `Object.finalize()` стоит **since=\"9\"** (уровень метода), а JEP 421 в Java 18 пометил deprecated for removal весь механизм и добавил флаг отключения. Удаление — план, а не факт.",
 "jc-override-overload": "⚠️ Распространённая ошибка — приписывать выбор перегрузки рантайму/`invokevirtual`. На самом деле сигнатуру перегрузки выбирает **javac в compile-time** и зашивает фиксированный дескриптор в байт-код; `invokevirtual` — это механизм **override** (динамическая диспетчеризация по vtable), а не overload. И: перегрузку **нельзя** различать по типу возврата — return type входит в дескриптор JVM, но в выборе overload не участвует.",
 "jc-hashmap-treeify": "⚠️ Распространённое заблуждение: «find() в дереве выбирает поддерево по identityHashCode». Нет. В `find()` на равных хэшах сначала работает `equals()`, затем — для Comparable-ключей — `compareTo`; для не-Comparable детерминированного направления нет, поэтому find обходит ОБА поддерева (→ O(n)). `System.identityHashCode`/`tieBreakOrder` вызываются ТОЛЬКО при вставке (`treeify`/`putTreeVal`) для стабильного размещения, и НЕ участвуют в поиске.",
 "jc-immutable-collections": "⚠️ `Collections.unmodifiableList(src)` НЕ делает копию — это живая вью: кто держит ссылку на `src`, может его менять, и изменения видны сквозь обёртку. Для настоящей защитной копии берите `List.copyOf(src)`: он делает immutable-копию мутабельного источника, НО short-circuit'ит — если источник уже List.of-immutable, возвращает ТОТ ЖЕ объект (`List.copyOf(List.of(1,2,3)) == List.of(1,2,3)` → true), копии не происходит. Ещё ловушка: `Arrays.asList(new int[]{1,2,3})` даёт `List<int[]>` размера 1 (примитивный массив не разворачивается в varargs), а `Arrays.asList(arr).set(i,v)` молча пишет в исходный массив.",
 "gap-co-cf-default-executor": "⚠️ Частый миф: «при 1 vCPU commonPool создаёт по потоку на задачу (ThreadPerTaskExecutor) или вырождается в синхронное исполнение». Неверно. Дефолтный Executor у CompletableFuture — это `ForkJoinPool.commonPool()` (через `asyncCommonPool`), и он всегда ограниченный пул: при parallelism=0 принудительно поднимается до 2 воркеров, при parallelism=1 гоняет все задачи по очереди на одном воркере. Поток-на-задачу не плодится. Реальная боль — обратная: воркеров СЛИШКОМ МАЛО, поэтому блокирующие async-цепочки забивают очередь и стопорят другие commonPool-задачи (parallel streams, чужие CF). Вывод тот же: под блокировки — свой Executor.",
 "jc-stream-infinite": "⚠️ Распространённое заблуждение: «distinct() — такой же барьер, как sorted(), и `iterate(1, n->n+1).distinct().limit(5)` повиснет/упадёт в OOM». Неверно — на JDK проверяется: этот конвейер завершается с `[1,2,3,4,5]`, вытягивая ровно 5 элементов, потому что limit ниже distinct() короткозамыкает pull. Барьер — только `sorted()` (и `count()` на не-SIZED): они обходят весь вход и потому висят даже с limit НИЖЕ них. Реальная опасность `distinct()` на бесконечном источнике — рост seen-множества, и только когда НИЧЕГО ниже не short-circuit'ит pull; нижний `limit` его спасает. Правило: ставь `limit` ДО `sorted()` (барьер), а после `distinct()` он и так гасит конвейер.",
 "jc-groupingby-downstream": "⚠️ counting() возвращает Long, не int — `int n = map.get(k)` не скомпилируется (Long → int неявно нельзя; нужно `long n = …` или `int n = map.get(k).intValue()`). А вот частый миф про == здесь НЕ работает так, как кажется: `map.get(k) == 200` (int-литерал) даёт TRUE даже для 200 (вне кэша −128..127), потому что Long распаковывается до long и сравнение числовое. Кэш боксинга (−128..127) ломает только сравнение ДВУХ обёрнутых ссылок: `Long a = 200L, b = 200L; a == b` → false. Так что с downstream-Long сравнивайте либо через .equals(), либо распаковывайте явно (`map.get(k).longValue() == 200`), а не полагайтесь на «== всегда сломан из-за кэша».",
 "gap-serial-externalizable": "⚠️ Не путай: при Externalizable из потока пропадают метаданные ПОЛЕЙ (имена/типы) и автозапись значений — но дескриптор класса (имя + serialVersionUID) всё равно пишется. Сказать «метаданные класса не пишутся» — неверно. И помни: при обычной десериализации Serializable конструктор сериализуемого класса НЕ вызывается (инварианты из конструктора могут не выполниться) — а вот Externalizable обязательно дёргает публичный no-arg конструктор перед readExternal.",
 "gap-exc-chaining-cause": "⚠️ Stacktrace в SLF4J теряется НЕ из-за `{}`. `log.error(\"msg {}\", e)` печатает полный trace — `{}` остаётся литералом. Trace пропадает, только когда Throwable стоит НЕ последним аргументом (после него есть ещё параметр), и его поглощает плейсхолдер через `toString()`: `log.error(\"x={}\", e, \"tail\")` → `x=java.lang.RuntimeException: boom` без trace. Правило простое: throwable — всегда последний аргумент.",
 "gap-io-byte-char-charset": "⚠️ JEP 400 (Java 18) сделал UTF-8 дефолтом только для **самой JVM** (`java.io`/`java.nio`). Это НЕ чинит: (1) `System.console()`/`Console.charset()` — там по-прежнему native-кодировка консоли; (2) файлы, реально записанные в cp1251 другим софтом; (3) запуск на старых JVM (≤17), где дефолт = локаль платформы. И главное — невалидные байты не падают, а молча становятся `�` (U+FFFD) из-за `CodingErrorAction.REPLACE`. Всегда передавай `StandardCharsets.UTF_8` явно, не надейся на дефолт.",
 "sp-tx-nested-savepoint": "⚠️ Неверно думать, что «NESTED = REQUIRES_NEW, только дешевле». При REQUIRES_NEW внутренняя транзакция коммитится отдельно: если потом упадёт ВНЕШНЯЯ, уже закоммиченные внутренние данные НЕ откатятся. При NESTED всё в одной физической транзакции — откат внешней снесёт и вложенное. И ещё: NESTED у `JpaTransactionManager` по умолчанию выключен (`nestedTransactionAllowed=false`) — это НЕ «JPA не умеет savepoints», умеет; флаг просто надо включить вручную. А вот `JtaTransactionManager` savepoints не поддерживает в принципе.",
 "sp-tx-readonly": "⚠️ Под readOnly=true Hibernate в FlushMode.MANUAL: если ты случайно изменишь managed-сущность, UPDATE НЕ полетит — flush не сработает, изменение тихо потеряется (не исключение!). И помни: readOnly учитывается только на ВНЕШНЕЙ транзакции (REQUIRED). Если внутренний readOnly=true-метод просто присоединяется к уже открытой readOnly=false-транзакции — флаг проигнорируется, новая транзакция с MANUAL flush не создастся.",
 "h-entity-states-merge-persist": "⚠️ merge(detached) НЕ делает аргумент managed — он остаётся detached, а managed это ТОЛЬКО возвращённое значение. Классическая ловушка: `repo.save(dto); return dto;` отдаёт detached-объект (со старым/null id и без подхваченных полей). Надо `dto = repo.save(dto)`. Второй капкан: частично заполненный граф из REST + `orphanRemoval=true` — merge увидит «пустую» коллекцию детей и удалит строки в БД.",
 "h-flush-vs-commit": "⚠️ Огромный батч + дефолтный FlushMode.AUTO = деградация. Цикл на N сущностей при каждом промежуточном запросе вызывает auto-flush, а каждый flush — это полный dirty-checking-проход по ВСЕМ managed-сущностям в контексте, то есть O(n²) работы по сравнению снапшотов (не по числу отправленных UPDATE — уже отправленные строки повторно в БД не летят). Лечится `flush()`+`clear()` пачками и `FlushMode.MANUAL` на время цикла. И помни: с `GenerationType.IDENTITY` JDBC batch-insert вообще не работает — INSERT летит сразу на каждый persist().",
 "h-lazy-proxy-getreference": "⚠️ Частая ошибка-перевёртыш: думать, что `proxy instanceof Order` вернёт false. Нет — прокси это подкласс, instanceof = true. Ломается именно `getClass() == Order.class` (вернёт false, т.к. класс — `Order$HibernateProxy$xxx`). Поэтому НЕ пиши `getClass() == o.getClass()` в equals()/hashCode() JPA-сущностей — прокси и managed-инстанс одной строки будут «не равны». Используй `instanceof` для типа и `Hibernate.getClass()` для настоящего класса.",
 "sp-jpa-batch": "⚠️ `reWriteBatchedInserts` (camelCase) — параметр именно драйвера PostgreSQL (pgjdbc), для других БД он бессмыслен. На MySQL вообще нет sequence-объектов (это фича Postgres, её нет ни в одной версии MySQL, включая 8.0) — используй `TABLE`-генератор для батч-вставок или включи `rewriteBatchedStatements=true` в JDBC URL Connector/J (другое имя, другой драйвер).",
 "sp-jpa-flush": "⚠️ Зеркальный антипаттерн: ждать UPDATE от dirty-checking ВНУТРИ readOnly-метода — он не прилетит (MANUAL душит авто-flush на коммите). И наоборот: считать readOnly «защитой от записи» опасно — JPQL/native `UPDATE`/`DELETE` через `executeUpdate()` и любой явный `entityManager.flush()` спокойно пишут в БД, минуя MANUAL.",
 "ops-three-pillars": "⚠️ Не путай Histogram и Summary в Prometheus. Summary даёт готовый `{quantile=\"0.99\"}`, посчитанный в приложении, — его НЕЛЬЗЯ агрегировать по инстансам (нельзя `avg`/`sum` квантили). Только Histogram (`_bucket{le}`) позволяет `sum by(le)` + `histogram_quantile` на пуле подов. И ещё: точность p99 ограничена границами корзин — `histogram_quantile` лишь интерполирует внутри корзины, поэтому грубые `le` дают грубый перцентиль.",
 "jc-stream-peek": "⚠️ Не лечи это через `.limit()` — на SIZED-источнике limit/skip сохраняют точный размер, peek так же промолчит. Стирают SIZED только filter/distinct/flatMap. И отдельно: в `parallelStream()` peek вызывается на нескольких worker-потоках ForkJoinPool одновременно (проверено: 9 разных потоков на 1000 элементов) — любой побочный эффект в peek обязан быть потокобезопасным, а порядок вызовов не определён.",
 "g-te-dont-mock-dont-own": "⚠️ Mockito по умолчанию возвращает для коллекций и `Optional` **пустые объекты, а не `null`** — `repo.findAll()` на незастабленном моке вернёт пустой `List`, а `repo.findById()` — `Optional.empty()`. Тест с забытым стабом не упадёт на NPE, а тихо пройдёт по ложной причине. Если хочешь, чтобы незастабленные вызовы громко падали, используй `RETURNS_SMART_NULLS` или строгие стабы. И не путай: `BigDecimal` не `final` (mock-able), но это всё равно чужой value-object — строй его, а не мокай.",
 "web-ssrf": "⚠️ Allowlist по доменному ИМЕНИ уязвим к DNS rebinding: при проверке имя резолвится в публичный IP, а при самом запросе (TTL=0) — во внутренний. Резолви имя сам, проверяй полученный IP против чёрного списка приватных диапазонов и обращайся ИМЕННО к этому IP. И про редиректы: `java.net.http.HttpClient` по умолчанию их НЕ следует (`Redirect.NEVER`), а вот `RestTemplate`/Apache HttpClient часто следуют — там проверяй конечный URL.",
 "sp-autoconfig-imports": "⚠️ Частая путаница: `spring.factories` НЕ удалён целиком в Boot 3 — он жив для прочих расширений (`ApplicationListener`, `ApplicationContextInitializer`, `FailureAnalyzer`, `EnvironmentPostProcessor`). Убрана только регистрация автоконфигов через ключ `EnableAutoConfiguration`. Если апаешь свой стартер на Boot 3 и забыл создать `AutoConfiguration.imports` — бины автоконфига просто молча не появятся, без ошибки на старте.",
 "kc-realm-client-roles": "⚠️ Удаление или переименование client (его `clientId`) аннулирует все назначенные client roles и путь `resource_access.<clientId>` в токенах — старые сессии/токены ссылаются на исчезнувший клиент, а downstream-сервисы, матчащие роли по жёсткому `resource_access.api.roles`, молча перестают авторизовывать. Меняя clientId, синхронно правьте protocol mappers, audience и role-маппинг в потребителях.",
 "kc-public-confidential": "⚠️ Старая галка «Bearer-Only» убрана из новой модели клиента Keycloak. Если бэкенд-ресурс по ошибке оставить как обычный confidential со включённым Standard Flow + service accounts, он сможет инициировать логины и получать токены — лишняя поверхность атаки. Для чистого resource server выключайте Standard Flow, Direct Access Grants и Service Accounts: пусть он ТОЛЬКО валидирует входящий Bearer-токен. И помни: bearer-only клиент в принципе нельзя использовать для логина — у него нет своего flow, и Keycloak вернёт ошибку, если попытаться им инициировать authorization request.",
 "kc-roles-to-authorities": "⚠️ Client-роли видны в access-токене ТОЛЬКО если у клиента включён маппер ролей и роль попала в audience/resource_access. По умолчанию роли клиента A не появятся в токене, выписанном для клиента B — даже если у юзера они есть. Если ждёшь client-роль в resource_access, а её там нет, проверяй не код, а Client Scopes / mappers в Keycloak.",
 "kc-token-types": "⚠️ ID token НЕ предназначен для авторизации в ресурс-API: его `aud` = client_id, а не resource server, и в нём нет `realm_access.roles`/`scope`. Слать его в backend вместо access token — либо отказ по audience, либо молчаливо сломанная ролевая модель. В API идёт ТОЛЬКО access token.",
 "kc-audience-issuer": "⚠️ Если за резолвинг подписи отвечает один общий JWKS/trust на несколько realm (или принимаешь несколько issuer-ов), без жёсткого pin по iss токен из «соседнего» realm с легитимной для него подписью пройдёт валидацию. Подпись валидна — а realm чужой. Всегда фиксируй ожидаемый issuer явно.",
 "ops-red-use-golden": "⚠️ Алертить надо по СИМПТОМУ (RED/latency/errors — то, что чувствует юзер), а не по причине (CPU 90%). Высокий CPU сам по себе не инцидент, если латенси в норме; а p99 вверх при нормальном CPU — реальная проблема (ждём I/O, лок, GC). USE-метрики — для диагностики ПОСЛЕ срабатывания симптом-алерта, не для алертов.",
 "db-tsdb-compression": "⚠️ Практический вывод: НЕ храни в метриках высокоэнтропийные значения (случайные id, суммы до копейки, timestamps как значение) — они убивают Gorilla, точка раздувается с ~1-2 байт до 8+. И регулярный scrape-интервал критичен: рваные таймстемпы ломают delta-of-delta. Хаос в значениях/шаге = взрыв диска даже при малом числе точек.",
 "db-tsdb-downsampling": "⚠️ Downsampling теряет пики: секундный всплеск латенси растворяется в часовом average. Поэтому в rollup храни не только avg, но и max/min/p99 — иначе постфактум не увидишь старый инцидент. И считай квантили правильно: нельзя усреднять p99 по времени (среднее от перцентилей ≠ перцентиль) — для гистограмм агрегируй бакеты, а не готовый квантиль.",
 "ops-recording-alerting-rules": "⚠️ `for:` в alerting rule — против флаппинга: условие должно держаться N минут, иначе разовый спайк не разбудит дежурного зря. И алерть на burn-rate (recording rule по бюджету ошибок), а не на сырой error-rate: multi-window burn-rate (быстрое+медленное окно) ловит и резкие аварии, и медленную деградацию, не спамя. Сырой порог «errors>1%» либо молчит, либо орёт.",
 "sd-metrics-tsdb-scale": "⚠️ Шардируют по series (по хэшу метки), а НЕ по времени — иначе один «горячий» момент времени бьёт в один узел, а чтение ряда за период идёт по всем узлам. И dedup обязателен: две HA-реплики Prometheus шлют почти одинаковые точки со сдвигом; vmselect схлопывает их, иначе rate() удвоится. remote_write асинхронный с буфером — при недоступности бэкенда Prometheus копит в WAL, но переполнение = потеря свежих точек.",
 "tr-finally-return": "⚠️ Классическая ловушка код-ревью: `return`/`throw` в `finally` молча съедает исключение из `try` — самый коварный способ спрятать баг (ошибка «исчезает» без следа). Линтеры (SpotBugs) на это ругаются. В `finally` — только освобождение ресурсов, никаких выходов из метода.",
 "tr-list-remove-overload": "⚠️ Коварно тем, что на `List<String>` код работает «по значению», а при рефакторинге на `List<Integer>` та же строка `remove(x)` внезапно начинает удалять по индексу → тихий баг + возможный IndexOutOfBounds. Всегда явно оборачивай: `remove(Integer.valueOf(x))`.",
 "tr-incr-atomic": "⚠️ Ловушка: `volatile int count` выглядит «потокобезопасным», но `count++` всё равно теряет данные — volatile НЕ про атомарность read-modify-write. Для счётчиков бери `AtomicInteger`/`LongAdder`; `volatile` годится лишь для флагов (одна запись, много чтений).",
 "tr-hashmap-mt": "⚠️ Коварно: баг воспроизводится редко и «плавает» (зависит от тайминга и resize) — в проде под нагрузкой, а на тестах молчит. Правило: любой разделяемый между потоками Map — только `ConcurrentHashMap`. И не путай его атомарные методы (`compute`, `merge`) с неатомарной связкой `get`+`put`.",
 "tr-float-money": "⚠️ Двойная ловушка: (1) люди «чинят» деньги через `double` и теряют копейки в отчётах; (2) даже переходя на BigDecimal, пишут `new BigDecimal(0.1)` — и тащат ту же ошибку. Только `new BigDecimal(\"0.1\")` или `BigDecimal.valueOf(0.1)`. И задавай `scale`+`RoundingMode` явно.",
 "tr-fixed-pool-oom": "⚠️ Коварно тем, что на тестах и малой нагрузке всё идеально, а деградация приходит под пиком — очередь тихо копится, пока не прилетит OOM. Никогда не бери фабрики `Executors.*` в проде без оглядки; задавай лимит очереди и политику отказа осознанно.",
 "tr-static-hiding": "⚠️ Ловушка усиливается тем, что `p.who()` через ссылку компилируется и «выглядит полиморфно», но молча берёт версию по типу ссылки. Никогда не вызывай static через переменную-экземпляр; всегда `ClassName.method()`. И не жди от static переопределения — его нет.",
 "tr-ternary-promotion": "⚠️ Двойная ловушка: (1) молчаливое `1 → 1.0` ломает форматирование/сравнение; (2) `cond ? primitive : boxedNullable` даёт NPE «из ниоткуда». Не смешивай в ветках тернарника обёртку и примитив/разные числовые типы — приводи явно или используй if/else."
};
